INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C1','math',6,2,'u6',2,'원기둥의 뜻 — 각기둥·각뿔을 되짚고, 서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 원기둥이라 하며 직사각형을 한 변을 기준으로 한 바퀴 돌려 만들 수 있음을 알기',ARRAY['6수03-07']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C2','math',6,2,'u6',3,'원기둥의 구성 요소 — 서로 평행하고 합동인 두 원(밑면 2개), 두 밑면과 만나는 굽은 면(옆면), 두 밑면 사이의 거리(높이)를 알고 높이는 밑면에 수직으로 재기',ARRAY['6수03-07']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C3','math',6,2,'u6',4,'원기둥의 전개도 — 합동인 원 2개와 직사각형 1개로 이루어지고, 옆면의 가로는 밑면의 둘레((지름) × (원주율)), 세로는 원기둥의 높이와 같음을 알고 길이 구하기',ARRAY['6수03-08']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C4','math',6,2,'u6',5,'원기둥의 전개도 가려내기 — 옆면이 직사각형이고, 두 밑면이 서로 합동인 원이며, 옆면을 사이에 두고 마주 보는 위치에 있어야 전개도가 됨을 알기',ARRAY['6수03-08']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C5','math',6,2,'u6',6,'원뿔의 뜻 — 한 원을 면으로 하는 입체도형을 원뿔이라 하고, 직각삼각형을 직각을 낀 한 변을 기준으로 한 바퀴 돌려 만들 수 있으며 원기둥·각뿔과 구별하기',ARRAY['6수03-07']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C6','math',6,2,'u6',7,'원뿔의 구성 요소 — 밑면(1개)·옆면·원뿔의 꼭짓점·모선(꼭짓점과 밑면 둘레의 한 점을 이은 선분, 무수히 많고 길이가 같음)·높이(꼭짓점에서 밑면에 수직으로 내린 선분의 길이)를 알고 모선이 높이보다 긺을 알기',ARRAY['6수03-07']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C7','math',6,2,'u6',8,'구 — 반원을 지름을 기준으로 한 바퀴 돌려 만든 입체도형을 구라 하고, 구의 중심(1개)·구의 반지름(무수히 많고 길이가 같음)을 알며 원기둥·원뿔·구를 위·앞·옆에서 본 모양을 견주기',ARRAY['6수03-07']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C8','math',6,2,'u6',9,'앞에서 본 모양 — 원뿔은 삼각형(밑변 = 밑면의 지름, 높이 = 원뿔의 높이), 원기둥은 직사각형(가로 = 밑면의 지름, 세로 = 높이)임을 알고 넓이·둘레를 구하거나 넓이로 모르는 길이를 되짚기',ARRAY['6수03-07']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X01','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C5']::text[],'각기둥·각뿔과 원기둥·원뿔을 혼동한다(밑면이 다각형인지 원인지 보지 않는다)','밑면이 원인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X02','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C2','M6-2-u6-C4']::text[],'원기둥의 두 원이 서로 평행하고 합동이어야 한다는 조건 가운데 하나를 빠뜨린다','평행하고 합동인 두 원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X03','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C5','M6-2-u6-C7']::text[],'한 바퀴 돌려 만드는 평면도형을 혼동한다(직사각형→원기둥, 직각삼각형→원뿔, 반원→구)','무엇을 돌렸나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X04','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C5']::text[],'돌릴 때 막대에 붙인 변과 뻗어 나간 변의 역할(높이·밑면의 반지름)을 바꾸거나 반지름을 지름으로 본다','뻗은 변 = 반지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X05','math',6,'u6',ARRAY['M6-2-u6-C2','M6-2-u6-C6']::text[],'밑면을 「밑에 있는 면」으로만 보거나 원기둥(2개)·원뿔(1개)의 밑면 수를 혼동한다','원기둥 2개, 원뿔 1개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X06','math',6,'u6',ARRAY['M6-2-u6-C2']::text[],'원기둥의 높이를 비스듬히 재거나 밑면의 지름·옆면의 둘레와 혼동한다','밑면에 수직으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X07','math',6,'u6',ARRAY['M6-2-u6-C2','M6-2-u6-C6','M6-2-u6-C7']::text[],'원기둥·구에 꼭짓점·모서리가 있다고 보거나 원뿔의 꼭짓점 수를 잘못 센다','굽은 면엔 모서리가 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X08','math',6,'u6',ARRAY['M6-2-u6-C3']::text[],'전개도에서 옆면의 가로를 밑면의 지름이나 (반지름) × (원주율)로 본다','가로 = 밑면의 둘레') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X09','math',6,'u6',ARRAY['M6-2-u6-C3']::text[],'전개도에서 옆면의 가로와 세로가 원기둥의 어디와 같은지 바꾸어 본다','세로 = 높이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X10','math',6,'u6',ARRAY['M6-2-u6-C3']::text[],'옆면의 가로로 밑면의 지름·반지름을 구할 때 곱셈·나눗셈을 거꾸로 하거나 반지름과 지름을 혼동한다','가로 ÷ 3.14 = 지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X11','math',6,'u6',ARRAY['M6-2-u6-C4']::text[],'옆면이 직사각형이 아닌(기울어진) 그림도 원기둥의 전개도라고 본다','옆면은 직사각형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X12','math',6,'u6',ARRAY['M6-2-u6-C4']::text[],'두 밑면이 옆면의 같은 쪽에 있어 접으면 겹치는 것을 알아차리지 못한다','마주 보는 위치') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X13','math',6,'u6',ARRAY['M6-2-u6-C3','M6-2-u6-C4']::text[],'전개도의 밑면을 원 1개로, 또는 옆면을 원·삼각형으로 생각한다','원 2개 + 직사각형 1개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X14','math',6,'u6',ARRAY['M6-2-u6-C5','M6-2-u6-C6']::text[],'원기둥과 원뿔을 혼동한다(원이 두 개인지 한 개인지, 뾰족한 점이 있는지 보지 않는다)','원 하나·뾰족한 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X15','math',6,'u6',ARRAY['M6-2-u6-C6','M6-2-u6-C8']::text[],'원뿔의 모선과 높이를 혼동한다(모선을 높이로 쓰거나 높이가 모선보다 길다고 본다)','모선은 비스듬히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X16','math',6,'u6',ARRAY['M6-2-u6-C6']::text[],'원뿔의 모선이 하나뿐이라고 보거나 모선마다 길이가 다르다고 본다','모선은 무수히, 길이는 같게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X17','math',6,'u6',ARRAY['M6-2-u6-C7']::text[],'구의 반지름이 방향마다 다르다고 보거나 구의 중심이 여러 개라고 본다','중심 1개, 반지름은 모두 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X18','math',6,'u6',ARRAY['M6-2-u6-C7','M6-2-u6-C8']::text[],'원기둥·원뿔·구를 위·앞·옆에서 본 모양을 혼동한다','위에서는 모두 원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X19','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C2','M6-2-u6-C3','M6-2-u6-C4','M6-2-u6-C5','M6-2-u6-C6','M6-2-u6-C7','M6-2-u6-C8']::text[],'묻는 말을 거꾸로 읽는다 — 잘못된↔알맞은, 반지름↔지름, 아닌↔맞는','물음의 「잘못·아닌」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X20','math',6,'u6',ARRAY['M6-2-u6-C3','M6-2-u6-C8']::text[],'앞모양 넓이에서 삼각형의 ÷ 2를 빠뜨리거나 밑변을 반지름으로 두는 등 넓이·길이 계산을 잘못한다','삼각형은 ÷ 2') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X21','math',6,'u6',ARRAY['M6-2-u6-C6']::text[],'원뿔의 모선을 모서리라고 여긴다 — 모서리는 평면과 평면이 만나는 선분인데, 원뿔에는 평면이 밑면 하나뿐이라 모서리가 없다(지도서 368)','모서리 = 평면과 평면이 만나는 선분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X22','math',6,'u6',ARRAY['M6-2-u6-C7']::text[],'반쪽 공·달걀 모양처럼 둥글고 굽은 면이 있으면 모두 구라고 여긴다 — 구는 어느 방향에서 보아도 모양이 원으로 같아야 한다(지도서 349·372)','어느 방향에서 보아도 원인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X23','math',6,'u6',ARRAY['M6-2-u6-C3','M6-2-u6-C4']::text[],'원기둥의 전개도는 한 가지 모양뿐이라고 여겨, 밑면이 붙은 자리가 다른 친구의 전개도를 틀렸다고 한다 — 어디를 잘라 펼치느냐에 따라 여러 가지가 나온다(지도서 362·364)','자른 곳이 다르면 펼친 모양도 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_basic#1','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',1,'mc','auto','눈꽃 축제의 얼음 성 몸체처럼 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?',ARRAY['M6-2-u6-X01','M6-2-u6-X03']::text[],true,'{"seq":1,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"눈꽃 축제의 얼음 성 몸체처럼 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?","options":[{"t":"각기둥","correct":true},{"t":"각뿔","mis":"M6-2-u6-X01"},{"t":"원기둥","mis":"M6-2-u6-X01"},{"t":"구","mis":"M6-2-u6-X03"}],"explanation":["6학년 1학기에 배운 입체도형이에요.","두 면이 서로 평행하고 합동인 다각형인 입체도형은 각기둥이에요.","얼음 성 몸체는 사각기둥, 지붕은 사각뿔 모양이었어요."],"variant_rule":{"alt":[{"stem":"밑면이 오각형이고 옆면이 모두 삼각형인 입체도형의 이름은 무엇인가요?","options":[{"t":"오각뿔","correct":true},{"t":"오각기둥","mis":"M6-2-u6-X01"},{"t":"원뿔","mis":"M6-2-u6-X01"},{"t":"육각뿔","mis":"M6-2-u6-X19"}],"explanation":["옆면이 모두 삼각형이면 각뿔이에요.","각뿔의 이름은 밑면의 모양으로 붙여요.","밑면이 오각형이니 오각뿔이에요."]},{"stem":"밑면이 육각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"육각기둥","correct":true},{"t":"육각뿔","mis":"M6-2-u6-X01"},{"t":"원기둥","mis":"M6-2-u6-X01"},{"t":"오각기둥","mis":"M6-2-u6-X19"}],"explanation":["두 밑면이 서로 평행하고 합동인 다각형이면 각기둥이에요.","각기둥의 이름은 밑면의 모양으로 붙여요.","밑면이 육각형이니 육각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_basic#2','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',1,'mc','auto','각뿔에서 옆면이 모두 만나는 점을 무엇이라고 하나요?',ARRAY['M6-2-u6-X07','M6-2-u6-X05','M6-2-u6-X15']::text[],true,'{"seq":2,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"각뿔에서 옆면이 모두 만나는 점을 무엇이라고 하나요?","options":[{"t":"각뿔의 꼭짓점","correct":true},{"t":"모서리","mis":"M6-2-u6-X07"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X15"}],"explanation":["6학년 1학기에 배운 각뿔의 구성 요소를 떠올려요.","면과 면이 만나는 선분은 모서리, 옆면이 모두 만나는 점은 각뿔의 꼭짓점이에요.","꼭짓점에서 밑면에 수직으로 내린 선분의 길이가 높이예요."],"variant_rule":{"alt":[{"stem":"각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"모서리","mis":"M6-2-u6-X15"},{"t":"각뿔의 꼭짓점","mis":"M6-2-u6-X07"},{"t":"밑면","mis":"M6-2-u6-X05"}],"explanation":["6학년 1학기에 배운 각뿔의 구성 요소를 떠올려요.","면과 면이 만나는 선분은 모서리, 옆면이 모두 만나는 점은 각뿔의 꼭짓점이에요.","꼭짓점에서 밑면에 수직으로 내린 선분의 길이가 높이예요."]},{"stem":"각뿔에서 면과 면이 만나는 선분을 무엇이라고 하나요?","options":[{"t":"모서리","correct":true},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"각뿔의 꼭짓점","mis":"M6-2-u6-X07"}],"explanation":["6학년 1학기에 배운 각뿔의 구성 요소를 떠올려요.","면과 면이 만나는 선분은 모서리, 옆면이 모두 만나는 점은 각뿔의 꼭짓점이에요.","꼭짓점에서 밑면에 수직으로 내린 선분의 길이가 높이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_basic#3','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',1,'mc','auto','눈꽃 축제의 눈사람 모자는 둥근 기둥 모양이에요. 이 모자를 각기둥이라고 부를 수 없는 까닭은 무엇인가요?',ARRAY['M6-2-u6-X19','M6-2-u6-X06','M6-2-u6-X07']::text[],true,'{"seq":3,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"눈꽃 축제의 눈사람 모자는 둥근 기둥 모양이에요. 이 모자를 각기둥이라고 부를 수 없는 까닭은 무엇인가요?","options":[{"t":"두 밑면이 다각형이 아니라 원이라서","correct":true},{"t":"옆면이 굽어 있어서","mis":"M6-2-u6-X19"},{"t":"높이가 낮아서","mis":"M6-2-u6-X06"},{"t":"꼭짓점이 없어서","mis":"M6-2-u6-X07"}],"explanation":["각기둥의 두 밑면은 다각형이에요.","눈사람 모자의 두 밑면은 원이에요.","밑면이 다르니 각기둥이 아니라 새 이름이 필요해요."],"variant_rule":{"alt":[{"stem":"눈꽃 축제의 눈사람 코는 둥근 뿔 모양이에요. 이 코를 각뿔이라고 부를 수 없는 까닭은 무엇인가요?","options":[{"t":"면이 다각형이 아니라 원이라서","correct":true},{"t":"뾰족한 점이 있어서","mis":"M6-2-u6-X19"},{"t":"옆면이 삼각형이라서","mis":"M6-2-u6-X01"},{"t":"크기가 작아서","mis":"M6-2-u6-X19"}],"explanation":["각뿔의 밑면은 다각형이에요.","눈사람 코는 면이 원인 뿔 모양이에요.","그래서 각뿔이 아니라 새 이름(원뿔)이 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_basic#4','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',1,'mc','auto','서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 무엇이라고 하나요?',ARRAY['M6-2-u6-X01','M6-2-u6-X03','M6-2-u6-X14']::text[],true,'{"seq":4,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 무엇이라고 하나요?","options":[{"t":"원기둥","correct":true},{"t":"각기둥","mis":"M6-2-u6-X01"},{"t":"각뿔","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X14"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 원기둥이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."],"variant_rule":{"alt":[{"stem":"직사각형 모양의 종이를 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원기둥","correct":true},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원기둥이 만들어져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_basic#5','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'mc','auto','간식 통 가~바를 ① 서로 평행한 두 면이 있나요? ② 평행한 두 면이 서로 합동인가요? ③ 두 면이 원인가요? 차례로 물어 갈라냈어요. 가(위아래 두 원의 크기가 다른 통)는 몇 번 물음에서 「아니요」가 되나요?',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":5,"concept":"M6-2-u6-C1","difficulty":2,"kind":"mc","stem":"간식 통 가~바를 ① 서로 평행한 두 면이 있나요? ② 평행한 두 면이 서로 합동인가요? ③ 두 면이 원인가요? 차례로 물어 갈라냈어요. 가(위아래 두 원의 크기가 다른 통)는 몇 번 물음에서 「아니요」가 되나요?","options":[{"t":"② 평행한 두 면이 서로 합동인가요?","correct":true},{"t":"① 서로 평행한 두 면이 있나요?","mis":"M6-2-u6-X02"},{"t":"③ 두 면이 원인가요?","mis":"M6-2-u6-X02"},{"t":"세 물음에 모두 「예」","mis":"M6-2-u6-X02"}],"explanation":["물음을 하나씩 통과해야 다음 물음으로 가요.","가는 ② 평행한 두 면이 서로 합동인가요?에서 처음으로 「아니요」예요.","세 물음에 모두 「예」인 나·라·바가 원기둥이에요."],"variant_rule":{"alt":[{"stem":"간식 통 가~바를 ① 서로 평행한 두 면이 있나요? ② 평행한 두 면이 서로 합동인가요? ③ 두 면이 원인가요? 차례로 물어 갈라냈어요. 다(서로 평행하고 합동인 두 면이 삼각형인 상자)는 몇 번 물음에서 「아니요」가 되나요?","options":[{"t":"③ 두 면이 원인가요?","correct":true},{"t":"① 서로 평행한 두 면이 있나요?","mis":"M6-2-u6-X01"},{"t":"② 평행한 두 면이 서로 합동인가요?","mis":"M6-2-u6-X01"},{"t":"세 물음에 모두 「예」","mis":"M6-2-u6-X02"}],"explanation":["물음을 하나씩 통과해야 다음 물음으로 가요.","다는 ③ 두 면이 원인가요?에서 처음으로 「아니요」예요.","세 물음에 모두 「예」인 나·라·바가 원기둥이에요."]},{"stem":"간식 통 가~바를 ① 서로 평행한 두 면이 있나요? ② 평행한 두 면이 서로 합동인가요? ③ 두 면이 원인가요? 차례로 물어 갈라냈어요. 마(뾰족한 뿔 모양의 상자)는 몇 번 물음에서 「아니요」가 되나요?","options":[{"t":"① 서로 평행한 두 면이 있나요?","correct":true},{"t":"② 평행한 두 면이 서로 합동인가요?","mis":"M6-2-u6-X01"},{"t":"③ 두 면이 원인가요?","mis":"M6-2-u6-X01"},{"t":"세 물음에 모두 「예」","mis":"M6-2-u6-X02"}],"explanation":["물음을 하나씩 통과해야 다음 물음으로 가요.","마는 ① 서로 평행한 두 면이 있나요?에서 처음으로 「아니요」예요.","세 물음에 모두 「예」인 나·라·바가 원기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_basic#6','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'sa','auto','가 위아래 두 원의 크기가 다른 통 · 나 둥근 기둥 모양의 통 · 다 서로 평행하고 합동인 두 면이 삼각형인 상자 · 라 길쭉한 둥근 기둥 모양의 통 · 마 뾰족한 뿔 모양의 상자 · 바 납작한 둥근 기둥 모양의 통 — 이 가운데 원기둥은 몇 개인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가 위아래 두 원의 크기가 다른 통 · 나 둥근 기둥 모양의 통 · 다 서로 평행하고 합동인 두 면이 삼각형인 상자 · 라 길쭉한 둥근 기둥 모양의 통 · 마 뾰족한 뿔 모양의 상자 · 바 납작한 둥근 기둥 모양의 통 — 이 가운데 원기둥은 몇 개인가요?","answer":["3"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 나, 라, 바예요.","모두 3개예요."],"mis":"M6-2-u6-X02","variant_rule":{"alt":[{"stem":"가 서로 평행하고 합동인 두 면이 삼각형인 입체도형 · 나 둥근 기둥 모양의 입체도형 · 다 마주 보는 두 면이 원이지만 크기가 다른 입체도형 · 라 눕혀 놓은 둥근 기둥 모양의 입체도형 — 이 가운데 원기둥은 몇 개인가요?","answer":["2"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 나, 라예요.","모두 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_basic#7','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'mc','auto','『수학』 125쪽의 가는 서로 평행하고 합동인 두 면이 있는데도 원기둥이 아니에요. 까닭은 무엇인가요?',ARRAY['M6-2-u6-X02','M6-2-u6-X19','M6-2-u6-X06']::text[],true,'{"seq":7,"concept":"M6-2-u6-C1","difficulty":2,"kind":"mc","stem":"『수학』 125쪽의 가는 서로 평행하고 합동인 두 면이 있는데도 원기둥이 아니에요. 까닭은 무엇인가요?","options":[{"t":"서로 평행하고 합동인 두 면이 삼각형이라서","correct":true},{"t":"두 면이 서로 합동이 아니라서","mis":"M6-2-u6-X02"},{"t":"옆면이 굽어 있지 않아서","mis":"M6-2-u6-X19"},{"t":"높이를 잴 수 없어서","mis":"M6-2-u6-X06"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","가의 평행하고 합동인 두 면은 삼각형이에요.","그래서 가는 원기둥이 아니라 삼각기둥이에요."],"variant_rule":{"alt":[{"stem":"『수학』 125쪽의 다는 마주 보는 두 면이 모두 원인데도 원기둥이 아니에요. 까닭은 무엇인가요?","options":[{"t":"마주 보는 두 원이 서로 합동이 아니라서","correct":true},{"t":"두 면이 원이 아니라서","mis":"M6-2-u6-X01"},{"t":"뾰족한 점이 있어서","mis":"M6-2-u6-X14"},{"t":"옆면이 굽어 있어서","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 두 원은 서로 평행하고 합동이어야 해요.","다는 위쪽 원과 아래쪽 원의 크기가 달라요.","두 원이 합동이 아니면 원기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_basic#8','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'mc','auto','직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원기둥의 무엇이 되나요?',ARRAY['M6-2-u6-X04','M6-2-u6-X06']::text[],true,'{"seq":8,"concept":"M6-2-u6-C1","difficulty":2,"kind":"mc","stem":"직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원기둥의 무엇이 되나요?","options":[{"t":"높이","correct":true},{"t":"밑면의 반지름","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"밑면의 둘레","mis":"M6-2-u6-X06"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."],"variant_rule":{"alt":[{"stem":"직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에서 뻗어 나간 변은 만들어진 원기둥의 무엇이 되나요?","options":[{"t":"밑면의 반지름","correct":true},{"t":"높이","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"밑면의 둘레","mis":"M6-2-u6-X06"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_basic#9','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'ox','auto','두 면이 원이면 모두 원기둥이에요.',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":9,"concept":"M6-2-u6-C1","difficulty":2,"kind":"ox","stem":"두 면이 원이면 모두 원기둥이에요.","answer":"X","reason_options":[{"t":"두 원이 서로 평행하고 합동이어야 원기둥이기 때문에","correct":true},{"t":"원이 두 개 있으면 원기둥이라고 정했기 때문에","mis":"M6-2-u6-X02"}],"mis":"M6-2-u6-X02","explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."],"variant_rule":{"alt":[{"stem":"직사각형을 한 변을 기준으로 한 바퀴 돌리면 원기둥이 돼요.","answer":"O","reason_options":[{"t":"돌린 변은 높이, 뻗은 변은 밑면의 반지름이 되기 때문에","correct":true},{"t":"직사각형의 네 변이 모두 원이 되기 때문에","mis":"M6-2-u6-X03"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_basic#10','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',3,'sa','auto','가로 9 cm, 세로 4 cm인 직사각형을 길이가 9 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C1","difficulty":3,"kind":"sa","stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 9 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["기준으로 한 9 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 4 cm 변은 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 4 × 2 = 8 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 9 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 높이는 몇 cm인가요?","answer":["9"],"explanation":["기준으로 한 9 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 4 cm 변은 밑면의 반지름이 돼요.","그래서 높이는 9 cm예요."]},{"stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 4 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["18"],"explanation":["기준으로 한 4 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 9 cm 변은 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 9 × 2 = 18 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_challenge#1','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',2,'sa','auto','눈꽃 축제의 얼음 성은 몸체가 사각기둥, 맨 꼭대기 지붕이 사각뿔 모양이에요. 두 입체도형의 밑면의 수를 더하면 모두 몇 개인가요?','{}'::text[],false,'{"seq":1,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"눈꽃 축제의 얼음 성은 몸체가 사각기둥, 맨 꼭대기 지붕이 사각뿔 모양이에요. 두 입체도형의 밑면의 수를 더하면 모두 몇 개인가요?","answer":["3"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면 — 2개예요.","각뿔의 밑면은 1개예요.","2 + 1 = 3개예요."],"mis":"M6-2-u6-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_challenge#2','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',2,'mc','auto','가 위아래 두 원의 크기가 다른 통 · 나 둥근 기둥 모양의 통 · 다 서로 평행하고 합동인 두 면이 삼각형인 상자 · 라 길쭉한 둥근 기둥 모양의 통 · 마 뾰족한 뿔 모양의 상자 · 바 납작한 둥근 기둥 모양의 통 — 원기둥을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X02','M6-2-u6-X01']::text[],true,'{"seq":2,"concept":"M6-2-u6-C1","difficulty":2,"kind":"mc","stem":"가 위아래 두 원의 크기가 다른 통 · 나 둥근 기둥 모양의 통 · 다 서로 평행하고 합동인 두 면이 삼각형인 상자 · 라 길쭉한 둥근 기둥 모양의 통 · 마 뾰족한 뿔 모양의 상자 · 바 납작한 둥근 기둥 모양의 통 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"나, 라, 바","correct":true},{"t":"나, 라","mis":"M6-2-u6-X02"},{"t":"가, 나, 라, 바","mis":"M6-2-u6-X02"},{"t":"나, 다, 라, 바","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","나, 라, 바 모두 원기둥이에요."],"variant_rule":{"alt":[{"stem":"가 서로 평행하고 합동인 두 면이 삼각형인 입체도형 · 나 둥근 기둥 모양의 입체도형 · 다 마주 보는 두 면이 원이지만 크기가 다른 입체도형 · 라 눕혀 놓은 둥근 기둥 모양의 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나","mis":"M6-2-u6-X05"},{"t":"나, 다, 라","mis":"M6-2-u6-X02"},{"t":"가, 나, 라","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","나, 라 모두 원기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_challenge#3','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'error','auto','원기둥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X02','M6-2-u6-X19']::text[],false,'{"seq":3,"concept":"M6-2-u6-C1","difficulty":3,"kind":"error","stem":"원기둥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「두 면이 원이기만 하면 원기둥이야.」","correct":true,"mis_target":"M6-2-u6-X02"},{"t":"지석 — 「두 원은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「직사각형을 돌려서 만들 수 있어.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「밑면이 원이라 각기둥과는 이름이 달라.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥이 되려면 두 원이 서로 평행하고 합동이어야 해요.","위쪽 원이 더 작은 컵처럼 두 면이 원이어도 원기둥이 아닌 것이 있어요.","그래서 민지의 말이 잘못되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_challenge#4','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'match','auto','간식 통을 물음 차례로 갈라냈어요. 처음으로 「아니요」가 되는 물음과 그 통을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"M6-2-u6-C1","difficulty":3,"kind":"match","stem":"간식 통을 물음 차례로 갈라냈어요. 처음으로 「아니요」가 되는 물음과 그 통을 이으세요.","pairs":[{"l":"서로 평행한 두 면이 있나요?","r":"마 — 뾰족한 뿔 모양 상자"},{"l":"평행한 두 면이 서로 합동인가요?","r":"가 — 위아래 원의 크기가 다른 통"},{"l":"두 면이 원인가요?","r":"다 — 두 면이 삼각형인 상자"}],"mis":"M6-2-u6-X02","explanation":["마는 서로 평행한 두 면이 없어요.","가는 평행한 두 원의 크기가 달라 합동이 아니에요.","다는 평행하고 합동인 두 면이 삼각형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_challenge#5','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'sa','auto','가로 9 cm, 세로 4 cm인 직사각형 종이를 「한 변을 정하여 자유롭게」 막대에 붙였어요. 9 cm인 변을 붙여 돌린 원기둥과 4 cm인 변을 붙여 돌린 원기둥의 밑면의 지름의 차는 몇 cm인가요?','{}'::text[],false,'{"seq":5,"concept":"M6-2-u6-C1","difficulty":3,"kind":"sa","stem":"가로 9 cm, 세로 4 cm인 직사각형 종이를 「한 변을 정하여 자유롭게」 막대에 붙였어요. 9 cm인 변을 붙여 돌린 원기둥과 4 cm인 변을 붙여 돌린 원기둥의 밑면의 지름의 차는 몇 cm인가요?","answer":["10"],"explanation":["9 cm 변을 붙이면 뻗은 변 4 cm가 반지름 — 지름은 4 × 2 = 8 cm예요.","4 cm 변을 붙이면 뻗은 변 9 cm가 반지름 — 지름은 9 × 2 = 18 cm예요.","18 − 8 = 10 cm예요."],"mis":"M6-2-u6-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_challenge#6','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'ox','auto','원기둥과 각기둥은 모두 서로 평행하고 합동인 두 면이 있어요.',ARRAY['M6-2-u6-X01']::text[],true,'{"seq":6,"concept":"M6-2-u6-C1","difficulty":3,"kind":"ox","stem":"원기둥과 각기둥은 모두 서로 평행하고 합동인 두 면이 있어요.","answer":"O","reason_options":[{"t":"두 밑면이 서로 평행하고 합동이라는 점이 같기 때문에","correct":true},{"t":"원기둥과 각기둥은 밑면의 모양까지 같기 때문에","mis":"M6-2-u6-X01"}],"mis":"M6-2-u6-X01","explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."],"variant_rule":{"alt":[{"stem":"원기둥의 두 원은 서로 평행하고 합동이에요.","answer":"O","reason_options":[{"t":"원기둥은 서로 평행하고 합동인 두 원을 면으로 하기 때문에","correct":true},{"t":"원기둥의 두 원은 크기가 달라도 되기 때문에","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_challenge#7','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'mc','auto','「두 원이 비스듬히 잘려 서로 평행하지 않은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":7,"concept":"M6-2-u6-C1","difficulty":3,"kind":"mc","stem":"「두 원이 비스듬히 잘려 서로 평행하지 않은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 평행하지 않아서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 원이 비스듬히 잘려 서로 평행하지 않은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 평행하지 않아서 원기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「두 면이 서로 평행하고 합동인 육각형인 상자」는 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 면이 원이 아니라 다각형이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X01"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X01"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 서로 평행하고 합동인 육각형인 상자」를 이 조건에 하나씩 대어 봐요.","두 면이 원이 아니라 다각형이어서 원기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_challenge#8','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',4,'essay','teacher','『수학』 125쪽의 다는 마주 보는 두 면이 모두 원이에요. 다가 원기둥인지 아닌지 쓰고, 그 까닭을 원기둥의 뜻을 써서 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u6-C1","difficulty":4,"kind":"essay","stem":"『수학』 125쪽의 다는 마주 보는 두 면이 모두 원이에요. 다가 원기둥인지 아닌지 쓰고, 그 까닭을 원기둥의 뜻을 써서 설명해 보세요.","answer_guide":{"answer":"예: 다는 원기둥이 아니다. 원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형인데, 다는 마주 보는 두 원의 크기가 달라 서로 합동이 아니기 때문이다.","scoring_points":["원기둥이 아니라고 판단했는가","원기둥의 뜻(서로 평행하고 합동인 두 원)을 썼는가","두 원이 합동이 아니라는 까닭을 썼는가"]},"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","다는 두 원의 크기가 달라요.","합동이 아니니 원기둥이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_challenge#9','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',4,'sa','auto','가로 9 cm, 세로 4 cm인 직사각형을 길이가 4 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?','{}'::text[],false,'{"seq":9,"concept":"M6-2-u6-C1","difficulty":4,"kind":"sa","stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 4 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["22"],"explanation":["기준으로 한 4 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 9 cm 변은 밑면의 반지름이 돼요.","지름 18 cm와 높이 4 cm — 18 + 4 = 22 cm예요."],"mis":"M6-2-u6-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L02_challenge#10','math',6,2,'u6','L02','tb_g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',4,'essay','teacher','직사각형 모양의 종이를 막대에 붙이고 막대를 기준으로 한 바퀴 돌리면 왜 원기둥이 되는지, 막대에 붙인 변과 뻗어 나간 변이 각각 무엇이 되는지 넣어 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C1","difficulty":4,"kind":"essay","stem":"직사각형 모양의 종이를 막대에 붙이고 막대를 기준으로 한 바퀴 돌리면 왜 원기둥이 되는지, 막대에 붙인 변과 뻗어 나간 변이 각각 무엇이 되는지 넣어 설명해 보세요.","answer_guide":{"answer":"예: 막대에 붙인 변은 위아래로 곧게 서서 원기둥의 높이가 된다. 뻗어 나간 위쪽 변과 아래쪽 변은 길이가 같아 돌면서 크기가 같은 원을 그리므로, 서로 평행하고 합동인 두 원(밑면)이 생겨 원기둥이 된다. 뻗어 나간 변은 밑면의 반지름이 된다.","scoring_points":["막대에 붙인 변이 높이가 됨을 썼는가","뻗어 나간 변이 밑면의 반지름이 됨을 썼는가","위아래에 서로 평행하고 합동인 두 원이 생김을 썼는가"]},"explanation":["붙인 변 = 높이예요.","뻗은 변 = 밑면의 반지름이에요.","위아래 변이 같은 원을 그려 합동인 두 밑면이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_basic#1','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',1,'mc','auto','원기둥에서 서로 평행하고 합동인 두 원을 무엇이라고 하나요?',ARRAY['M6-2-u6-X05','M6-2-u6-X06','M6-2-u6-X15']::text[],true,'{"seq":1,"concept":"M6-2-u6-C2","difficulty":1,"kind":"mc","stem":"원기둥에서 서로 평행하고 합동인 두 원을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","서로 평행하고 합동인 두 원을 밑면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."],"variant_rule":{"alt":[{"stem":"원기둥에서 두 밑면과 만나는 굽은 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면과 만나는 굽은 면을 옆면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]},{"stem":"원기둥에서 두 밑면 사이의 거리를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면 사이의 거리를 높이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_basic#2','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',1,'mc','auto','원기둥 모형에서 서로 평행하고 합동인 두 원을 색칠하고, 색칠한 두 원과 만나는 면을 찾았어요. 그 면은 어떤 면인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X01']::text[],false,'{"seq":2,"concept":"M6-2-u6-C2","difficulty":1,"kind":"mc","stem":"원기둥 모형에서 서로 평행하고 합동인 두 원을 색칠하고, 색칠한 두 원과 만나는 면을 찾았어요. 그 면은 어떤 면인가요?","options":[{"t":"굽은 면","correct":true},{"t":"평평한 직사각형 면","mis":"M6-2-u6-X05"},{"t":"평평한 원","mis":"M6-2-u6-X05"},{"t":"삼각형 면","mis":"M6-2-u6-X01"}],"explanation":["색칠한 두 원은 밑면이에요.","두 밑면과 만나는 면을 손으로 쓸어 보면 둥글게 굽어 있어요.","이 굽은 면을 옆면이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_basic#3','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',1,'sa','auto','원기둥의 밑면은 모두 몇 개인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u6-C2","difficulty":1,"kind":"sa","stem":"원기둥의 밑면은 모두 몇 개인가요?","answer":["2"],"explanation":["원기둥을 손에 들고 면을 하나씩 짚어 봐요.","원기둥의 밑면은 서로 평행하고 합동인 두 원 — 2개예요.","각기둥처럼 옆면이 여러 개로 나뉘지 않아요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"원기둥의 옆면은 모두 몇 개인가요?","answer":["1"],"explanation":["원기둥을 손에 들고 면을 하나씩 짚어 봐요.","원기둥의 옆면은 굽은 면 하나예요.","각기둥처럼 옆면이 여러 개로 나뉘지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_basic#4','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',1,'sa','auto','『수학익힘』 87쪽의 통조림은 원기둥 모양이에요. 밑면의 지름이 8 cm이고 두 밑면 사이의 거리가 3 cm예요. 이 통조림의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C2","difficulty":1,"kind":"sa","stem":"『수학익힘』 87쪽의 통조림은 원기둥 모양이에요. 밑면의 지름이 8 cm이고 두 밑면 사이의 거리가 3 cm예요. 이 통조림의 높이는 몇 cm인가요?","answer":["3"],"explanation":["원기둥의 높이는 두 밑면 사이의 거리예요.","밑면의 지름 8 cm는 높이가 아니에요.","그래서 높이는 3 cm예요."],"mis":"M6-2-u6-X06","variant_rule":{"alt":[{"stem":"단원 평가 — 밑면의 지름이 6 cm이고 두 밑면 사이의 거리가 4 cm인 원기둥이 있어요. 이 원기둥의 높이는 몇 cm인가요?","answer":["4"],"explanation":["높이는 두 밑면 사이의 거리예요.","밑면의 지름 6 cm는 높이와 상관없어요.","그래서 높이는 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_basic#5','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'mc','auto','원기둥의 높이를 재는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X06']::text[],true,'{"seq":5,"concept":"M6-2-u6-C2","difficulty":2,"kind":"mc","stem":"원기둥의 높이를 재는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"자와 삼각자를 밑면에 수직으로 대어 두 밑면 사이의 거리를 재요","correct":true},{"t":"밑면의 지름을 재요","mis":"M6-2-u6-X06"},{"t":"옆면을 따라 비스듬히 줄자를 대어 재요","mis":"M6-2-u6-X06"},{"t":"밑면의 둘레를 재요","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."],"variant_rule":{"alt":[{"stem":"원기둥의 높이를 비스듬히 재면 어떻게 되나요?","options":[{"t":"두 밑면 사이의 거리보다 길게 나와요","correct":true},{"t":"두 밑면 사이의 거리보다 짧게 나와요","mis":"M6-2-u6-X06"},{"t":"언제나 같은 값이 나와요","mis":"M6-2-u6-X06"},{"t":"밑면의 지름과 같아져요","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_basic#6','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'sa','auto','『수학익힘』 87쪽의 원기둥 모양 물건이 눕혀 놓여 있어요. 밑면의 지름은 6 cm이고, 두 밑면 사이의 거리는 12 cm예요. 이 물건의 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":6,"concept":"M6-2-u6-C2","difficulty":2,"kind":"sa","stem":"『수학익힘』 87쪽의 원기둥 모양 물건이 눕혀 놓여 있어요. 밑면의 지름은 6 cm이고, 두 밑면 사이의 거리는 12 cm예요. 이 물건의 높이는 몇 cm인가요?","answer":["12"],"explanation":["눕혀 놓아도 서로 평행하고 합동인 두 원이 밑면이에요.","높이는 두 밑면 사이의 거리예요 — 바닥에서 위까지의 길이가 아니에요.","그래서 높이는 12 cm예요."],"mis":"M6-2-u6-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_basic#7','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'ox','auto','원기둥의 밑면은 언제나 아래쪽에 있는 면 하나예요.',ARRAY['M6-2-u6-X05']::text[],true,'{"seq":7,"concept":"M6-2-u6-C2","difficulty":2,"kind":"ox","stem":"원기둥의 밑면은 언제나 아래쪽에 있는 면 하나예요.","answer":"X","reason_options":[{"t":"밑면은 「기본이 되는 면」 — 서로 평행하고 합동인 두 원 모두 밑면이기 때문에","correct":true},{"t":"밑면이라는 이름처럼 밑에 있는 면만 밑면이기 때문에","mis":"M6-2-u6-X05"}],"mis":"M6-2-u6-X05","explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."],"variant_rule":{"alt":[{"stem":"원기둥을 눕혀 놓으면 밑면이 옆면이 돼요.","answer":"X","reason_options":[{"t":"놓는 방향과 상관없이 평행하고 합동인 두 원이 밑면이기 때문에","correct":true},{"t":"아래에 닿은 면만 밑면이기 때문에","mis":"M6-2-u6-X05"}],"explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_basic#8','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'sa','auto','밑면의 반지름이 4 cm이고 높이가 8 cm인 원기둥이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C2","difficulty":2,"kind":"sa","stem":"밑면의 반지름이 4 cm이고 높이가 8 cm인 원기둥이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["16"],"explanation":["밑면의 지름은 4 × 2 = 8 cm예요.","높이는 8 cm예요.","8 + 8 = 16 cm예요."],"mis":"M6-2-u6-X19","variant_rule":{"alt":[{"stem":"밑면의 반지름이 3 cm이고 높이가 5 cm인 원기둥이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["11"],"explanation":["밑면의 지름은 3 × 2 = 6 cm예요.","높이는 5 cm예요.","6 + 5 = 11 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_basic#9','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'error','auto','원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X07','M6-2-u6-X19']::text[],false,'{"seq":9,"concept":"M6-2-u6-C2","difficulty":2,"kind":"error","stem":"원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"민지 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"지석 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 여울의 말이 잘못되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_basic#10','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',3,'ox','auto','『수학익힘』 87쪽 — 두 밑면이 서로 평행하지 않은 통도 두 면이 원이면 원기둥이에요.',ARRAY['M6-2-u6-X02']::text[],false,'{"seq":10,"concept":"M6-2-u6-C2","difficulty":3,"kind":"ox","stem":"『수학익힘』 87쪽 — 두 밑면이 서로 평행하지 않은 통도 두 면이 원이면 원기둥이에요.","answer":"X","reason_options":[{"t":"원기둥의 두 밑면은 서로 평행하고 합동이어야 하기 때문에","correct":true},{"t":"두 면이 원이기만 하면 원기둥이기 때문에","mis":"M6-2-u6-X02"}],"mis":"M6-2-u6-X02","explanation":["원기둥의 두 밑면은 서로 평행하고 합동이에요.","두 밑면이 평행하지 않으면 그 조건을 어겨요.","그래서 원기둥이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_challenge#1','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',3,'match','auto','원기둥에 대해 알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C2","difficulty":3,"kind":"match","stem":"원기둥에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"서로 평행하고 합동인 두 원","r":"밑면"},{"l":"두 밑면과 만나는 굽은 면","r":"옆면"},{"l":"두 밑면 사이의 거리","r":"높이"}],"mis":"M6-2-u6-X05","explanation":["밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 굽은 면 하나예요.","높이는 두 밑면 사이의 거리이고 꼭짓점은 없어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"원기둥의 밑면의 수","r":"2개"},{"l":"원기둥의 옆면의 수","r":"1개"},{"l":"원기둥의 꼭짓점의 수","r":"0개"}],"explanation":["밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 굽은 면 하나예요.","높이는 두 밑면 사이의 거리이고 꼭짓점은 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_challenge#2','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',2,'mc','auto','교실에서 원기둥 모양의 물건을 찾았어요. 원기둥 모양이 아닌 것은 어느 것인가요?',ARRAY['M6-2-u6-X02']::text[],false,'{"seq":2,"concept":"M6-2-u6-C2","difficulty":2,"kind":"mc","stem":"교실에서 원기둥 모양의 물건을 찾았어요. 원기둥 모양이 아닌 것은 어느 것인가요?","options":[{"t":"네모난 지우개","correct":true},{"t":"고체 풀","mis":"M6-2-u6-X02"},{"t":"보온병","mis":"M6-2-u6-X02"},{"t":"음료수 캔","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","고체 풀·보온병·캔은 위아래가 합동인 원이에요.","네모난 지우개는 밑면이 사각형인 각기둥 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_challenge#3','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',3,'mc','auto','원기둥과 각기둥의 같은 점은 어느 것인가요?',ARRAY['M6-2-u6-X01','M6-2-u6-X07']::text[],true,'{"seq":3,"concept":"M6-2-u6-C2","difficulty":3,"kind":"mc","stem":"원기둥과 각기둥의 같은 점은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 밑면이 있어요","correct":true},{"t":"밑면의 모양이 같아요","mis":"M6-2-u6-X01"},{"t":"옆면이 모두 직사각형이에요","mis":"M6-2-u6-X01"},{"t":"꼭짓점이 있어요","mis":"M6-2-u6-X07"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."],"variant_rule":{"alt":[{"stem":"원기둥과 각기둥의 다른 점은 어느 것인가요?","options":[{"t":"밑면이 원기둥은 원, 각기둥은 다각형이에요","correct":true},{"t":"원기둥은 밑면이 1개, 각기둥은 2개예요","mis":"M6-2-u6-X05"},{"t":"원기둥은 높이가 없어요","mis":"M6-2-u6-X06"},{"t":"원기둥은 두 밑면이 평행하지 않아요","mis":"M6-2-u6-X02"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."]},{"stem":"원기둥에는 없고 각기둥에는 있는 것은 어느 것인가요?","options":[{"t":"모서리와 꼭짓점","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_challenge#4','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',3,'mc','auto','원기둥의 높이를 자와 삼각자 대신 더 간편하게 잴 수 있는 도구는 어느 것인가요?',ARRAY['M6-2-u6-X06']::text[],false,'{"seq":4,"concept":"M6-2-u6-C2","difficulty":3,"kind":"mc","stem":"원기둥의 높이를 자와 삼각자 대신 더 간편하게 잴 수 있는 도구는 어느 것인가요?","options":[{"t":"곱자 또는 직각자","correct":true},{"t":"줄자로 옆면을 비스듬히 감아 재요","mis":"M6-2-u6-X06"},{"t":"각도기","mis":"M6-2-u6-X06"},{"t":"컴퍼스로 밑면의 지름을 재요","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요.","곱자나 직각자는 직각이 있어 수직을 바로 맞출 수 있어요.","그래서 곱자·직각자로 간편하게 잴 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_challenge#5','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',3,'ox','auto','원기둥에는 모서리가 없어요.',ARRAY['M6-2-u6-X07']::text[],true,'{"seq":5,"concept":"M6-2-u6-C2","difficulty":3,"kind":"ox","stem":"원기둥에는 모서리가 없어요.","answer":"O","reason_options":[{"t":"평평한 면끼리 만나는 선분이 없기 때문에","correct":true},{"t":"원기둥의 모서리는 2개이기 때문에","mis":"M6-2-u6-X07"}],"mis":"M6-2-u6-X07","explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."],"variant_rule":{"alt":[{"stem":"원기둥의 높이는 밑면의 지름과 언제나 같아요.","answer":"X","reason_options":[{"t":"높이는 두 밑면 사이의 거리라 지름과 따로 정해지기 때문에","correct":true},{"t":"원기둥은 높이와 지름이 같은 도형이기 때문에","mis":"M6-2-u6-X06"}],"explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_challenge#6','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',2,'sa','auto','『수학익힘』 87쪽 — 통조림은 밑면의 지름이 8 cm, 높이가 3 cm예요. 눕혀 놓은 원기둥 모양 물건은 밑면의 지름이 6 cm, 두 밑면 사이의 거리가 12 cm예요. 두 물건의 높이의 합은 몇 cm인가요?','{}'::text[],false,'{"seq":6,"concept":"M6-2-u6-C2","difficulty":2,"kind":"sa","stem":"『수학익힘』 87쪽 — 통조림은 밑면의 지름이 8 cm, 높이가 3 cm예요. 눕혀 놓은 원기둥 모양 물건은 밑면의 지름이 6 cm, 두 밑면 사이의 거리가 12 cm예요. 두 물건의 높이의 합은 몇 cm인가요?","answer":["15"],"explanation":["통조림의 높이는 두 밑면 사이의 거리 3 cm예요.","눕힌 물건도 높이는 두 밑면 사이의 거리 12 cm예요 — 지름 6 cm가 아니에요.","3 + 12 = 15 cm예요."],"mis":"M6-2-u6-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_challenge#7','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',3,'sa','auto','밑면의 지름이 6 cm이고 높이가 12 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?','{}'::text[],false,'{"seq":7,"concept":"M6-2-u6-C2","difficulty":3,"kind":"sa","stem":"밑면의 지름이 6 cm이고 높이가 12 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?","answer":["15"],"explanation":["밑면의 반지름은 6 ÷ 2 = 3 cm예요.","높이는 12 cm예요.","3 + 12 = 15 cm예요."],"mis":"M6-2-u6-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_challenge#8','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',4,'essay','teacher','『수학익힘』 87쪽 — 두 밑면이 서로 평행하지 않은 통이 있어요. 이 통이 원기둥인지 알맞은 말에 ○표 하듯 답하고 까닭을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u6-C2","difficulty":4,"kind":"essay","stem":"『수학익힘』 87쪽 — 두 밑면이 서로 평행하지 않은 통이 있어요. 이 통이 원기둥인지 알맞은 말에 ○표 하듯 답하고 까닭을 써 보세요.","answer_guide":{"answer":"예: 원기둥이 아닙니다. 원기둥의 두 밑면은 서로 평행하고 합동이어야 하는데, 이 통은 두 밑면이 서로 평행하지 않기 때문입니다.","scoring_points":["원기둥이 아니라고 답했는가","원기둥의 두 밑면의 특징(평행·합동)을 썼는가","두 밑면이 평행하지 않다는 까닭을 썼는가"]},"explanation":["원기둥의 두 밑면은 서로 평행하고 합동이에요.","이 통은 두 밑면이 평행하지 않아요.","그래서 원기둥이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_challenge#9','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',4,'essay','teacher','원기둥을 눕혀 놓았더니 친구가 「바닥에 닿은 옆면이 밑면이 되고, 바닥에서 위까지의 길이가 높이야.」라고 말했어요. 친구의 말을 바르게 고치고 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u6-C2","difficulty":4,"kind":"essay","stem":"원기둥을 눕혀 놓았더니 친구가 「바닥에 닿은 옆면이 밑면이 되고, 바닥에서 위까지의 길이가 높이야.」라고 말했어요. 친구의 말을 바르게 고치고 까닭을 써 보세요.","answer_guide":{"answer":"예: 눕혀 놓아도 밑면은 서로 평행하고 합동인 두 원이다. 밑면은 「밑에 있는 면」이 아니라 「기본이 되는 면」이다. 높이는 두 밑면 사이의 거리이므로 놓는 방향과 상관없이 같다.","scoring_points":["밑면은 여전히 두 원이라고 고쳤는가","밑면이 기본이 되는 면이라는 뜻을 썼는가","높이는 두 밑면 사이의 거리라고 썼는가"]},"explanation":["밑면 = 서로 평행하고 합동인 두 원이에요.","놓는 방향이 바뀌어도 밑면은 그대로예요.","높이 = 두 밑면 사이의 거리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L03_challenge#10','math',6,2,'u6','L03','tb_g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',4,'sa','auto','밑면의 반지름이 4 cm, 높이가 8 cm인 원기둥과 밑면의 반지름이 3 cm, 높이가 5 cm인 원기둥이 있어요. 두 원기둥의 밑면의 지름의 합은 몇 cm인가요?','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C2","difficulty":4,"kind":"sa","stem":"밑면의 반지름이 4 cm, 높이가 8 cm인 원기둥과 밑면의 반지름이 3 cm, 높이가 5 cm인 원기둥이 있어요. 두 원기둥의 밑면의 지름의 합은 몇 cm인가요?","answer":["14"],"explanation":["반지름 4 cm인 원기둥의 지름은 4 × 2 = 8 cm예요.","반지름 3 cm인 원기둥의 지름은 3 × 2 = 6 cm예요.","8 + 6 = 14 cm예요 — 높이는 쓰지 않아요."],"mis":"M6-2-u6-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_basic#1','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',1,'mc','auto','원기둥의 모든 면이 이어지도록 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?',ARRAY['M6-2-u6-X13']::text[],true,'{"seq":1,"concept":"M6-2-u6-C3","difficulty":1,"kind":"mc","stem":"원기둥의 모든 면이 이어지도록 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?","options":[{"t":"원기둥의 전개도","correct":true},{"t":"원기둥의 겨냥도","mis":"M6-2-u6-X13"},{"t":"원기둥의 밑면","mis":"M6-2-u6-X13"},{"t":"원기둥의 옆면","mis":"M6-2-u6-X13"}],"explanation":["입체도형을 잘라 평면 위에 펼친 그림이 전개도예요.","겨냥도는 입체도형의 모양을 잘 알 수 있게 그린 그림이에요.","그래서 원기둥의 전개도예요."],"variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 밑면과 옆면은 각각 어떤 도형인가요?","options":[{"t":"밑면은 원, 옆면은 직사각형","correct":true},{"t":"밑면은 직사각형, 옆면은 원","mis":"M6-2-u6-X09"},{"t":"밑면은 원, 옆면은 삼각형","mis":"M6-2-u6-X13"},{"t":"밑면과 옆면 모두 원","mis":"M6-2-u6-X13"}],"explanation":["밑면은 원기둥의 두 원이에요.","굽은 옆면을 잘라 펼치면 직사각형이 돼요.","그래서 밑면은 원, 옆면은 직사각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_basic#2','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',1,'mc','auto','대나무 칫솔이 담긴 원기둥 모양 상자를 잘라서 펼쳤어요. 원기둥의 밑면의 둘레와 맞닿는 부분을 빨간색으로 표시하면 전개도의 어디에 칠하게 되나요?',ARRAY['M6-2-u6-X09','M6-2-u6-X08']::text[],true,'{"seq":2,"concept":"M6-2-u6-C3","difficulty":1,"kind":"mc","stem":"대나무 칫솔이 담긴 원기둥 모양 상자를 잘라서 펼쳤어요. 원기둥의 밑면의 둘레와 맞닿는 부분을 빨간색으로 표시하면 전개도의 어디에 칠하게 되나요?","options":[{"t":"옆면의 가로","correct":true},{"t":"옆면의 세로","mis":"M6-2-u6-X09"},{"t":"밑면의 지름","mis":"M6-2-u6-X08"},{"t":"밑면의 반지름","mis":"M6-2-u6-X08"}],"explanation":["옆면을 다시 감으면 위아래 테두리가 밑면의 둘레에 맞닿아요.","그 테두리가 펼친 직사각형의 가로예요.","그래서 빨간색은 옆면의 가로에 칠해요."],"variant_rule":{"alt":[{"stem":"대나무 칫솔 상자의 전개도에서 원기둥의 높이와 길이가 같은 부분을 파란색으로 표시하면 어디에 칠하게 되나요?","options":[{"t":"옆면의 세로","correct":true},{"t":"옆면의 가로","mis":"M6-2-u6-X09"},{"t":"밑면의 둘레","mis":"M6-2-u6-X09"},{"t":"밑면의 지름","mis":"M6-2-u6-X09"}],"explanation":["옆면의 세로는 두 밑면 사이를 이어요.","두 밑면 사이의 거리가 원기둥의 높이예요.","그래서 파란색은 옆면의 세로에 칠해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_basic#3','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',1,'mc','auto','원기둥의 전개도에서 옆면의 가로는 원기둥의 무엇과 길이가 같나요?',ARRAY['M6-2-u6-X08','M6-2-u6-X09']::text[],true,'{"seq":3,"concept":"M6-2-u6-C3","difficulty":1,"kind":"mc","stem":"원기둥의 전개도에서 옆면의 가로는 원기둥의 무엇과 길이가 같나요?","options":[{"t":"밑면의 둘레","correct":true},{"t":"밑면의 지름","mis":"M6-2-u6-X08"},{"t":"원기둥의 높이","mis":"M6-2-u6-X09"},{"t":"밑면의 반지름","mis":"M6-2-u6-X08"}],"explanation":["옆면을 다시 감아 붙이면 위쪽 테두리가 밑면의 둘레에 딱 맞아야 해요.","그래서 옆면의 가로는 밑면의 둘레와 같아요.","지름이 아니라 둘레예요."],"variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 세로는 원기둥의 무엇과 길이가 같나요?","options":[{"t":"원기둥의 높이","correct":true},{"t":"밑면의 둘레","mis":"M6-2-u6-X09"},{"t":"밑면의 지름","mis":"M6-2-u6-X09"},{"t":"밑면의 반지름","mis":"M6-2-u6-X09"}],"explanation":["옆면의 세로는 두 밑면 사이를 이어요.","두 밑면 사이의 거리가 원기둥의 높이예요.","그래서 옆면의 세로는 높이와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_basic#4','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',1,'mc','auto','원기둥의 전개도는 어떤 도형 몇 개로 이루어져 있나요?',ARRAY['M6-2-u6-X13','M6-2-u6-X02']::text[],false,'{"seq":4,"concept":"M6-2-u6-C3","difficulty":1,"kind":"mc","stem":"원기둥의 전개도는 어떤 도형 몇 개로 이루어져 있나요?","options":[{"t":"합동인 원 2개와 직사각형 1개","correct":true},{"t":"원 1개와 직사각형 1개","mis":"M6-2-u6-X13"},{"t":"합동인 원 2개와 직사각형 2개","mis":"M6-2-u6-X13"},{"t":"크기가 다른 원 2개와 직사각형 1개","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 밑면은 서로 합동인 원 2개예요.","옆면은 굽은 면 하나 — 펼치면 직사각형 1개예요.","그래서 합동인 원 2개와 직사각형 1개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_basic#5','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',2,'mc','auto','밑면의 반지름이 4 cm, 높이가 8 cm인 원기둥의 전개도를 그렸어요. 옆면의 가로는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":5,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"밑면의 반지름이 4 cm, 높이가 8 cm인 원기둥의 전개도를 그렸어요. 옆면의 가로는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"8 cm","mis":"M6-2-u6-X08"},{"t":"12.56 cm","mis":"M6-2-u6-X08"},{"t":"50.24 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 4 cm의 2배 — 지름은 8 cm예요.","8 × 3.14 = 25.12 cm예요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 4 cm, 높이가 6 cm인 원기둥의 전개도를 그렸어요. 옆면의 가로는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"8 cm","mis":"M6-2-u6-X08"},{"t":"12.56 cm","mis":"M6-2-u6-X08"},{"t":"50.24 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 4 cm의 2배 — 지름은 8 cm예요.","8 × 3.14 = 25.12 cm예요."]},{"stem":"밑면의 반지름이 5 cm, 높이가 11 cm인 원기둥의 전개도를 그렸어요. 옆면의 가로는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"10 cm","mis":"M6-2-u6-X08"},{"t":"15.7 cm","mis":"M6-2-u6-X08"},{"t":"62.8 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 5 cm의 2배 — 지름은 10 cm예요.","10 × 3.14 = 31.4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_basic#6','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',2,'sa','auto','밑면의 반지름이 4 cm, 높이가 8 cm인 원기둥의 전개도에서 옆면의 세로는 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"밑면의 반지름이 4 cm, 높이가 8 cm인 원기둥의 전개도에서 옆면의 세로는 몇 cm인가요?","answer":["8"],"explanation":["옆면의 세로는 두 밑면 사이를 이어요.","두 밑면 사이의 거리가 원기둥의 높이예요.","그래서 옆면의 세로는 높이와 같은 8 cm예요."],"mis":"M6-2-u6-X09","variant_rule":{"alt":[{"stem":"밑면의 반지름이 4 cm, 높이가 6 cm인 원기둥의 전개도에서 옆면의 세로는 몇 cm인가요?","answer":["6"],"explanation":["옆면의 세로는 두 밑면 사이를 이어요.","두 밑면 사이의 거리가 원기둥의 높이예요.","그래서 옆면의 세로는 높이와 같은 6 cm예요."]},{"stem":"밑면의 반지름이 5 cm, 높이가 11 cm인 원기둥의 전개도에서 옆면의 세로는 몇 cm인가요?","answer":["11"],"explanation":["옆면의 세로는 두 밑면 사이를 이어요.","두 밑면 사이의 거리가 원기둥의 높이예요.","그래서 옆면의 세로는 높이와 같은 11 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_basic#7','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',2,'mc','auto','『수학』 128쪽 — 밑면의 반지름이 3 cm, 높이가 5 cm인 원기둥과 그 전개도를 보고 표를 완성했어요. (밑면의 지름, 옆면의 가로, 옆면의 세로)로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X09']::text[],false,'{"seq":7,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"『수학』 128쪽 — 밑면의 반지름이 3 cm, 높이가 5 cm인 원기둥과 그 전개도를 보고 표를 완성했어요. (밑면의 지름, 옆면의 가로, 옆면의 세로)로 알맞은 것은 어느 것인가요?","options":[{"t":"6 cm, 18.84 cm, 5 cm","correct":true},{"t":"3 cm, 9.42 cm, 5 cm","mis":"M6-2-u6-X08"},{"t":"6 cm, 6 cm, 5 cm","mis":"M6-2-u6-X08"},{"t":"6 cm, 5 cm, 18.84 cm","mis":"M6-2-u6-X09"}],"explanation":["밑면의 지름은 3 × 2 = 6 cm예요.","옆면의 가로는 밑면의 둘레 — 6 × 3.14 = 18.84 cm예요.","옆면의 세로는 높이 5 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_basic#8','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',2,'mc','auto','밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로를 바르게 구한 식은 어느 것인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":8,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로를 바르게 구한 식은 어느 것인가요?","options":[{"t":"4 × 2 × 3.14","correct":true},{"t":"4 × 3.14","mis":"M6-2-u6-X08"},{"t":"4 ÷ 3.14","mis":"M6-2-u6-X10"},{"t":"4 × 2","mis":"M6-2-u6-X08"}],"explanation":["옆면의 가로는 밑면의 둘레 — (지름) × 3.14예요.","반지름에 2를 먼저 곱해 지름을 만들어요.","그래서 4 × 2 × 3.14예요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 3 cm인 원기둥의 전개도에서 옆면의 가로를 바르게 구한 식은 어느 것인가요?","options":[{"t":"3 × 2 × 3.14","correct":true},{"t":"3 × 3.14","mis":"M6-2-u6-X08"},{"t":"3 ÷ 3.14","mis":"M6-2-u6-X10"},{"t":"3 × 2","mis":"M6-2-u6-X08"}],"explanation":["옆면의 가로는 밑면의 둘레 — (지름) × 3.14예요.","반지름에 2를 먼저 곱해 지름을 만들어요.","그래서 3 × 2 × 3.14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_basic#9','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',2,'ox','auto','원기둥의 전개도에서 옆면의 가로는 밑면의 지름과 같아요.',ARRAY['M6-2-u6-X08']::text[],true,'{"seq":9,"concept":"M6-2-u6-C3","difficulty":2,"kind":"ox","stem":"원기둥의 전개도에서 옆면의 가로는 밑면의 지름과 같아요.","answer":"X","reason_options":[{"t":"옆면을 감으면 가로가 밑면의 둘레를 한 바퀴 두르기 때문에","correct":true},{"t":"옆면의 가로가 밑면을 가로지르기 때문에","mis":"M6-2-u6-X08"}],"mis":"M6-2-u6-X08","explanation":["원기둥의 전개도는 합동인 원 2개와 직사각형 1개예요.","옆면의 가로는 밑면의 둘레, 세로는 높이예요.","(밑면의 둘레) = (지름) × 3.14예요."],"variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 세로는 원기둥의 높이와 같아요.","answer":"O","reason_options":[{"t":"세로가 두 밑면 사이를 잇기 때문에","correct":true},{"t":"세로는 밑면의 둘레와 같기 때문에","mis":"M6-2-u6-X09"}],"explanation":["원기둥의 전개도는 합동인 원 2개와 직사각형 1개예요.","옆면의 가로는 밑면의 둘레, 세로는 높이예요.","(밑면의 둘레) = (지름) × 3.14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_basic#10','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',3,'sa','auto','원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 8 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C3","difficulty":3,"kind":"sa","stem":"원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 8 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 8 cm는 높이예요.","25.12 ÷ 3.14 = 8 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 5 cm는 높이예요.","18.84 ÷ 3.14 = 6 cm예요."]},{"stem":"원기둥의 전개도에서 옆면의 가로가 31.4 cm, 세로가 11 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["10"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 11 cm는 높이예요.","31.4 ÷ 3.14 = 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_challenge#1','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',2,'match','auto','『수학』 128쪽의 원기둥(밑면의 반지름 4 cm, 높이 8 cm)과 전개도에서 알맞은 것끼리 이으세요.','{}'::text[],false,'{"seq":1,"concept":"M6-2-u6-C3","difficulty":2,"kind":"match","stem":"『수학』 128쪽의 원기둥(밑면의 반지름 4 cm, 높이 8 cm)과 전개도에서 알맞은 것끼리 이으세요.","pairs":[{"l":"밑면의 반지름","r":"4 cm"},{"l":"옆면의 가로","r":"25.12 cm"},{"l":"옆면의 세로","r":"8 cm"}],"mis":"M6-2-u6-X08","explanation":["밑면의 반지름은 그대로 4 cm예요.","옆면의 가로는 밑면의 둘레 — 8 × 3.14 = 25.12 cm예요.","옆면의 세로는 높이 8 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_challenge#2','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',2,'mc','auto','밑면의 반지름이 3 cm, 높이가 5 cm인 원기둥의 전개도를 그렸어요. 옆면의 가로는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":2,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"밑면의 반지름이 3 cm, 높이가 5 cm인 원기둥의 전개도를 그렸어요. 옆면의 가로는 몇 cm인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"6 cm","mis":"M6-2-u6-X08"},{"t":"9.42 cm","mis":"M6-2-u6-X08"},{"t":"37.68 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 3 cm의 2배 — 지름은 6 cm예요.","6 × 3.14 = 18.84 cm예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 10 cm, 높이가 11 cm인 원기둥의 전개도를 그렸어요. 옆면의 가로는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"10 cm","mis":"M6-2-u6-X08"},{"t":"15.7 cm","mis":"M6-2-u6-X08"},{"t":"62.8 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × (원주율)이에요.","10 × 3.14 = 31.4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_challenge#3','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',3,'error','auto','밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X19']::text[],false,'{"seq":3,"concept":"M6-2-u6-C3","difficulty":3,"kind":"error","stem":"밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"서우 — 「가로는 밑면의 지름이니 8 cm야.」","correct":true,"mis_target":"M6-2-u6-X08"},{"t":"여울 — 「4 × 2 × 3.14 = 25.12야.」","mis":"M6-2-u6-X19"},{"t":"지석 — 「지름 8 cm에 3.14를 곱해 25.12야.」","mis":"M6-2-u6-X19"},{"t":"민지 — 「가로는 밑면의 둘레야.」","mis":"M6-2-u6-X19"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","8 × 3.14 = 25.12 cm예요.","서우는 지름을 가로로 보았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_challenge#4','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',3,'ox','auto','밑면의 지름이 같은 두 원기둥은 전개도에서 옆면의 가로가 같아요.',ARRAY['M6-2-u6-X09']::text[],true,'{"seq":4,"concept":"M6-2-u6-C3","difficulty":3,"kind":"ox","stem":"밑면의 지름이 같은 두 원기둥은 전개도에서 옆면의 가로가 같아요.","answer":"O","reason_options":[{"t":"옆면의 가로는 (지름) × 3.14이기 때문에","correct":true},{"t":"옆면의 가로는 높이로 정해지기 때문에","mis":"M6-2-u6-X09"}],"mis":"M6-2-u6-X09","explanation":["원기둥의 전개도는 합동인 원 2개와 직사각형 1개예요.","옆면의 가로는 밑면의 둘레, 세로는 높이예요.","(밑면의 둘레) = (지름) × 3.14예요."],"variant_rule":{"alt":[{"stem":"원기둥의 높이가 높아지면 전개도에서 옆면의 가로가 길어져요.","answer":"X","reason_options":[{"t":"높이는 옆면의 세로이고 가로는 밑면의 둘레이기 때문에","correct":true},{"t":"높이와 옆면의 가로는 같은 길이이기 때문에","mis":"M6-2-u6-X09"}],"explanation":["원기둥의 전개도는 합동인 원 2개와 직사각형 1개예요.","옆면의 가로는 밑면의 둘레, 세로는 높이예요.","(밑면의 둘레) = (지름) × 3.14예요."]},{"stem":"밑면의 반지름이 2배가 되면 옆면의 가로도 2배가 돼요.","answer":"O","reason_options":[{"t":"옆면의 가로는 (반지름) × 2 × 3.14이기 때문에","correct":true},{"t":"옆면의 가로는 반지름과 상관없기 때문에","mis":"M6-2-u6-X10"}],"explanation":["원기둥의 전개도는 합동인 원 2개와 직사각형 1개예요.","옆면의 가로는 밑면의 둘레, 세로는 높이예요.","(밑면의 둘레) = (지름) × 3.14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_challenge#5','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',3,'mc','auto','밑면의 지름이 10 cm, 높이가 8 cm인 원기둥의 전개도에서 옆면의 둘레는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X20']::text[],false,'{"seq":5,"concept":"M6-2-u6-C3","difficulty":3,"kind":"mc","stem":"밑면의 지름이 10 cm, 높이가 8 cm인 원기둥의 전개도에서 옆면의 둘레는 몇 cm인가요?","options":[{"t":"78.8 cm","correct":true},{"t":"36 cm","mis":"M6-2-u6-X08"},{"t":"39.4 cm","mis":"M6-2-u6-X20"},{"t":"47.4 cm","mis":"M6-2-u6-X08"}],"explanation":["옆면의 가로는 밑면의 둘레 — 10 × 3.14 = 31.4 cm예요.","옆면의 세로는 높이 8 cm예요.","옆면의 둘레는 (31.4 + 8) × 2 = 78.8 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_challenge#6','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',3,'mc','auto','원기둥의 전개도에서 옆면의 가로를 구할 때 원주율 3.14를 쓰는 까닭은 무엇인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X09']::text[],false,'{"seq":6,"concept":"M6-2-u6-C3","difficulty":3,"kind":"mc","stem":"원기둥의 전개도에서 옆면의 가로를 구할 때 원주율 3.14를 쓰는 까닭은 무엇인가요?","options":[{"t":"옆면의 가로가 밑면의 둘레(원주)이고 (원주) = (지름) × (원주율)이기 때문에","correct":true},{"t":"옆면의 가로가 밑면의 지름이기 때문에","mis":"M6-2-u6-X08"},{"t":"옆면의 세로가 원주이기 때문에","mis":"M6-2-u6-X09"},{"t":"원기둥의 높이를 구해야 하기 때문에","mis":"M6-2-u6-X09"}],"explanation":["옆면의 가로는 밑면의 둘레와 맞닿아요.","원의 둘레(원주)는 (지름) × (원주율)로 구해요.","원주율은 3.14로 하고 계산기를 써도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_challenge#7','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',3,'sa','auto','원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 4 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u6-C3","difficulty":3,"kind":"sa","stem":"원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 4 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["12"],"explanation":["지름은 25.12 ÷ 3.14 = 8 cm예요.","옆면의 세로가 높이 — 4 cm예요.","8 + 4 = 12 cm예요."],"mis":"M6-2-u6-X09","variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["11"],"explanation":["지름은 18.84 ÷ 3.14 = 6 cm예요.","옆면의 세로가 높이 — 5 cm예요.","6 + 5 = 11 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_challenge#8','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',4,'sa','auto','가로 37.68 cm, 세로 6 cm인 직사각형 모양의 종이를 옆면으로 하는 원기둥을 만들려고 해요. 밑면의 반지름은 몇 cm로 해야 하나요?','{}'::text[],false,'{"seq":8,"concept":"M6-2-u6-C3","difficulty":4,"kind":"sa","stem":"가로 37.68 cm, 세로 6 cm인 직사각형 모양의 종이를 옆면으로 하는 원기둥을 만들려고 해요. 밑면의 반지름은 몇 cm로 해야 하나요?","answer":["6"],"explanation":["옆면의 가로 37.68 cm가 밑면의 둘레가 돼요.","지름은 37.68 ÷ 3.14 = 12 cm예요.","반지름은 12 ÷ 2 = 6 cm예요."],"mis":"M6-2-u6-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_challenge#9','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',4,'essay','teacher','밑면의 반지름이 4 cm, 높이가 8 cm인 원기둥의 전개도에서 옆면의 가로와 세로를 구하는 과정을 쓰세요. 옆면의 가로가 밑면의 지름이 아닌 까닭도 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u6-C3","difficulty":4,"kind":"essay","stem":"밑면의 반지름이 4 cm, 높이가 8 cm인 원기둥의 전개도에서 옆면의 가로와 세로를 구하는 과정을 쓰세요. 옆면의 가로가 밑면의 지름이 아닌 까닭도 함께 쓰세요.","answer_guide":{"answer":"예: 옆면을 감아 붙이면 위아래 테두리가 밑면의 둘레에 딱 맞아야 하므로 옆면의 가로는 밑면의 둘레이다. 지름은 4 × 2 = 8 cm이므로 가로는 8 × 3.14 = 25.12 cm이다. 옆면의 세로는 원기둥의 높이와 같으므로 8 cm이다.","scoring_points":["가로 = 밑면의 둘레인 까닭(감으면 둘레에 맞닿음)을 썼는가","가로 25.12 cm를 구했는가","세로 = 높이 8 cm를 썼는가"]},"explanation":["가로 = 밑면의 둘레예요.","8 × 3.14 = 25.12 cm예요.","세로 = 높이 8 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L04_challenge#10','math',6,2,'u6','L04','tb_g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',4,'sa','auto','밑면의 지름이 8 cm인 원기둥의 전개도에서 옆면의 가로를 cm 단위로 구한 뒤, 그 값을 다시 3.14로 나누면 얼마가 되나요?','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C3","difficulty":4,"kind":"sa","stem":"밑면의 지름이 8 cm인 원기둥의 전개도에서 옆면의 가로를 cm 단위로 구한 뒤, 그 값을 다시 3.14로 나누면 얼마가 되나요?","answer":["8"],"explanation":["옆면의 가로는 8 × 3.14 = 25.12 cm예요.","25.12 ÷ 3.14는 둘레에서 지름을 되짚는 셈이에요.","25.12 ÷ 3.14 = 8 — 처음 지름이 돼요."],"mis":"M6-2-u6-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_basic#1','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',1,'mc','auto','『수학』 129쪽의 나 — 「옆면이 사다리꼴 모양이고, 두 원이 위와 아래에 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?',ARRAY['M6-2-u6-X11']::text[],true,'{"seq":1,"concept":"M6-2-u6-C4","difficulty":1,"kind":"mc","stem":"『수학』 129쪽의 나 — 「옆면이 사다리꼴 모양이고, 두 원이 위와 아래에 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"옆면이 직사각형이 아니어서","correct":true},{"t":"두 원이 겹쳐서","mis":"M6-2-u6-X11"},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X11"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X11"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 옆면이 직사각형이 아니어서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"『수학』 129쪽의 다 — 「옆면이 직사각형이고, 크기가 같은 두 원이 옆면의 위쪽에 나란히 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"두 원이 겹쳐서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X12"},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X12"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X12"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 두 원이 겹쳐서 전개도가 될 수 없어요."]},{"stem":"『수학』 129쪽의 라 — 「세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 다른 두 원이 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 원이 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 두 원이 서로 합동이 아니어서 전개도가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_basic#2','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',1,'mc','auto','『수학』 129쪽 신나는 퀴즈 — 원기둥의 전개도에서 밑면의 둘레와 같은 것은 옆면의 ㉠(가로)과 ㉡(세로) 가운데 어느 것인가요?',ARRAY['M6-2-u6-X09','M6-2-u6-X08']::text[],true,'{"seq":2,"concept":"M6-2-u6-C4","difficulty":1,"kind":"mc","stem":"『수학』 129쪽 신나는 퀴즈 — 원기둥의 전개도에서 밑면의 둘레와 같은 것은 옆면의 ㉠(가로)과 ㉡(세로) 가운데 어느 것인가요?","options":[{"t":"㉠ 옆면의 가로","correct":true},{"t":"㉡ 옆면의 세로","mis":"M6-2-u6-X09"},{"t":"둘 다 아니에요","mis":"M6-2-u6-X08"},{"t":"㉠과 ㉡의 합","mis":"M6-2-u6-X09"}],"explanation":["옆면을 감으면 가로가 밑면의 테두리를 한 바퀴 둘러요.","그래서 밑면의 둘레는 ㉠과 같아요.","높이는 ㉡과 같아요."],"variant_rule":{"alt":[{"stem":"『수학』 129쪽 신나는 퀴즈 — 원기둥의 전개도를 그릴 때 밑면은 서로 어떤 모양으로 몇 개 그리나요?","options":[{"t":"서로 합동인 모양으로 2개","correct":true},{"t":"서로 평행한 모양으로 1개","mis":"M6-2-u6-X13"},{"t":"크기가 다른 모양으로 2개","mis":"M6-2-u6-X02"},{"t":"서로 합동인 모양으로 1개","mis":"M6-2-u6-X13"}],"explanation":["원기둥의 두 밑면은 서로 평행하고 합동인 원이에요.","전개도에서는 펼쳐져 있으니 「합동」을 지켜 그려요.","그래서 합동인 원 2개를 마주 보게 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_basic#3','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',1,'sa','auto','원기둥의 전개도를 그릴 때 밑면은 모두 몇 개 그려야 하나요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u6-C4","difficulty":1,"kind":"sa","stem":"원기둥의 전개도를 그릴 때 밑면은 모두 몇 개 그려야 하나요?","answer":["2"],"explanation":["원기둥의 면을 떠올려요 — 밑면 2개와 옆면 1개예요.","밑면은 서로 합동인 원 2개를 그려요.","두 밑면은 옆면을 사이에 두고 마주 보게 그려요."],"mis":"M6-2-u6-X13","variant_rule":{"alt":[{"stem":"원기둥의 전개도는 모두 몇 개의 평면도형으로 이루어져 있나요?","answer":["3"],"explanation":["원기둥의 면을 떠올려요 — 밑면 2개와 옆면 1개예요.","원 2개와 직사각형 1개 — 모두 3개예요.","두 밑면은 옆면을 사이에 두고 마주 보게 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_basic#4','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',1,'mc','auto','원기둥의 전개도에서 두 밑면은 어디에 있어야 하나요?',ARRAY['M6-2-u6-X12']::text[],true,'{"seq":4,"concept":"M6-2-u6-C4","difficulty":1,"kind":"mc","stem":"원기둥의 전개도에서 두 밑면은 어디에 있어야 하나요?","options":[{"t":"옆면을 사이에 두고 마주 보는 위치","correct":true},{"t":"옆면의 같은 쪽에 나란히","mis":"M6-2-u6-X12"},{"t":"옆면의 한가운데에 겹쳐서","mis":"M6-2-u6-X12"},{"t":"아무 곳에나","mis":"M6-2-u6-X12"}],"explanation":["옆면을 감으면 둥근 통이 돼요.","그 통의 위쪽과 아래쪽을 각각 막아야 해요.","그래서 두 밑면은 서로 합동인 원이고 옆면을 사이에 두고 마주 보아야 해요."],"variant_rule":{"alt":[{"stem":"원기둥의 전개도를 그릴 때 두 밑면은 어떻게 그려야 하나요?","options":[{"t":"서로 합동인 원 2개","correct":true},{"t":"크기가 다른 원 2개","mis":"M6-2-u6-X02"},{"t":"원 1개","mis":"M6-2-u6-X13"},{"t":"직사각형 2개","mis":"M6-2-u6-X13"}],"explanation":["옆면을 감으면 둥근 통이 돼요.","그 통의 위쪽과 아래쪽을 각각 막아야 해요.","그래서 두 밑면은 서로 합동인 원이고 옆면을 사이에 두고 마주 보아야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_basic#5','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',2,'mc','auto','『수학』 129쪽 가~라 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요? (가 직사각형의 위와 아래에 크기가 같은 원 · 나 사다리꼴 옆면 · 다 두 원이 위쪽에 나란히 · 라 크기가 다른 두 원)',ARRAY['M6-2-u6-X11','M6-2-u6-X12','M6-2-u6-X02']::text[],false,'{"seq":5,"concept":"M6-2-u6-C4","difficulty":2,"kind":"mc","stem":"『수학』 129쪽 가~라 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요? (가 직사각형의 위와 아래에 크기가 같은 원 · 나 사다리꼴 옆면 · 다 두 원이 위쪽에 나란히 · 라 크기가 다른 두 원)","options":[{"t":"가","correct":true},{"t":"나","mis":"M6-2-u6-X11"},{"t":"다","mis":"M6-2-u6-X12"},{"t":"라","mis":"M6-2-u6-X02"}],"explanation":["나는 옆면이 직사각형이 아니에요.","다는 두 원이 겹치고, 라는 두 원이 합동이 아니에요.","그래서 원기둥의 전개도가 될 수 있는 것은 가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_basic#6','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',2,'mc','auto','종이 상자는 이물질을 없앤 다음 납작하게 부피를 줄여 분리배출해요. 상자를 잘라 펼친 가 · 나 · 다 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요? (가 직사각형의 위와 아래에 크기가 같은 원이 하나씩 · 나 직사각형의 왼쪽에 크기가 같은 두 원이 나란히 · 다 직사각형의 위에 큰 원, 아래에 작은 원)',ARRAY['M6-2-u6-X12','M6-2-u6-X02']::text[],false,'{"seq":6,"concept":"M6-2-u6-C4","difficulty":2,"kind":"mc","stem":"종이 상자는 이물질을 없앤 다음 납작하게 부피를 줄여 분리배출해요. 상자를 잘라 펼친 가 · 나 · 다 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요? (가 직사각형의 위와 아래에 크기가 같은 원이 하나씩 · 나 직사각형의 왼쪽에 크기가 같은 두 원이 나란히 · 다 직사각형의 위에 큰 원, 아래에 작은 원)","options":[{"t":"가","correct":true},{"t":"나","mis":"M6-2-u6-X12"},{"t":"다","mis":"M6-2-u6-X02"},{"t":"셋 다 될 수 있어요","mis":"M6-2-u6-X02"}],"explanation":["나는 두 원이 같은 쪽에 있어 접으면 겹쳐요.","다는 두 원이 서로 합동이 아니에요.","그래서 원기둥의 전개도는 가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_basic#7','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C3',2,'mc','auto','『수학』 130쪽 활동 6 — 밑면의 반지름이 1 cm, 높이가 2 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":7,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"『수학』 130쪽 활동 6 — 밑면의 반지름이 1 cm, 높이가 2 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"6.28 cm","correct":true},{"t":"2 cm","mis":"M6-2-u6-X08"},{"t":"3.14 cm","mis":"M6-2-u6-X08"},{"t":"12.56 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 2 cm예요.","2 × 3.14 = 6.28 cm예요."],"variant_rule":{"alt":[{"stem":"『수학』 130쪽 활동 7 — 밑면의 지름이 3 cm, 높이가 2 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"9.42 cm","correct":true},{"t":"3 cm","mis":"M6-2-u6-X08"},{"t":"4.71 cm","mis":"M6-2-u6-X08"},{"t":"2 cm","mis":"M6-2-u6-X09"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 3 cm예요.","3 × 3.14 = 9.42 cm예요."]},{"stem":"『수학익힘』 89쪽 — 밑면의 반지름이 1.5 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"9.42 cm","correct":true},{"t":"3 cm","mis":"M6-2-u6-X08"},{"t":"4.71 cm","mis":"M6-2-u6-X08"},{"t":"18.84 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 3 cm예요.","3 × 3.14 = 9.42 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_basic#8','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',2,'ox','auto','옆면이 평행사변형인 그림도 원기둥의 전개도가 될 수 있어요.',ARRAY['M6-2-u6-X11']::text[],true,'{"seq":8,"concept":"M6-2-u6-C4","difficulty":2,"kind":"ox","stem":"옆면이 평행사변형인 그림도 원기둥의 전개도가 될 수 있어요.","answer":"X","reason_options":[{"t":"감으면 위아래 테두리가 어긋나기 때문에","correct":true},{"t":"평행사변형도 사각형이라 감을 수 있기 때문에","mis":"M6-2-u6-X11"}],"mis":"M6-2-u6-X11","explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보아야 해요."],"variant_rule":{"alt":[{"stem":"합동인 두 원이 옆면의 같은 쪽에 붙은 그림은 원기둥의 전개도가 아니에요.","answer":"O","reason_options":[{"t":"접으면 두 원이 겹치고 반대쪽이 비기 때문에","correct":true},{"t":"두 원의 크기가 다르기 때문에","mis":"M6-2-u6-X12"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보아야 해요."]},{"stem":"두 원의 크기가 달라도 옆면이 직사각형이면 원기둥의 전개도예요.","answer":"X","reason_options":[{"t":"원기둥의 두 밑면은 서로 합동이어야 하기 때문에","correct":true},{"t":"옆면만 직사각형이면 되기 때문에","mis":"M6-2-u6-X02"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보아야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_basic#9','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',2,'error','auto','원기둥의 전개도가 될 수 있는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X12','M6-2-u6-X19']::text[],false,'{"seq":9,"concept":"M6-2-u6-C4","difficulty":2,"kind":"error","stem":"원기둥의 전개도가 될 수 있는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지석 — 「두 원이 옆면의 같은 쪽에 있어도 합동이면 전개도야.」","correct":true,"mis_target":"M6-2-u6-X12"},{"t":"서우 — 「옆면은 직사각형이어야 해.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「두 원은 서로 합동이어야 해.」","mis":"M6-2-u6-X19"},{"t":"민지 — 「두 원은 옆면을 사이에 두고 마주 보아야 해.」","mis":"M6-2-u6-X19"}],"explanation":["두 원이 같은 쪽에 있으면 접었을 때 한자리에 겹쳐요.","그러면 반대쪽이 뚫린 채 남아요.","그래서 지석의 말이 잘못되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_basic#10','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C3',3,'mc','auto','『수학익힘』 89쪽 — 밑면의 반지름이 1.5 cm, 높이가 3 cm인 원기둥의 전개도에 (밑면의 반지름, 옆면의 가로, 옆면의 세로)를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u6-X04','M6-2-u6-X08','M6-2-u6-X09']::text[],true,'{"seq":10,"concept":"M6-2-u6-C3","difficulty":3,"kind":"mc","stem":"『수학익힘』 89쪽 — 밑면의 반지름이 1.5 cm, 높이가 3 cm인 원기둥의 전개도에 (밑면의 반지름, 옆면의 가로, 옆면의 세로)를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1.5 cm, 9.42 cm, 3 cm","correct":true},{"t":"3 cm, 9.42 cm, 3 cm","mis":"M6-2-u6-X04"},{"t":"1.5 cm, 3 cm, 3 cm","mis":"M6-2-u6-X08"},{"t":"1.5 cm, 3 cm, 9.42 cm","mis":"M6-2-u6-X09"}],"explanation":["밑면의 반지름은 1.5 cm예요.","옆면의 가로는 3 × 3.14 = 9.42 cm예요.","옆면의 세로는 높이 3 cm예요."],"variant_rule":{"alt":[{"stem":"『수학』 130쪽 활동 7 — 밑면의 지름이 3 cm, 높이가 2 cm인 원기둥의 전개도에 (밑면의 반지름, 옆면의 가로, 옆면의 세로)를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1.5 cm, 9.42 cm, 2 cm","correct":true},{"t":"3 cm, 9.42 cm, 2 cm","mis":"M6-2-u6-X04"},{"t":"1.5 cm, 3 cm, 2 cm","mis":"M6-2-u6-X08"},{"t":"1.5 cm, 2 cm, 9.42 cm","mis":"M6-2-u6-X09"}],"explanation":["밑면의 반지름은 1.5 cm예요.","옆면의 가로는 3 × 3.14 = 9.42 cm예요.","옆면의 세로는 높이 2 cm예요."]},{"stem":"단원 평가 — 밑면의 반지름이 0.5 cm, 높이가 3 cm인 원기둥의 전개도에 (밑면의 반지름, 옆면의 가로, 옆면의 세로)를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"0.5 cm, 3.14 cm, 3 cm","correct":true},{"t":"1 cm, 3.14 cm, 3 cm","mis":"M6-2-u6-X04"},{"t":"0.5 cm, 1 cm, 3 cm","mis":"M6-2-u6-X08"},{"t":"0.5 cm, 3 cm, 3.14 cm","mis":"M6-2-u6-X09"}],"explanation":["밑면의 반지름은 0.5 cm예요.","옆면의 가로는 1 × 3.14 = 3.14 cm예요.","옆면의 세로는 높이 3 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_challenge#1','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',3,'match','auto','원기둥의 전개도가 될 수 없는 그림과 그 까닭을 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C4","difficulty":3,"kind":"match","stem":"원기둥의 전개도가 될 수 없는 그림과 그 까닭을 이으세요.","pairs":[{"l":"옆면이 평행사변형","r":"옆면이 직사각형이 아님"},{"l":"두 원이 같은 쪽","r":"접으면 두 원이 겹침"},{"l":"위 원이 더 작음","r":"두 밑면이 합동이 아님"}],"mis":"M6-2-u6-X11","explanation":["옆면은 직사각형이어야 해요.","두 밑면은 합동인 원이어야 해요.","두 밑면은 마주 보는 위치에 있어야 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥의 전개도가 될 수 없는 그림과 그 까닭을 이으세요.","pairs":[{"l":"기울어진 옆면","r":"위아래 테두리가 어긋남"},{"l":"크기가 다른 두 원","r":"한쪽이 남거나 모자람"},{"l":"나란히 붙은 두 원","r":"한쪽이 뚫림"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 합동인 원이어야 해요.","두 밑면은 마주 보는 위치에 있어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_challenge#2','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',2,'mc','auto','원기둥의 전개도를 그릴 때 옆면을 먼저 그렸어요. 밑면은 어떻게 그려야 하나요?',ARRAY['M6-2-u6-X12','M6-2-u6-X13','M6-2-u6-X02']::text[],false,'{"seq":2,"concept":"M6-2-u6-C4","difficulty":2,"kind":"mc","stem":"원기둥의 전개도를 그릴 때 옆면을 먼저 그렸어요. 밑면은 어떻게 그려야 하나요?","options":[{"t":"옆면을 기준으로 이미 그린 밑면과 마주 보는 위치에 합동인 원을 그려요","correct":true},{"t":"이미 그린 밑면 바로 옆에 같은 원을 하나 더 그려요","mis":"M6-2-u6-X12"},{"t":"옆면 안쪽에 원을 그려요","mis":"M6-2-u6-X13"},{"t":"이미 그린 밑면보다 작은 원을 반대쪽에 그려요","mis":"M6-2-u6-X02"}],"explanation":["옆면을 감으면 둥근 통이 돼요.","통의 위쪽과 아래쪽을 각각 막아야 해요.","그래서 합동인 원을 옆면을 기준으로 마주 보게 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_challenge#3','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',3,'mc','auto','『수학』 141쪽 마무리 4 — 가 직사각형의 위쪽에 크기가 같은 두 원이 나란히 · 나 사다리꼴 옆면의 위와 아래에 원 · 다 세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 같은 원이 하나씩 — 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u6-X12','M6-2-u6-X11']::text[],false,'{"seq":3,"concept":"M6-2-u6-C4","difficulty":3,"kind":"mc","stem":"『수학』 141쪽 마무리 4 — 가 직사각형의 위쪽에 크기가 같은 두 원이 나란히 · 나 사다리꼴 옆면의 위와 아래에 원 · 다 세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 같은 원이 하나씩 — 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M6-2-u6-X12"},{"t":"나","mis":"M6-2-u6-X11"},{"t":"가와 다","mis":"M6-2-u6-X12"}],"explanation":["가는 두 원이 겹쳐서 안 돼요.","나는 옆면이 직사각형이 아니어서 안 돼요.","다는 옆면이 직사각형이고 합동인 두 원이 마주 보아 전개도가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_challenge#4','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',3,'ox','auto','친구와 내가 그린 원기둥의 전개도가 밑면이 붙은 자리만 서로 달라요. 옆면이 직사각형이고, 합동인 두 원이 옆면을 기준으로 마주 보고 있으면 두 그림 모두 원기둥의 전개도예요.',ARRAY['M6-2-u6-X23']::text[],false,'{"seq":4,"concept":"M6-2-u6-C4","difficulty":3,"kind":"ox","stem":"친구와 내가 그린 원기둥의 전개도가 밑면이 붙은 자리만 서로 달라요. 옆면이 직사각형이고, 합동인 두 원이 옆면을 기준으로 마주 보고 있으면 두 그림 모두 원기둥의 전개도예요.","answer":"O","reason_options":[{"t":"원기둥을 어디를 잘라 펼치느냐에 따라 전개도가 여러 가지로 나오기 때문에","correct":true},{"t":"원기둥의 전개도는 한 가지 모양뿐이기 때문에","mis":"M6-2-u6-X23"}],"mis":"M6-2-u6-X23","explanation":["전개도는 원기둥을 잘라서 펼친 그림이에요.","자른 곳이 다르면 펼친 모양도 달라져요.","옆면 직사각형 · 합동인 두 원 · 마주 보는 위치면 모두 전개도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_challenge#5','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C3',3,'mc','auto','밑면의 지름이 2 cm인 원기둥의 전개도를 그리는데 옆면의 가로를 2 cm로 그렸더니 감았을 때 밑면과 맞지 않았어요. 옆면의 가로를 몇 cm로 고쳐야 하나요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":5,"concept":"M6-2-u6-C3","difficulty":3,"kind":"mc","stem":"밑면의 지름이 2 cm인 원기둥의 전개도를 그리는데 옆면의 가로를 2 cm로 그렸더니 감았을 때 밑면과 맞지 않았어요. 옆면의 가로를 몇 cm로 고쳐야 하나요?","options":[{"t":"6.28 cm","correct":true},{"t":"2 cm","mis":"M6-2-u6-X08"},{"t":"3.14 cm","mis":"M6-2-u6-X08"},{"t":"12.56 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면을 감았을 때 테두리가 밑면의 둘레에 딱 맞아야 해요.","밑면의 둘레는 2 × 3.14 = 6.28 cm예요.","그래서 가로를 6.28 cm로 고쳐요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 3 cm인 원기둥의 전개도를 그리는데 옆면의 가로를 3 cm로 그렸더니 감았을 때 밑면과 맞지 않았어요. 옆면의 가로를 몇 cm로 고쳐야 하나요?","options":[{"t":"9.42 cm","correct":true},{"t":"3 cm","mis":"M6-2-u6-X08"},{"t":"4.71 cm","mis":"M6-2-u6-X08"},{"t":"18.84 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면을 감았을 때 테두리가 밑면의 둘레에 딱 맞아야 해요.","밑면의 둘레는 3 × 3.14 = 9.42 cm예요.","그래서 가로를 9.42 cm로 고쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_challenge#6','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C3',2,'sa','auto','『수학』 141쪽 마무리 5 — 밑면의 지름이 2 cm, 높이가 3 cm인 원기둥의 전개도를 완성했어요. 밑면의 반지름(cm)과 옆면의 세로(cm)를 더하면 얼마인가요?','{}'::text[],false,'{"seq":6,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"『수학』 141쪽 마무리 5 — 밑면의 지름이 2 cm, 높이가 3 cm인 원기둥의 전개도를 완성했어요. 밑면의 반지름(cm)과 옆면의 세로(cm)를 더하면 얼마인가요?","answer":["4"],"explanation":["밑면의 반지름은 2 ÷ 2 = 1 cm예요.","옆면의 세로는 높이 3 cm예요 — 옆면의 가로는 2 × 3.14 = 6.28 cm예요.","1 + 3 = 4예요."],"mis":"M6-2-u6-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_challenge#7','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',3,'error','auto','원기둥의 전개도를 그린 친구들의 실수예요. 지도서가 「단순한 오차인지 확인해 보라」고 한 실수는 어느 것인가요?',ARRAY['M6-2-u6-X02','M6-2-u6-X19']::text[],false,'{"seq":7,"concept":"M6-2-u6-C4","difficulty":3,"kind":"error","stem":"원기둥의 전개도를 그린 친구들의 실수예요. 지도서가 「단순한 오차인지 확인해 보라」고 한 실수는 어느 것인가요?","options":[{"t":"두 밑면을 조금 다른 크기로 그렸어요 — 원기둥의 두 밑면은 합동인 원으로 그려야 해요","correct":true,"mis_target":"M6-2-u6-X02"},{"t":"옆면을 직사각형으로 그렸어요","mis":"M6-2-u6-X19"},{"t":"두 밑면을 옆면의 위와 아래에 마주 보게 그렸어요","mis":"M6-2-u6-X19"},{"t":"옆면의 가로를 밑면의 둘레만큼 그렸어요","mis":"M6-2-u6-X19"}],"explanation":["두 밑면의 크기가 다르면 단순한 오차인지 먼저 확인해요.","원기둥의 두 밑면은 서로 합동인 원으로 그려야 해요.","나머지는 모두 바르게 그린 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_challenge#8','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',4,'essay','teacher','휴지 심으로 원기둥의 전개도를 그리려고 해요. 휴지 심의 높이를 재고, 잘라 펼친 가로를 잰 다음 무엇을 구해 어떻게 그리는지 차례대로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u6-C4","difficulty":4,"kind":"essay","stem":"휴지 심으로 원기둥의 전개도를 그리려고 해요. 휴지 심의 높이를 재고, 잘라 펼친 가로를 잰 다음 무엇을 구해 어떻게 그리는지 차례대로 설명해 보세요.","answer_guide":{"answer":"예: ① 휴지 심의 높이를 재어 옆면의 세로로 한다. ② 잘라서 펼친 옆면의 가로를 잰다. ③ 옆면의 가로가 밑면의 둘레이므로 (가로) ÷ 3.14로 밑면의 지름을 구한다. ④ 옆면은 직사각형으로, 밑면은 구한 지름의 원 두 개를 옆면을 기준으로 마주 보게 그린다.","scoring_points":["높이 = 옆면의 세로로 썼는가","가로 ÷ 3.14로 지름을 구한다고 썼는가","합동인 두 원을 마주 보게 그린다고 썼는가"]},"explanation":["높이 → 옆면의 세로예요.","(가로) ÷ 3.14 → 밑면의 지름이에요.","합동인 원 2개를 마주 보게 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_challenge#9','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C3',4,'sa','auto','단원 평가의 원기둥(밑면의 반지름 0.5 cm, 높이 3 cm)과 『수학』 130쪽 활동 6의 원기둥(밑면의 반지름 1 cm, 높이 2 cm)의 전개도를 그렸어요. 뒤의 원기둥의 옆면의 가로는 앞의 원기둥의 옆면의 가로의 몇 배인가요?','{}'::text[],false,'{"seq":9,"concept":"M6-2-u6-C3","difficulty":4,"kind":"sa","stem":"단원 평가의 원기둥(밑면의 반지름 0.5 cm, 높이 3 cm)과 『수학』 130쪽 활동 6의 원기둥(밑면의 반지름 1 cm, 높이 2 cm)의 전개도를 그렸어요. 뒤의 원기둥의 옆면의 가로는 앞의 원기둥의 옆면의 가로의 몇 배인가요?","answer":["2"],"explanation":["앞의 원기둥: 지름 1 cm — 옆면의 가로는 1 × 3.14 = 3.14 cm예요.","뒤의 원기둥: 지름 2 cm — 옆면의 가로는 2 × 3.14 = 6.28 cm예요.","6.28 ÷ 3.14 = 2 — 반지름이 2배이면 옆면의 가로도 2배예요(높이와는 상관없어요)."],"mis":"M6-2-u6-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L05_challenge#10','math',6,2,'u6','L05','tb_g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',4,'essay','teacher','『수학』 129쪽의 나·다·라가 원기둥의 전개도가 될 수 없는 까닭을 각각 쓰세요. (나 사다리꼴 옆면 · 다 두 원이 옆면의 위쪽에 나란히 · 라 크기가 다른 두 원)','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C4","difficulty":4,"kind":"essay","stem":"『수학』 129쪽의 나·다·라가 원기둥의 전개도가 될 수 없는 까닭을 각각 쓰세요. (나 사다리꼴 옆면 · 다 두 원이 옆면의 위쪽에 나란히 · 라 크기가 다른 두 원)","answer_guide":{"answer":"예: 나는 옆면이 직사각형이 아니므로 원기둥의 전개도가 될 수 없다. 다는 두 원이 겹치므로(마주 보는 위치에 있지 않으므로) 될 수 없다. 라는 두 원이 서로 합동이 아니므로 될 수 없다.","scoring_points":["나 — 옆면이 직사각형이 아님을 썼는가","다 — 두 원이 겹침을 썼는가","라 — 두 원이 합동이 아님을 썼는가"]},"explanation":["나는 옆면이 직사각형이 아니에요.","다는 두 원이 겹쳐요.","라는 두 원이 합동이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_basic#1','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',1,'mc','auto','한 원을 면으로 하는 입체도형을 무엇이라고 하나요?',ARRAY['M6-2-u6-X14','M6-2-u6-X03','M6-2-u6-X01']::text[],true,'{"seq":1,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"한 원을 면으로 하는 입체도형을 무엇이라고 하나요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X14"},{"t":"각기둥","mis":"M6-2-u6-X03"},{"t":"각뿔","mis":"M6-2-u6-X01"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","한 원을 면으로 하는 입체도형을 원뿔이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."],"variant_rule":{"alt":[{"stem":"원뿔은 어떤 입체도형인가요?","options":[{"t":"한 원을 면으로 하는 입체도형","correct":true},{"t":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"},{"t":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형","mis":"M6-2-u6-X03"},{"t":"밑면이 다각형이고 옆면이 모두 삼각형인 입체도형","mis":"M6-2-u6-X01"}],"explanation":["원뿔의 뜻을 떠올려요.","원뿔은 한 원을 면으로 하는 입체도형이에요.","나머지는 다른 입체도형의 뜻이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_basic#2','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',1,'mc','auto','직각삼각형 모양의 종이를 직각을 낀 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?',ARRAY['M6-2-u6-X03','M6-2-u6-X01']::text[],true,'{"seq":2,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"직각삼각형 모양의 종이를 직각을 낀 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원뿔이 만들어져요."],"variant_rule":{"alt":[{"stem":"직사각형 모양의 종이를 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원기둥","correct":true},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원기둥이 만들어져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_basic#3','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',1,'mc','auto','건물에서 찾은 입체도형을 「뿔 모양인가요?」로 먼저 갈라냈어요. 「아니요」가 된 것은 어느 것인가요? (가 원뿔 · 나 각기둥 · 다·라 원기둥 · 마 원뿔 · 바 각뿔)',ARRAY['M6-2-u6-X14','M6-2-u6-X01']::text[],false,'{"seq":3,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"건물에서 찾은 입체도형을 「뿔 모양인가요?」로 먼저 갈라냈어요. 「아니요」가 된 것은 어느 것인가요? (가 원뿔 · 나 각기둥 · 다·라 원기둥 · 마 원뿔 · 바 각뿔)","options":[{"t":"나, 다, 라","correct":true},{"t":"가, 마, 바","mis":"M6-2-u6-X14"},{"t":"바","mis":"M6-2-u6-X01"},{"t":"가, 마","mis":"M6-2-u6-X14"}],"explanation":["뿔 모양은 뾰족한 부분이 있는 모양이에요.","가·마·바는 뿔 모양이에요.","나·다·라는 뿔 모양이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_basic#4','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',1,'mc','auto','뿔 모양인 가·마·바를 「한 면이 원인가요?」로 다시 갈라냈어요. 「아니요」가 된 것은 어느 것인가요?',ARRAY['M6-2-u6-X01','M6-2-u6-X14']::text[],false,'{"seq":4,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"뿔 모양인 가·마·바를 「한 면이 원인가요?」로 다시 갈라냈어요. 「아니요」가 된 것은 어느 것인가요?","options":[{"t":"바","correct":true},{"t":"가","mis":"M6-2-u6-X01"},{"t":"마","mis":"M6-2-u6-X01"},{"t":"가, 마","mis":"M6-2-u6-X14"}],"explanation":["바는 밑면이 다각형인 각뿔이에요.","가와 마는 한 원을 면으로 해요.","그래서 「아니요」는 바예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_basic#5','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',2,'sa','auto','가 밑면이 원이고 뾰족한 뿔 모양인 입체도형 · 나 상자 모양의 각기둥 · 다 둥근 기둥 모양의 입체도형 · 라 납작한 둥근 기둥 모양의 입체도형 · 마 작은 뿔 모양이고 밑면이 원인 입체도형 · 바 밑면이 다각형인 뿔 모양의 입체도형 — 이 가운데 원뿔은 몇 개인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"가 밑면이 원이고 뾰족한 뿔 모양인 입체도형 · 나 상자 모양의 각기둥 · 다 둥근 기둥 모양의 입체도형 · 라 납작한 둥근 기둥 모양의 입체도형 · 마 작은 뿔 모양이고 밑면이 원인 입체도형 · 바 밑면이 다각형인 뿔 모양의 입체도형 — 이 가운데 원뿔은 몇 개인가요?","answer":["2"],"explanation":["원뿔의 뜻에 하나씩 대어 봐요.","원뿔인 것은 가, 마예요.","모두 2개예요."],"mis":"M6-2-u6-X14","variant_rule":{"alt":[{"stem":"가 밑면이 다각형인 뿔 모양의 입체도형 · 나 서로 평행하고 합동인 두 원이 있는 기둥 모양 · 다 거꾸로 세운 뿔 모양이고 한 원을 면으로 하는 입체도형 · 라 눕혀 놓은 뿔 모양이고 한 원을 면으로 하는 입체도형 — 이 가운데 원뿔은 몇 개인가요?","answer":["2"],"explanation":["원뿔의 뜻에 하나씩 대어 봐요.","원뿔인 것은 다, 라예요.","모두 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_basic#6','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',2,'mc','auto','『수학』 132쪽의 가는 뿔 모양인데도 원뿔이 아니에요. 까닭은 무엇인가요?',ARRAY['M6-2-u6-X19','M6-2-u6-X01','M6-2-u6-X15']::text[],false,'{"seq":6,"concept":"M6-2-u6-C5","difficulty":2,"kind":"mc","stem":"『수학』 132쪽의 가는 뿔 모양인데도 원뿔이 아니에요. 까닭은 무엇인가요?","options":[{"t":"원을 면으로 하지 않아서","correct":true},{"t":"뾰족한 점이 있어서","mis":"M6-2-u6-X19"},{"t":"옆면이 삼각형이 아니어서","mis":"M6-2-u6-X01"},{"t":"높이를 잴 수 없어서","mis":"M6-2-u6-X15"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","가의 밑면은 원이 아니라 다각형이에요.","그래서 가는 원뿔이 아니라 각뿔이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_basic#7','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',2,'mc','auto','『수학』 132쪽의 나에도 원이 있는데 원뿔이 아니에요. 까닭은 무엇인가요?',ARRAY['M6-2-u6-X19','M6-2-u6-X06']::text[],false,'{"seq":7,"concept":"M6-2-u6-C5","difficulty":2,"kind":"mc","stem":"『수학』 132쪽의 나에도 원이 있는데 원뿔이 아니에요. 까닭은 무엇인가요?","options":[{"t":"서로 합동인 두 면(원)이 있어서","correct":true},{"t":"원이 너무 커서","mis":"M6-2-u6-X19"},{"t":"옆면이 굽어 있어서","mis":"M6-2-u6-X19"},{"t":"높이가 높아서","mis":"M6-2-u6-X06"}],"explanation":["원뿔은 원을 한 개만 면으로 해요.","나는 서로 평행하고 합동인 두 원이 있는 원기둥이에요.","그래서 원뿔이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_basic#8','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',2,'mc','auto','직각삼각형의 직각을 낀 변을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원뿔의 무엇이 되나요?',ARRAY['M6-2-u6-X04','M6-2-u6-X15']::text[],true,'{"seq":8,"concept":"M6-2-u6-C5","difficulty":2,"kind":"mc","stem":"직각삼각형의 직각을 낀 변을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원뿔의 무엇이 되나요?","options":[{"t":"높이","correct":true},{"t":"밑면의 반지름","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."],"variant_rule":{"alt":[{"stem":"직각삼각형의 직각을 낀 변을 막대에 붙여 한 바퀴 돌릴 때, 막대에서 뻗어 나간 변은 만들어진 원뿔의 무엇이 되나요?","options":[{"t":"밑면의 반지름","correct":true},{"t":"높이","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_basic#9','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',2,'ox','auto','원뿔은 한 원을 면으로 하는 입체도형이에요.',ARRAY['M6-2-u6-X14']::text[],true,'{"seq":9,"concept":"M6-2-u6-C5","difficulty":2,"kind":"ox","stem":"원뿔은 한 원을 면으로 하는 입체도형이에요.","answer":"O","reason_options":[{"t":"원뿔에는 면이 되는 원이 하나 있기 때문에","correct":true},{"t":"원뿔에는 서로 합동인 두 원이 있기 때문에","mis":"M6-2-u6-X14"}],"mis":"M6-2-u6-X14","explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","각뿔은 밑면이 다각형, 원뿔은 원이에요.","직각삼각형을 한 바퀴 돌리면 원뿔이 돼요."],"variant_rule":{"alt":[{"stem":"밑면이 원인 뿔 모양도 각뿔이라고 불러요.","answer":"X","reason_options":[{"t":"각뿔은 밑면이 다각형이고 원은 다각형이 아니기 때문에","correct":true},{"t":"뿔 모양은 모두 각뿔이기 때문에","mis":"M6-2-u6-X01"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","각뿔은 밑면이 다각형, 원뿔은 원이에요.","직각삼각형을 한 바퀴 돌리면 원뿔이 돼요."]},{"stem":"직각삼각형을 한 바퀴 돌리면 원뿔이 돼요.","answer":"O","reason_options":[{"t":"직각을 낀 변을 기준으로 돌리면 뾰족한 점과 원이 생기기 때문에","correct":true},{"t":"삼각형을 돌리면 언제나 구가 되기 때문에","mis":"M6-2-u6-X03"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","각뿔은 밑면이 다각형, 원뿔은 원이에요.","직각삼각형을 한 바퀴 돌리면 원뿔이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_basic#10','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',3,'sa','auto','『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C5","difficulty":3,"kind":"sa","stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 지름은 몇 cm인가요?","answer":["14"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","지름은 7 × 2 = 14 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 높이는 몇 cm인가요?","answer":["5"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","그래서 높이는 5 cm예요."]},{"stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["19"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","지름 14 cm와 높이 5 cm — 14 + 5 = 19 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_challenge#1','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',2,'mc','auto','가 밑면이 다각형인 뿔 모양의 입체도형 · 나 서로 평행하고 합동인 두 원이 있는 기둥 모양 · 다 거꾸로 세운 뿔 모양이고 한 원을 면으로 하는 입체도형 · 라 눕혀 놓은 뿔 모양이고 한 원을 면으로 하는 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X14','M6-2-u6-X01']::text[],true,'{"seq":1,"concept":"M6-2-u6-C5","difficulty":2,"kind":"mc","stem":"가 밑면이 다각형인 뿔 모양의 입체도형 · 나 서로 평행하고 합동인 두 원이 있는 기둥 모양 · 다 거꾸로 세운 뿔 모양이고 한 원을 면으로 하는 입체도형 · 라 눕혀 놓은 뿔 모양이고 한 원을 면으로 하는 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"다, 라","correct":true},{"t":"다","mis":"M6-2-u6-X14"},{"t":"가, 다, 라","mis":"M6-2-u6-X01"},{"t":"나, 다, 라","mis":"M6-2-u6-X14"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","다, 라 모두 원뿔이에요."],"variant_rule":{"alt":[{"stem":"가 밑면이 원이고 뾰족한 뿔 모양인 입체도형 · 나 상자 모양의 각기둥 · 다 둥근 기둥 모양의 입체도형 · 라 납작한 둥근 기둥 모양의 입체도형 · 마 작은 뿔 모양이고 밑면이 원인 입체도형 · 바 밑면이 다각형인 뿔 모양의 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 마","correct":true},{"t":"가","mis":"M6-2-u6-X14"},{"t":"가, 마, 바","mis":"M6-2-u6-X01"},{"t":"가, 라, 마","mis":"M6-2-u6-X14"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 마 모두 원뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_challenge#2','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u6-C5","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"밑면이 다각형인 뿔","r":"각뿔"},{"l":"밑면이 원인 뿔","r":"원뿔"},{"l":"밑면이 원인 기둥","r":"원기둥"}],"mis":"M6-2-u6-X01","explanation":["밑면이 다각형이면 각기둥·각뿔, 원이면 원기둥·원뿔이에요.","원뿔의 밑면은 1개, 원기둥은 2개, 구는 평평한 면이 없어요.","직각삼각형은 원뿔, 직사각형은 원기둥, 반원은 구가 돼요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원뿔의 밑면의 수","r":"1개"},{"l":"원기둥의 밑면의 수","r":"2개"},{"l":"구의 평평한 면의 수","r":"0개"}],"explanation":["밑면이 다각형이면 각기둥·각뿔, 원이면 원기둥·원뿔이에요.","원뿔의 밑면은 1개, 원기둥은 2개, 구는 평평한 면이 없어요.","직각삼각형은 원뿔, 직사각형은 원기둥, 반원은 구가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_challenge#3','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',3,'error','auto','원뿔에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X14','M6-2-u6-X19']::text[],false,'{"seq":3,"concept":"M6-2-u6-C5","difficulty":3,"kind":"error","stem":"원뿔에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「원기둥도 원이 있으니 원뿔이야.」","correct":true,"mis_target":"M6-2-u6-X14"},{"t":"지석 — 「원뿔은 한 원을 면으로 해.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「직각삼각형을 돌려서 만들 수 있어.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「원뿔에는 뾰족한 점이 있어.」","mis":"M6-2-u6-X19"}],"explanation":["원뿔은 한 원을 면으로 하고 뾰족한 점이 하나 있어요.","원기둥은 합동인 원이 두 개이고 뾰족한 점이 없어요.","그래서 민지의 말이 잘못되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_challenge#4','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',3,'mc','auto','직각삼각형 모양의 종이를 막대에 붙여 원뿔을 만들 때, 종이를 어떻게 붙여야 하나요?',ARRAY['M6-2-u6-X03','M6-2-u6-X04']::text[],false,'{"seq":4,"concept":"M6-2-u6-C5","difficulty":3,"kind":"mc","stem":"직각삼각형 모양의 종이를 막대에 붙여 원뿔을 만들 때, 종이를 어떻게 붙여야 하나요?","options":[{"t":"직각이 있는 변을 막대에 붙여요","correct":true},{"t":"가장 긴 변을 막대에 붙여요","mis":"M6-2-u6-X03"},{"t":"어느 변이든 상관없어요","mis":"M6-2-u6-X03"},{"t":"직각과 마주 보는 꼭짓점만 막대에 대요","mis":"M6-2-u6-X04"}],"explanation":["직각을 낀 변을 막대에 붙여야 그 변이 곧게 서요.","뻗어 나간 다른 변이 돌며 원을 그려요.","그래서 직각이 있는 변을 막대에 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_challenge#5','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',3,'mc','auto','원기둥과 원뿔의 다른 점은 어느 것인가요?',ARRAY['M6-2-u6-X01','M6-2-u6-X14','M6-2-u6-X06']::text[],true,'{"seq":5,"concept":"M6-2-u6-C5","difficulty":3,"kind":"mc","stem":"원기둥과 원뿔의 다른 점은 어느 것인가요?","options":[{"t":"원기둥은 밑면이 2개, 원뿔은 1개예요","correct":true},{"t":"원기둥은 밑면이 원, 원뿔은 다각형이에요","mis":"M6-2-u6-X01"},{"t":"원뿔에는 옆면이 없어요","mis":"M6-2-u6-X14"},{"t":"원기둥은 높이가 없어요","mis":"M6-2-u6-X06"}],"explanation":["원기둥과 원뿔 모두 밑면이 원이고 옆면이 굽은 면이에요.","원기둥은 밑면이 2개, 원뿔은 1개예요.","원뿔에는 뾰족한 꼭짓점이 있고 원기둥에는 없어요."],"variant_rule":{"alt":[{"stem":"원기둥과 원뿔의 같은 점은 어느 것인가요?","options":[{"t":"밑면이 원이고 옆면이 굽은 면이에요","correct":true},{"t":"밑면의 수가 같아요","mis":"M6-2-u6-X05"},{"t":"꼭짓점이 있어요","mis":"M6-2-u6-X07"},{"t":"모선이 있어요","mis":"M6-2-u6-X15"}],"explanation":["원기둥과 원뿔 모두 밑면이 원이고 옆면이 굽은 면이에요.","원기둥은 밑면이 2개, 원뿔은 1개예요.","원뿔에는 뾰족한 꼭짓점이 있고 원기둥에는 없어요."]},{"stem":"원뿔에는 있고 원기둥에는 없는 것은 어느 것인가요?","options":[{"t":"뾰족한 꼭짓점","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X14"},{"t":"높이","mis":"M6-2-u6-X06"}],"explanation":["원기둥과 원뿔 모두 밑면이 원이고 옆면이 굽은 면이에요.","원기둥은 밑면이 2개, 원뿔은 1개예요.","원뿔에는 뾰족한 꼭짓점이 있고 원기둥에는 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_challenge#6','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',3,'ox','auto','원기둥에도 원이 있으니 원뿔이라고 할 수 있어요.',ARRAY['M6-2-u6-X14']::text[],true,'{"seq":6,"concept":"M6-2-u6-C5","difficulty":3,"kind":"ox","stem":"원기둥에도 원이 있으니 원뿔이라고 할 수 있어요.","answer":"X","reason_options":[{"t":"원기둥은 합동인 원이 두 개이고 뾰족한 점이 없기 때문에","correct":true},{"t":"원이 있으면 모두 원뿔이기 때문에","mis":"M6-2-u6-X14"}],"mis":"M6-2-u6-X14","explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","각뿔은 밑면이 다각형, 원뿔은 원이에요.","직각삼각형을 한 바퀴 돌리면 원뿔이 돼요."],"variant_rule":{"alt":[{"stem":"원뿔의 옆면은 평평한 삼각형이에요.","answer":"X","reason_options":[{"t":"원뿔의 옆면은 굽은 면이기 때문에","correct":true},{"t":"원뿔은 각뿔과 옆면이 같기 때문에","mis":"M6-2-u6-X01"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","각뿔은 밑면이 다각형, 원뿔은 원이에요.","직각삼각형을 한 바퀴 돌리면 원뿔이 돼요."]},{"stem":"직각삼각형을 돌릴 때 막대에 붙인 변은 원뿔의 높이가 돼요.","answer":"O","reason_options":[{"t":"막대에 붙은 변이 꼭짓점에서 밑면에 수직으로 서기 때문에","correct":true},{"t":"막대에 붙인 변은 모선이 되기 때문에","mis":"M6-2-u6-X04"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","각뿔은 밑면이 다각형, 원뿔은 원이에요.","직각삼각형을 한 바퀴 돌리면 원뿔이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_challenge#7','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',2,'sa','auto','『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 반지름은 몇 cm인가요?','{}'::text[],false,'{"seq":7,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","그래서 밑면의 반지름은 7 cm예요."],"mis":"M6-2-u6-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_challenge#8','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',4,'sa','auto','『수학익힘』 91쪽의 직각삼각형(직각을 낀 두 변 5 cm, 7 cm)을 이번에는 7 cm인 변을 기준으로 한 바퀴 돌렸어요. 5 cm인 변을 기준으로 돌린 원뿔과 견주어 밑면의 지름은 몇 cm 짧아지나요?','{}'::text[],false,'{"seq":8,"concept":"M6-2-u6-C5","difficulty":4,"kind":"sa","stem":"『수학익힘』 91쪽의 직각삼각형(직각을 낀 두 변 5 cm, 7 cm)을 이번에는 7 cm인 변을 기준으로 한 바퀴 돌렸어요. 5 cm인 변을 기준으로 돌린 원뿔과 견주어 밑면의 지름은 몇 cm 짧아지나요?","answer":["4"],"explanation":["5 cm 변을 기준으로 돌리면 뻗은 변 7 cm가 반지름 — 지름 14 cm예요.","7 cm 변을 기준으로 돌리면 뻗은 변 5 cm가 반지름 — 지름 10 cm예요.","14 − 10 = 4 cm 짧아져요."],"mis":"M6-2-u6-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_challenge#9','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',4,'essay','teacher','『수학』 132쪽 가(밑면이 다각형인 뿔 모양)와 나(서로 합동인 두 원이 있는 기둥 모양)가 원뿔이 아닌 까닭을 각각 원뿔의 뜻을 써서 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u6-C5","difficulty":4,"kind":"essay","stem":"『수학』 132쪽 가(밑면이 다각형인 뿔 모양)와 나(서로 합동인 두 원이 있는 기둥 모양)가 원뿔이 아닌 까닭을 각각 원뿔의 뜻을 써서 설명해 보세요.","answer_guide":{"answer":"예: 원뿔은 한 원을 면으로 하는 입체도형이다. 가는 원을 면으로 하지 않으므로 원뿔이 아니다. 나는 합동인 두 면(원)이 있으므로 원뿔이 아니다.","scoring_points":["원뿔의 뜻(한 원을 면으로)을 썼는가","가 — 원을 면으로 하지 않음을 썼는가","나 — 합동인 두 면이 있음을 썼는가"]},"explanation":["원뿔 = 한 원을 면으로 하는 입체도형이에요.","가는 원이 없어요.","나는 원이 두 개(합동)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L06_challenge#10','math',6,2,'u6','L06','tb_g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',4,'essay','teacher','원기둥과 원뿔은 모두 원을 면으로 해요. 두 입체도형을 가르는 차이를 원의 개수와 뾰족한 점을 넣어 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C5","difficulty":4,"kind":"essay","stem":"원기둥과 원뿔은 모두 원을 면으로 해요. 두 입체도형을 가르는 차이를 원의 개수와 뾰족한 점을 넣어 설명해 보세요.","answer_guide":{"answer":"예: 원기둥은 서로 평행하고 합동인 두 원을 면으로 하고 뾰족한 점이 없다. 원뿔은 한 원만 면으로 하고 뾰족한 점(원뿔의 꼭짓점)이 하나 있다.","scoring_points":["원기둥은 원이 2개(평행·합동)임을 썼는가","원뿔은 원이 1개임을 썼는가","원뿔에만 뾰족한 점이 있음을 썼는가"]},"explanation":["원기둥은 원 2개예요.","원뿔은 원 1개예요.","원뿔에만 뾰족한 점이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_basic#1','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',1,'mc','auto','원뿔에서 면이 되는 원을 무엇이라고 하나요?',ARRAY['M6-2-u6-X15','M6-2-u6-X05']::text[],true,'{"seq":1,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"원뿔에서 면이 되는 원을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","면이 되는 원을 밑면이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."],"variant_rule":{"alt":[{"stem":"원뿔에서 밑면과 만나는 굽은 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","밑면과 만나는 굽은 면을 옆면이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]},{"stem":"원뿔에서 뾰족한 부분의 점을 무엇이라고 하나요?","options":[{"t":"원뿔의 꼭짓점","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","뾰족한 부분의 점을 원뿔의 꼭짓점이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_basic#2','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',1,'mc','auto','원뿔에서 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 무엇이라고 하나요?',ARRAY['M6-2-u6-X15','M6-2-u6-X05']::text[],true,'{"seq":2,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"원뿔에서 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"모선","correct":true},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 모선이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."],"variant_rule":{"alt":[{"stem":"원뿔에서 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 높이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_basic#3','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',1,'sa','auto','원뿔의 밑면은 몇 개인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u6-C6","difficulty":1,"kind":"sa","stem":"원뿔의 밑면은 몇 개인가요?","answer":["1"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔의 밑면은 원 하나 — 1개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"원뿔의 꼭짓점은 몇 개인가요?","answer":["1"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔의 꼭짓점은 뾰족한 점 하나 — 1개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_basic#4','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',1,'mc','auto','원뿔 모형에서 뾰족한 부분의 점에서 색칠한 원까지의 거리를 재려고 해요. 어떻게 재어야 하나요?',ARRAY['M6-2-u6-X15']::text[],false,'{"seq":4,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"원뿔 모형에서 뾰족한 부분의 점에서 색칠한 원까지의 거리를 재려고 해요. 어떻게 재어야 하나요?","options":[{"t":"자와 삼각자를 사용하여 뾰족한 점에서 밑면에 수직으로 재요","correct":true},{"t":"뾰족한 점에서 원의 둘레까지 옆면을 따라 비스듬히 재요","mis":"M6-2-u6-X15"},{"t":"원의 지름을 재요","mis":"M6-2-u6-X15"},{"t":"원의 둘레를 재요","mis":"M6-2-u6-X15"}],"explanation":["뾰족한 점에서 밑면까지의 거리는 수직으로 재요.","자와 삼각자(곱자·직각자)를 써요.","이 길이가 원뿔의 높이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_basic#5','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',2,'sa','auto','원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 13 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 13 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["12"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 높이는 12 cm예요 — 13 cm는 모선이에요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 4 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 5 cm, 밑면의 반지름은 3 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["4"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 높이는 4 cm예요 — 5 cm는 모선이에요."]},{"stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 15 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 17 cm, 밑면의 반지름은 8 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["15"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 높이는 15 cm예요 — 17 cm는 모선이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_basic#6','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',2,'sa','auto','원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 13 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 13 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["13"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 모선의 길이는 13 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 4 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 5 cm, 밑면의 반지름은 3 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["5"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 모선의 길이는 5 cm예요."]},{"stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 15 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 17 cm, 밑면의 반지름은 8 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["17"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 모선의 길이는 17 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_basic#7','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',2,'error','auto','『수학익힘』 91쪽 — 원뿔에 대해 말한 친구들이에요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X19']::text[],false,'{"seq":7,"concept":"M6-2-u6-C6","difficulty":2,"kind":"error","stem":"『수학익힘』 91쪽 — 원뿔에 대해 말한 친구들이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지석 — 「원뿔에서 밑면은 2개예요.」","correct":true,"mis_target":"M6-2-u6-X05"},{"t":"민지 — 「원뿔의 옆면은 굽은 면이에요.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「원뿔의 꼭짓점은 1개예요.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「원뿔의 밑면은 원이에요.」","mis":"M6-2-u6-X19"}],"explanation":["원뿔은 한 원을 면으로 해요.","그래서 원뿔에서 밑면은 1개예요.","지석의 말을 「원뿔에서 밑면은 1개예요.」로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_basic#8','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',2,'mc','auto','원뿔의 모선이 높이보다 긴 까닭은 무엇인가요?',ARRAY['M6-2-u6-X16','M6-2-u6-X15']::text[],true,'{"seq":8,"concept":"M6-2-u6-C6","difficulty":2,"kind":"mc","stem":"원뿔의 모선이 높이보다 긴 까닭은 무엇인가요?","options":[{"t":"모선은 둘레까지 비스듬히 가고 높이는 한가운데까지 곧게 가서","correct":true},{"t":"모선이 여러 개여서","mis":"M6-2-u6-X16"},{"t":"밑면이 원이어서","mis":"M6-2-u6-X15"},{"t":"높이를 잴 수 없어서","mis":"M6-2-u6-X15"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."],"variant_rule":{"alt":[{"stem":"원뿔의 모선은 몇 개인가요?","options":[{"t":"무수히 많아요","correct":true},{"t":"1개","mis":"M6-2-u6-X16"},{"t":"2개","mis":"M6-2-u6-X16"},{"t":"4개","mis":"M6-2-u6-X16"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."]},{"stem":"한 원뿔에서 모선의 길이는 어떤가요?","options":[{"t":"모두 같아요","correct":true},{"t":"모두 달라요","mis":"M6-2-u6-X16"},{"t":"둘레 쪽으로 갈수록 길어져요","mis":"M6-2-u6-X16"},{"t":"높이와 같아요","mis":"M6-2-u6-X15"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_basic#9','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',2,'ox','auto','원뿔의 모선은 하나뿐이에요.',ARRAY['M6-2-u6-X16']::text[],true,'{"seq":9,"concept":"M6-2-u6-C6","difficulty":2,"kind":"ox","stem":"원뿔의 모선은 하나뿐이에요.","answer":"X","reason_options":[{"t":"밑면 둘레의 점마다 모선을 그을 수 있어 무수히 많기 때문에","correct":true},{"t":"원뿔의 꼭짓점이 하나이기 때문에","mis":"M6-2-u6-X16"}],"mis":"M6-2-u6-X16","explanation":["원뿔은 밑면 1개, 꼭짓점 1개예요.","모선은 무수히 많고 길이가 모두 같아요.","높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 모선보다 짧아요."],"variant_rule":{"alt":[{"stem":"원뿔의 높이는 모선보다 짧아요.","answer":"O","reason_options":[{"t":"높이는 곧게, 모선은 비스듬히 내려가기 때문에","correct":true},{"t":"높이는 밑면의 지름과 같기 때문에","mis":"M6-2-u6-X15"}],"explanation":["원뿔은 밑면 1개, 꼭짓점 1개예요.","모선은 무수히 많고 길이가 모두 같아요.","높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 모선보다 짧아요."]},{"stem":"원뿔의 밑면은 1개예요.","answer":"O","reason_options":[{"t":"원뿔은 한 원을 면으로 하기 때문에","correct":true},{"t":"원뿔은 원기둥처럼 원이 두 개이기 때문에","mis":"M6-2-u6-X05"}],"explanation":["원뿔은 밑면 1개, 꼭짓점 1개예요.","모선은 무수히 많고 길이가 모두 같아요.","높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 모선보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_basic#10','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',3,'sa','auto','밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C6","difficulty":3,"kind":"sa","stem":"밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["20"],"explanation":["밑면의 지름은 6 × 2 = 12 cm예요.","높이는 8 cm예요 — 모선 10 cm는 쓰지 않아요.","12 + 8 = 20 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"밑면의 반지름이 3 cm, 높이가 4 cm, 모선이 5 cm인 원뿔이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["10"],"explanation":["밑면의 지름은 3 × 2 = 6 cm예요.","높이는 4 cm예요 — 모선 5 cm는 쓰지 않아요.","6 + 4 = 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_challenge#1','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',3,'match','auto','원뿔에 대해 알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C6","difficulty":3,"kind":"match","stem":"원뿔에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"뾰족한 부분의 점","r":"원뿔의 꼭짓점"},{"l":"꼭짓점과 밑면 둘레의 한 점을 이은 선분","r":"모선"},{"l":"꼭짓점에서 밑면에 수직으로 내린 선분의 길이","r":"높이"}],"mis":"M6-2-u6-X15","explanation":["뾰족한 점은 원뿔의 꼭짓점이에요.","꼭짓점과 둘레의 한 점을 이은 선분은 모선 — 무수히 많아요.","꼭짓점에서 밑면에 수직으로 내린 선분의 길이가 높이예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원뿔에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"원뿔의 밑면","r":"원 1개"},{"l":"원뿔의 모선","r":"무수히 많음"},{"l":"원뿔의 꼭짓점","r":"1개"}],"explanation":["뾰족한 점은 원뿔의 꼭짓점이에요.","꼭짓점과 둘레의 한 점을 이은 선분은 모선 — 무수히 많아요.","꼭짓점에서 밑면에 수직으로 내린 선분의 길이가 높이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_challenge#2','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',2,'ox','auto','원뿔의 모선은 면과 면이 만나는 선분이니 모서리라고 할 수 있어요.',ARRAY['M6-2-u6-X21']::text[],false,'{"seq":2,"concept":"M6-2-u6-C6","difficulty":2,"kind":"ox","stem":"원뿔의 모선은 면과 면이 만나는 선분이니 모서리라고 할 수 있어요.","answer":"X","reason_options":[{"t":"원뿔에는 평면이 밑면뿐이라 평면과 평면이 만나는 선분인 모서리가 없기 때문에","correct":true},{"t":"모선도 모서리처럼 선분이기 때문에","mis":"M6-2-u6-X21"}],"mis":"M6-2-u6-X21","explanation":["모서리는 평면과 평면이 만나는 선분이에요.","원뿔에서 평면은 밑면 하나뿐이에요.","모선은 꼭짓점과 밑면 둘레의 한 점을 이은 선분이지 모서리가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_challenge#3','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',3,'error','auto','밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X15','M6-2-u6-X19']::text[],false,'{"seq":3,"concept":"M6-2-u6-C6","difficulty":3,"kind":"error","stem":"밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「이 원뿔의 높이는 10 cm야.」","correct":true,"mis_target":"M6-2-u6-X15"},{"t":"민지 — 「모선이 높이보다 길어.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「밑면의 지름은 12 cm야.」","mis":"M6-2-u6-X19"},{"t":"지석 — 「모선은 무수히 많고 길이가 모두 10 cm야.」","mis":"M6-2-u6-X19"}],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 8 cm예요.","10 cm는 모선의 길이예요.","그래서 여울의 말이 잘못되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_challenge#4','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',2,'sa','auto','단원 평가 — 모선의 길이가 17 cm, 높이가 15 cm, 밑면의 반지름이 8 cm인 원뿔과 반지름이 8 cm인 구가 있어요. 원뿔의 모선의 길이와 구의 지름의 차는 몇 cm인가요?','{}'::text[],false,'{"seq":4,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"단원 평가 — 모선의 길이가 17 cm, 높이가 15 cm, 밑면의 반지름이 8 cm인 원뿔과 반지름이 8 cm인 구가 있어요. 원뿔의 모선의 길이와 구의 지름의 차는 몇 cm인가요?","answer":["1"],"explanation":["원뿔의 모선의 길이는 17 cm예요.","구의 지름은 8 × 2 = 16 cm예요.","17 − 16 = 1 cm예요."],"mis":"M6-2-u6-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_challenge#5','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',3,'mc','auto','한 원뿔에서 두 선분의 길이가 8 cm와 10 cm예요. 이 원뿔의 높이는 어느 것인가요?',ARRAY['M6-2-u6-X15','M6-2-u6-X16','M6-2-u6-X19']::text[],true,'{"seq":5,"concept":"M6-2-u6-C6","difficulty":3,"kind":"mc","stem":"한 원뿔에서 두 선분의 길이가 8 cm와 10 cm예요. 이 원뿔의 높이는 어느 것인가요?","options":[{"t":"8 cm","correct":true},{"t":"10 cm","mis":"M6-2-u6-X15"},{"t":"두 선분 모두 높이예요","mis":"M6-2-u6-X16"},{"t":"알 수 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔에서 모선은 높이보다 길어요.","모선은 둘레까지 비스듬히, 높이는 한가운데까지 곧게 가요.","그래서 짧은 8 cm가 높이, 긴 10 cm가 모선이에요."],"variant_rule":{"alt":[{"stem":"한 원뿔에서 두 선분의 길이가 12 cm와 13 cm예요. 이 원뿔의 높이는 어느 것인가요?","options":[{"t":"12 cm","correct":true},{"t":"13 cm","mis":"M6-2-u6-X15"},{"t":"두 선분 모두 높이예요","mis":"M6-2-u6-X16"},{"t":"알 수 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔에서 모선은 높이보다 길어요.","모선은 둘레까지 비스듬히, 높이는 한가운데까지 곧게 가요.","그래서 짧은 12 cm가 높이, 긴 13 cm가 모선이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_challenge#6','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',3,'mc','auto','단원 평가 — 원뿔의 꼭짓점 ㄱ에서 선분 ㄱㄴ, 선분 ㄱㄷ, 선분 ㄱㄹ은 밑면의 둘레까지, 선분 ㄱㅂ은 밑면의 중심까지 수직으로 그었어요. 길이가 다른 선분은 어느 것인가요?',ARRAY['M6-2-u6-X16']::text[],false,'{"seq":6,"concept":"M6-2-u6-C6","difficulty":3,"kind":"mc","stem":"단원 평가 — 원뿔의 꼭짓점 ㄱ에서 선분 ㄱㄴ, 선분 ㄱㄷ, 선분 ㄱㄹ은 밑면의 둘레까지, 선분 ㄱㅂ은 밑면의 중심까지 수직으로 그었어요. 길이가 다른 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㅂ","correct":true},{"t":"선분 ㄱㄴ","mis":"M6-2-u6-X16"},{"t":"선분 ㄱㄷ","mis":"M6-2-u6-X16"},{"t":"선분 ㄱㄹ","mis":"M6-2-u6-X16"}],"explanation":["꼭짓점과 밑면 둘레의 한 점을 이은 선분은 모두 모선이에요.","한 원뿔에서 모선의 길이는 모두 같아요.","선분 ㄱㅂ은 높이 — 모선보다 짧아 길이가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_challenge#7','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',3,'ox','auto','원뿔의 높이는 꼭짓점과 밑면 둘레의 한 점을 이은 선분이에요.',ARRAY['M6-2-u6-X15']::text[],false,'{"seq":7,"concept":"M6-2-u6-C6","difficulty":3,"kind":"ox","stem":"원뿔의 높이는 꼭짓점과 밑면 둘레의 한 점을 이은 선분이에요.","answer":"X","reason_options":[{"t":"그 선분은 모선이고 높이는 밑면에 수직으로 내린 선분의 길이이기 때문에","correct":true},{"t":"높이와 모선은 같은 뜻이기 때문에","mis":"M6-2-u6-X15"}],"mis":"M6-2-u6-X15","explanation":["원뿔은 밑면 1개, 꼭짓점 1개예요.","모선은 무수히 많고 길이가 모두 같아요.","높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 모선보다 짧아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_challenge#8','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',4,'essay','teacher','『수학익힘』 91쪽 — 지석이가 「원뿔에서 밑면은 2개예요.」라고 말했어요. 잘못된 문장을 바르게 고쳐 쓰고, 원기둥과 견주어 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u6-C6","difficulty":4,"kind":"essay","stem":"『수학익힘』 91쪽 — 지석이가 「원뿔에서 밑면은 2개예요.」라고 말했어요. 잘못된 문장을 바르게 고쳐 쓰고, 원기둥과 견주어 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원뿔에서 밑면은 1개입니다. 원뿔은 한 원을 면으로 하는 입체도형이므로 밑면이 원 하나뿐이다. 서로 평행하고 합동인 두 원이 밑면인 원기둥은 밑면이 2개이다.","scoring_points":["「밑면은 1개」로 고쳐 썼는가","원뿔은 한 원을 면으로 한다는 까닭을 썼는가","원기둥(밑면 2개)과 견주었는가"]},"explanation":["원뿔의 밑면은 1개예요.","원뿔은 한 원을 면으로 해요.","원기둥은 밑면이 2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_challenge#9','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',4,'sa','auto','단원 평가 — 모선의 길이가 5 cm, 높이가 4 cm, 밑면의 지름이 6 cm인 원뿔이 있어요. 모선의 길이와 높이와 밑면의 지름을 모두 더하면 몇 cm인가요?','{}'::text[],false,'{"seq":9,"concept":"M6-2-u6-C6","difficulty":4,"kind":"sa","stem":"단원 평가 — 모선의 길이가 5 cm, 높이가 4 cm, 밑면의 지름이 6 cm인 원뿔이 있어요. 모선의 길이와 높이와 밑면의 지름을 모두 더하면 몇 cm인가요?","answer":["15"],"explanation":["모선 5 cm, 높이 4 cm, 밑면의 지름 6 cm예요.","모선은 비스듬히, 높이는 곧게 — 5 > 4로 모선이 더 길어요.","5 + 4 + 6 = 15 cm예요."],"mis":"M6-2-u6-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L07_challenge#10','math',6,2,'u6','L07','tb_g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',4,'essay','teacher','종이에 컴퍼스로 원을 그려 자르고, 반지름을 따라 자른 다음 겹쳐서 밑면이 없는 원뿔 모형을 만들었어요. 이 모형에서 원의 반지름이었던 선분은 원뿔의 무엇이 되는지 쓰고, 그 선분과 원뿔의 높이 중 어느 것이 더 긴지 까닭과 함께 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C6","difficulty":4,"kind":"essay","stem":"종이에 컴퍼스로 원을 그려 자르고, 반지름을 따라 자른 다음 겹쳐서 밑면이 없는 원뿔 모형을 만들었어요. 이 모형에서 원의 반지름이었던 선분은 원뿔의 무엇이 되는지 쓰고, 그 선분과 원뿔의 높이 중 어느 것이 더 긴지 까닭과 함께 설명해 보세요.","answer_guide":{"answer":"예: 원의 반지름이었던 선분은 원뿔의 꼭짓점과 밑면 둘레의 한 점을 잇는 모선이 된다. 모선은 꼭짓점에서 둘레까지 비스듬히 가고 높이는 꼭짓점에서 밑면에 수직으로 내려가므로 모선이 높이보다 길다.","scoring_points":["반지름 → 모선이 됨을 썼는가","모선이 높이보다 길다고 썼는가","비스듬히 vs 수직 까닭을 썼는가"]},"explanation":["원의 반지름 → 원뿔의 모선이에요.","모선은 비스듬히, 높이는 수직이에요.","그래서 모선이 높이보다 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_basic#1','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',1,'mc','auto','구는 어떻게 만든 입체도형인가요?',ARRAY['M6-2-u6-X03','M6-2-u6-X14']::text[],true,'{"seq":1,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"구는 어떻게 만든 입체도형인가요?","options":[{"t":"지름을 따라 반으로 나눈 원을 지름을 기준으로 한 바퀴 돌려서 만든 입체도형","correct":true},{"t":"직사각형을 한 바퀴 돌려서 만든 입체도형","mis":"M6-2-u6-X03"},{"t":"직각삼각형을 한 바퀴 돌려서 만든 입체도형","mis":"M6-2-u6-X03"},{"t":"합동인 두 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."],"variant_rule":{"alt":[{"stem":"돌리기 전 반원의 중심은 만들어진 구의 무엇이 되나요?","options":[{"t":"구의 중심","correct":true},{"t":"구의 반지름","mis":"M6-2-u6-X17"},{"t":"구의 밑면","mis":"M6-2-u6-X07"},{"t":"구의 꼭짓점","mis":"M6-2-u6-X07"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."]},{"stem":"돌리기 전 반원의 반지름은 만들어진 구의 무엇이 되나요?","options":[{"t":"구의 반지름","correct":true},{"t":"구의 중심","mis":"M6-2-u6-X17"},{"t":"구의 지름","mis":"M6-2-u6-X04"},{"t":"구의 둘레","mis":"M6-2-u6-X17"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_basic#2','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',1,'mc','auto','구를 앞에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":2,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"구를 앞에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 구를 앞에서 본 모양은 원이에요."],"variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 앞에서 본 모양은 직사각형이에요."]},{"stem":"원뿔을 옆에서 본 모양은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 옆에서 본 모양은 삼각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_basic#3','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',1,'mc','auto','축구공, 농구공, 야구공, 테니스공이 데굴데굴 굴러가요. 모두 크기만 다를 뿐 모양이 같아요. 이 공 모양에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['M6-2-u6-X07','M6-2-u6-X05']::text[],false,'{"seq":3,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"축구공, 농구공, 야구공, 테니스공이 데굴데굴 굴러가요. 모두 크기만 다를 뿐 모양이 같아요. 이 공 모양에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"평평한 면이 없고 굽은 면으로만 이루어져 있어요","correct":true},{"t":"평평한 면이 1개 있어요","mis":"M6-2-u6-X07"},{"t":"뾰족한 부분이 1개 있어요","mis":"M6-2-u6-X07"},{"t":"밑면이 2개 있어요","mis":"M6-2-u6-X05"}],"explanation":["공 모양에는 뾰족한 부분이 없어요.","평평한 면도 없어요.","굽은 면으로만 이루어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_basic#4','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',1,'mc','auto','원기둥·원뿔·구 가운데 어느 방향에서 보아도 모양이 같은 입체도형은 무엇인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":4,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"원기둥·원뿔·구 가운데 어느 방향에서 보아도 모양이 같은 입체도형은 무엇인가요?","options":[{"t":"구","correct":true},{"t":"원기둥","mis":"M6-2-u6-X18"},{"t":"원뿔","mis":"M6-2-u6-X18"},{"t":"세 가지 모두","mis":"M6-2-u6-X18"}],"explanation":["구는 한 점에서 같은 거리에 있는 점들로 이루어져 어느 쪽에서 보아도 원이에요.","원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞에서 보면 원기둥은 직사각형, 원뿔은 삼각형이에요."],"variant_rule":{"alt":[{"stem":"원기둥·원뿔·구를 위에서 본 모양은 어떤가요?","options":[{"t":"모두 원이에요","correct":true},{"t":"모두 다른 모양이에요","mis":"M6-2-u6-X18"},{"t":"원기둥만 원이에요","mis":"M6-2-u6-X18"},{"t":"구만 원이에요","mis":"M6-2-u6-X18"}],"explanation":["구는 한 점에서 같은 거리에 있는 점들로 이루어져 어느 쪽에서 보아도 원이에요.","원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞에서 보면 원기둥은 직사각형, 원뿔은 삼각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_basic#5','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',2,'mc','auto','『수학』 135쪽 — 가 공 모양 · 나 납작하게 눌린 둥근 모양 · 다 길쭉한 달걀 모양 · 라 작은 공 모양. 구를 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X22']::text[],false,'{"seq":5,"concept":"M6-2-u6-C7","difficulty":2,"kind":"mc","stem":"『수학』 135쪽 — 가 공 모양 · 나 납작하게 눌린 둥근 모양 · 다 길쭉한 달걀 모양 · 라 작은 공 모양. 구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가, 나, 다, 라","mis":"M6-2-u6-X22"},{"t":"가","mis":"M6-2-u6-X22"},{"t":"가, 다, 라","mis":"M6-2-u6-X22"}],"explanation":["구는 어느 방향에서 보아도 모양이 원으로 같아요.","나와 다는 보는 방향에 따라 모양이 달라요.","그래서 구는 가와 라예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_basic#6','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',2,'sa','auto','반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C7","difficulty":2,"kind":"sa","stem":"반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["돌리기 전 원의 반지름은 구의 반지름이 돼요.","반원의 반지름이 8 cm예요.","그래서 구의 반지름은 8 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 6 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["12"],"explanation":["돌리기 전 원의 반지름이 구의 반지름 — 6 cm예요.","구의 지름은 반지름의 2배예요.","6 × 2 = 12 cm예요."]},{"stem":"반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["8"],"explanation":["돌리기 전 원의 반지름이 구의 반지름 — 4 cm예요.","구의 지름은 반지름의 2배예요.","4 × 2 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_basic#7','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',2,'mc','auto','구에 대해 바르게 설명한 것은 어느 것인가요?',ARRAY['M6-2-u6-X17','M6-2-u6-X05','M6-2-u6-X07']::text[],true,'{"seq":7,"concept":"M6-2-u6-C7","difficulty":2,"kind":"mc","stem":"구에 대해 바르게 설명한 것은 어느 것인가요?","options":[{"t":"구의 반지름은 무수히 많고 그 길이가 모두 같아요","correct":true},{"t":"구의 반지름은 무수히 많고 그 길이가 모두 달라요","mis":"M6-2-u6-X17"},{"t":"구는 밑면이 2개 있어요","mis":"M6-2-u6-X05"},{"t":"구에는 꼭짓점이 1개 있어요","mis":"M6-2-u6-X07"}],"explanation":["구의 반지름은 구의 중심에서 겉면의 한 점까지예요.","겉면의 점마다 그을 수 있어 무수히 많아요.","중심에서 겉면까지의 거리는 어디나 같아 길이도 모두 같아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 구에 대해 바르게 설명한 것은 어느 것인가요?","options":[{"t":"구의 중심은 1개예요","correct":true},{"t":"구의 중심은 무수히 많아요","mis":"M6-2-u6-X17"},{"t":"구에는 평평한 면이 1개 있어요","mis":"M6-2-u6-X07"},{"t":"구를 앞에서 보면 반원이에요","mis":"M6-2-u6-X18"}],"explanation":["반원의 중심이 구의 중심이 되니 구의 중심은 1개예요.","구는 굽은 면으로만 이루어져 평평한 면이 없어요.","구는 어느 방향에서 보아도 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_basic#8','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',2,'sa','auto','원기둥·원뿔·구의 평평한 면의 수를 모두 더하면 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C7","difficulty":2,"kind":"sa","stem":"원기둥·원뿔·구의 평평한 면의 수를 모두 더하면 몇 개인가요?","answer":["3"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원기둥 2개, 원뿔 1개, 구 0개 — 2 + 1 + 0 = 3개예요."],"mis":"M6-2-u6-X07","variant_rule":{"alt":[{"stem":"「알지오매스 키즈」로 원기둥 1개, 원뿔 1개, 구 2개를 이용하여 나만의 운송 수단을 만들었어요(구로 바퀴를, 원뿔로 운전석을 표현). 쓴 입체도형의 평평한 면은 모두 몇 개인가요?","answer":["3"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","원기둥 1개 2개 + 원뿔 1개 1개 + 구 2개 0개예요.","2 + 1 + 0 = 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_basic#9','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',2,'ox','auto','구를 앞에서 본 모양은 반원이에요.',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":9,"concept":"M6-2-u6-C7","difficulty":2,"kind":"ox","stem":"구를 앞에서 본 모양은 반원이에요.","answer":"X","reason_options":[{"t":"구는 어느 방향에서 보아도 원이기 때문에","correct":true},{"t":"반원을 돌려 만들었기 때문에","mis":"M6-2-u6-X18"}],"mis":"M6-2-u6-X18","explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."],"variant_rule":{"alt":[{"stem":"구의 반지름은 방향에 따라 길이가 달라요.","answer":"X","reason_options":[{"t":"구의 중심에서 겉면의 어느 점까지나 거리가 같기 때문에","correct":true},{"t":"구는 공처럼 찌그러질 수 있기 때문에","mis":"M6-2-u6-X17"}],"explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_basic#10','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',3,'mc','auto','『수학익힘』 93쪽 — ㉠ 구는 꼭짓점이 없어요. ㉡ 구는 밑면이 2개 있어요. ㉢ 구의 중심은 1개예요. ㉣ 구의 반지름은 무수히 많고 그 길이가 모두 달라요. 바르게 설명한 것을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X17']::text[],false,'{"seq":10,"concept":"M6-2-u6-C7","difficulty":3,"kind":"mc","stem":"『수학익힘』 93쪽 — ㉠ 구는 꼭짓점이 없어요. ㉡ 구는 밑면이 2개 있어요. ㉢ 구의 중심은 1개예요. ㉣ 구의 반지름은 무수히 많고 그 길이가 모두 달라요. 바르게 설명한 것을 모두 찾은 것은 어느 것인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠, ㉡","mis":"M6-2-u6-X05"},{"t":"㉢, ㉣","mis":"M6-2-u6-X17"},{"t":"㉠, ㉢, ㉣","mis":"M6-2-u6-X17"}],"explanation":["구에는 평평한 면이 없어 밑면도 없어요 — ㉡은 틀려요.","구의 반지름은 무수히 많고 길이가 모두 같아요 — ㉣은 틀려요.","그래서 바른 것은 ㉠, ㉢이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_challenge#1','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C7","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"원기둥을 앞에서","r":"직사각형"},{"l":"원뿔을 앞에서","r":"삼각형"},{"l":"구를 앞에서","r":"원"}],"mis":"M6-2-u6-X18","explanation":["원기둥은 앞에서 직사각형, 원뿔은 삼각형, 구는 원이에요.","반원의 중심은 구의 중심, 반지름은 구의 반지름이 돼요.","평평한 면은 원기둥 2개, 원뿔 1개, 구 0개예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"반원의 중심","r":"구의 중심"},{"l":"반원의 반지름","r":"구의 반지름"},{"l":"반원을 돌린 입체도형","r":"구"}],"explanation":["원기둥은 앞에서 직사각형, 원뿔은 삼각형, 구는 원이에요.","반원의 중심은 구의 중심, 반지름은 구의 반지름이 돼요.","평평한 면은 원기둥 2개, 원뿔 1개, 구 0개예요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원기둥의 평평한 면","r":"2개"},{"l":"원뿔의 평평한 면","r":"1개"},{"l":"구의 평평한 면","r":"0개"}],"explanation":["원기둥은 앞에서 직사각형, 원뿔은 삼각형, 구는 원이에요.","반원의 중심은 구의 중심, 반지름은 구의 반지름이 돼요.","평평한 면은 원기둥 2개, 원뿔 1개, 구 0개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_challenge#2','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',2,'mc','auto','「알지오매스 키즈」에서 만든 원기둥, 원뿔, 구를 원하는 크기로 바꿀 때 주의할 점으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X14','M6-2-u6-X22','M6-2-u6-X19']::text[],false,'{"seq":2,"concept":"M6-2-u6-C7","difficulty":2,"kind":"mc","stem":"「알지오매스 키즈」에서 만든 원기둥, 원뿔, 구를 원하는 크기로 바꿀 때 주의할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"배율 모드에서 크기를 바꿀 때 도형의 모양이 바뀌지 않게 해요","correct":true},{"t":"크기를 바꾸면 원기둥이 원뿔로 바뀌어요","mis":"M6-2-u6-X14"},{"t":"구는 크기를 바꿀 수 없어요","mis":"M6-2-u6-X22"},{"t":"이동 모드에서만 크기를 바꿀 수 있어요","mis":"M6-2-u6-X19"}],"explanation":["이동 모드는 도형을 원하는 위치로 옮겨요.","배율 모드는 도형을 원하는 크기로 조절해요.","이때 도형의 모양이 바뀌지 않도록 주의해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_challenge#3','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',3,'error','auto','구에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X18','M6-2-u6-X19']::text[],false,'{"seq":3,"concept":"M6-2-u6-C7","difficulty":3,"kind":"error","stem":"구에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서우 — 「구를 옆에서 보면 반원이야.」","correct":true,"mis_target":"M6-2-u6-X18"},{"t":"여울 — 「구의 중심은 1개야.」","mis":"M6-2-u6-X19"},{"t":"지석 — 「구의 반지름은 모두 길이가 같아.」","mis":"M6-2-u6-X19"},{"t":"민지 — 「구에는 평평한 면이 없어.」","mis":"M6-2-u6-X19"}],"explanation":["구는 어느 방향에서 보아도 원이에요.","반원은 구를 만들 때 돌린 모양일 뿐이에요.","그래서 서우의 말이 잘못되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_challenge#4','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',3,'ox','auto','반쪽 공처럼 둥글고 굽은 면이 있는 모양이면 모두 구라고 할 수 있어요.',ARRAY['M6-2-u6-X22']::text[],false,'{"seq":4,"concept":"M6-2-u6-C7","difficulty":3,"kind":"ox","stem":"반쪽 공처럼 둥글고 굽은 면이 있는 모양이면 모두 구라고 할 수 있어요.","answer":"X","reason_options":[{"t":"구는 어느 방향에서 보아도 모양이 원으로 같아야 하기 때문에","correct":true},{"t":"굽은 면이 있으면 모두 구이기 때문에","mis":"M6-2-u6-X22"}],"mis":"M6-2-u6-X22","explanation":["반쪽 공은 평평한 면이 있고, 옆에서 보면 반원이에요.","구는 어느 방향에서 보아도 원이에요.","그래서 둥글다고 모두 구는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_challenge#5','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',3,'sa','auto','원기둥 2개와 원뿔 1개의 평평한 면은 모두 몇 개인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u6-C7","difficulty":3,"kind":"sa","stem":"원기둥 2개와 원뿔 1개의 평평한 면은 모두 몇 개인가요?","answer":["5"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원기둥 하나에 2개씩 4개, 원뿔 1개 — 4 + 1 = 5개예요."],"mis":"M6-2-u6-X07","variant_rule":{"alt":[{"stem":"원뿔 3개와 구 2개의 평평한 면은 모두 몇 개인가요?","answer":["3"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원뿔 하나에 1개씩 3개, 구는 0개 — 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_challenge#6','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',3,'sa','auto','원기둥 1개, 원뿔 1개, 구 2개로 만든 운송 수단이 있어요. 쓴 입체도형에서 뾰족한 꼭짓점은 모두 몇 개인가요?','{}'::text[],false,'{"seq":6,"concept":"M6-2-u6-C7","difficulty":3,"kind":"sa","stem":"원기둥 1개, 원뿔 1개, 구 2개로 만든 운송 수단이 있어요. 쓴 입체도형에서 뾰족한 꼭짓점은 모두 몇 개인가요?","answer":["1"],"explanation":["원기둥과 구에는 꼭짓점이 없어요.","원뿔에만 원뿔의 꼭짓점이 1개 있어요.","원뿔 1개 — 모두 1개예요."],"mis":"M6-2-u6-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_challenge#7','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',2,'mc','auto','단원 평가 — 구 위에 원기둥을 붙인 모양과, 원기둥 옆에 원뿔을 붙인 모양이 있어요. 두 모양을 만드는 데 모두 사용한 입체도형은 무엇인가요?',ARRAY['M6-2-u6-X18','M6-2-u6-X01']::text[],false,'{"seq":7,"concept":"M6-2-u6-C7","difficulty":2,"kind":"mc","stem":"단원 평가 — 구 위에 원기둥을 붙인 모양과, 원기둥 옆에 원뿔을 붙인 모양이 있어요. 두 모양을 만드는 데 모두 사용한 입체도형은 무엇인가요?","options":[{"t":"원기둥","correct":true},{"t":"원뿔","mis":"M6-2-u6-X18"},{"t":"구","mis":"M6-2-u6-X18"},{"t":"각기둥","mis":"M6-2-u6-X01"}],"explanation":["첫째 모양은 구와 원기둥으로 만들었어요.","둘째 모양은 원기둥과 원뿔로 만들었어요.","두 모양에 모두 쓴 것은 원기둥이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_challenge#8','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',4,'essay','teacher','원기둥, 원뿔, 구를 위, 앞, 옆에서 본 모양을 견주어 같은 점과 다른 점을 각각 하나 이상 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u6-C7","difficulty":4,"kind":"essay","stem":"원기둥, 원뿔, 구를 위, 앞, 옆에서 본 모양을 견주어 같은 점과 다른 점을 각각 하나 이상 쓰세요.","answer_guide":{"answer":"예: 같은 점 — 원기둥, 원뿔, 구를 위에서 본 모양은 모두 원이다. 다른 점 — 앞이나 옆에서 본 모양이 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이다. 구만 어느 방향에서 보아도 원이다.","scoring_points":["위에서 본 모양이 모두 원임을 썼는가","앞·옆 모양(직사각형·삼각형·원)을 썼는가","구만 어느 방향에서나 원임을 썼는가"]},"explanation":["위에서는 모두 원이에요.","앞·옆은 직사각형·삼각형·원이에요.","구는 어느 방향에서나 원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_challenge#9','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',4,'sa','auto','단원 평가 — 지름을 따라 반으로 나눈 원(반지름 6 cm)을 지름을 기준으로 한 바퀴 돌려서 구를 만들었어요. 이 구를 반으로 자른 면의 지름과, 반지름이 4 cm인 반원을 돌려 만든 구의 지름의 합은 몇 cm인가요?','{}'::text[],false,'{"seq":9,"concept":"M6-2-u6-C7","difficulty":4,"kind":"sa","stem":"단원 평가 — 지름을 따라 반으로 나눈 원(반지름 6 cm)을 지름을 기준으로 한 바퀴 돌려서 구를 만들었어요. 이 구를 반으로 자른 면의 지름과, 반지름이 4 cm인 반원을 돌려 만든 구의 지름의 합은 몇 cm인가요?","answer":["20"],"explanation":["반지름 6 cm인 반원을 돌린 구의 지름은 6 × 2 = 12 cm예요.","반지름 4 cm인 반원을 돌린 구의 지름은 4 × 2 = 8 cm예요.","12 + 8 = 20 cm예요."],"mis":"M6-2-u6-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L08_challenge#10','math',6,2,'u6','L08','tb_g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',4,'essay','teacher','「알지오매스 키즈」로 원기둥 1개, 원뿔 1개, 구 2개를 이용하여 나만의 운송 수단을 만들었어요. 각 입체도형을 어디에 썼는지 소개하는 글을 쓰고, 쓴 입체도형의 평평한 면이 모두 몇 개인지 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C7","difficulty":4,"kind":"essay","stem":"「알지오매스 키즈」로 원기둥 1개, 원뿔 1개, 구 2개를 이용하여 나만의 운송 수단을 만들었어요. 각 입체도형을 어디에 썼는지 소개하는 글을 쓰고, 쓴 입체도형의 평평한 면이 모두 몇 개인지 구해 보세요.","answer_guide":{"answer":"예: 원기둥으로 몸체를, 원뿔로 운전석을, 구 2개로 바퀴를 표현했습니다. 평평한 면은 원기둥 2개, 원뿔 1개, 구 0개이므로 모두 2 + 1 + 0 = 3개입니다.","scoring_points":["원기둥·원뿔·구를 어디에 썼는지 소개했는가","평평한 면 수(원기둥 2·원뿔 1·구 0)를 알맞게 셌는가","모두 3개를 구했는가"]},"explanation":["원기둥·원뿔·구의 쓰임을 소개해요.","평평한 면은 2 + 1 + 0이에요.","모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_basic#1','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',1,'mc','auto','원뿔을 앞에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":1,"concept":"M6-2-u6-C8","difficulty":1,"kind":"mc","stem":"원뿔을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 앞에서 본 모양은 삼각형이에요."],"variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 앞에서 본 모양은 직사각형이에요."]},{"stem":"원기둥을 위에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 위에서 본 모양은 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_basic#2','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',1,'mc','auto','원뿔을 앞에서 본 삼각형의 밑변은 원뿔의 무엇과 길이가 같나요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":2,"concept":"M6-2-u6-C8","difficulty":1,"kind":"mc","stem":"원뿔을 앞에서 본 삼각형의 밑변은 원뿔의 무엇과 길이가 같나요?","options":[{"t":"밑면의 지름","correct":true},{"t":"밑면의 반지름","mis":"M6-2-u6-X20"},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"}],"explanation":["원뿔을 앞에서 보면 밑면인 원이 납작하게 보여요.","원이 지름만큼의 선분으로 보여요.","그래서 삼각형의 밑변은 밑면의 지름과 같아요."],"variant_rule":{"alt":[{"stem":"원뿔을 앞에서 본 삼각형의 높이는 원뿔의 무엇과 길이가 같나요?","options":[{"t":"원뿔의 높이","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"밑면의 지름","mis":"M6-2-u6-X18"},{"t":"밑면의 반지름","mis":"M6-2-u6-X18"}],"explanation":["삼각형의 꼭짓점이 원뿔의 꼭짓점이에요.","꼭짓점에서 밑변에 수직으로 내린 길이가 삼각형의 높이예요.","그래서 원뿔의 높이와 같아요 — 모선은 삼각형의 옆 변이에요."]},{"stem":"원뿔을 앞에서 본 삼각형의 두 옆 변은 원뿔의 무엇과 길이가 같나요?","options":[{"t":"모선","correct":true},{"t":"원뿔의 높이","mis":"M6-2-u6-X15"},{"t":"밑면의 지름","mis":"M6-2-u6-X18"},{"t":"밑면의 반지름","mis":"M6-2-u6-X18"}],"explanation":["앞에서 보면 꼭짓점에서 밑면의 양 끝까지 비스듬한 선이 보여요.","꼭짓점과 밑면 둘레의 한 점을 이은 선분이 모선이에요.","그래서 두 옆 변은 모선과 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_basic#3','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',1,'mc','auto','원뿔을 앞에서 본 모양의 넓이를 구하려면 무엇을 알아야 하나요?',ARRAY['M6-2-u6-X15','M6-2-u6-X20','M6-2-u6-X18']::text[],true,'{"seq":3,"concept":"M6-2-u6-C8","difficulty":1,"kind":"mc","stem":"원뿔을 앞에서 본 모양의 넓이를 구하려면 무엇을 알아야 하나요?","options":[{"t":"삼각형의 밑변의 길이와 높이","correct":true},{"t":"삼각형의 두 옆 변(모선)의 길이","mis":"M6-2-u6-X15"},{"t":"밑면의 반지름만","mis":"M6-2-u6-X20"},{"t":"직사각형의 가로와 세로","mis":"M6-2-u6-X18"}],"explanation":["원뿔을 앞에서 보면 삼각형이에요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","그래서 밑변의 길이와 높이를 알아야 해요."],"variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 모양의 넓이를 구하려면 무엇을 알아야 하나요?","options":[{"t":"직사각형의 가로와 세로","correct":true},{"t":"밑면의 둘레와 높이","mis":"M6-2-u6-X08"},{"t":"삼각형의 밑변의 길이와 높이","mis":"M6-2-u6-X18"},{"t":"밑면의 반지름과 둘레","mis":"M6-2-u6-X20"}],"explanation":["원기둥을 앞에서 보면 직사각형이에요.","직사각형의 넓이는 (가로) × (세로)예요.","가로는 밑면의 지름, 세로는 높이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_basic#4','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',1,'mc','auto','원기둥을 앞에서 본 직사각형의 가로와 세로는 원기둥의 무엇과 같나요?',ARRAY['M6-2-u6-X08','M6-2-u6-X20','M6-2-u6-X09']::text[],false,'{"seq":4,"concept":"M6-2-u6-C8","difficulty":1,"kind":"mc","stem":"원기둥을 앞에서 본 직사각형의 가로와 세로는 원기둥의 무엇과 같나요?","options":[{"t":"가로는 밑면의 지름, 세로는 높이","correct":true},{"t":"가로는 밑면의 둘레, 세로는 높이","mis":"M6-2-u6-X08"},{"t":"가로는 밑면의 반지름, 세로는 높이","mis":"M6-2-u6-X20"},{"t":"가로는 높이, 세로는 밑면의 둘레","mis":"M6-2-u6-X09"}],"explanation":["원기둥을 앞에서 보면 밑면인 원이 지름만큼의 선분으로 보여요.","그래서 가로는 밑면의 지름이에요.","세로는 두 밑면 사이 — 원기둥의 높이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_basic#5','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',2,'mc','auto','밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":5,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"108 cm²","correct":true},{"t":"216 cm²","mis":"M6-2-u6-X20"},{"t":"54 cm²","mis":"M6-2-u6-X20"},{"t":"135 cm²","mis":"M6-2-u6-X15"}],"explanation":["앞에서 본 삼각형의 밑변은 밑면의 지름 18 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선 15 cm는 쓰지 않아요.","18 × 12 ÷ 2 = 108 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"48 cm²","correct":true},{"t":"96 cm²","mis":"M6-2-u6-X20"},{"t":"24 cm²","mis":"M6-2-u6-X20"},{"t":"60 cm²","mis":"M6-2-u6-X15"}],"explanation":["앞에서 본 삼각형의 밑변은 밑면의 지름 12 cm, 높이는 원뿔의 높이 8 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선 10 cm는 쓰지 않아요.","12 × 8 ÷ 2 = 48 cm²예요."]},{"stem":"밑면의 지름이 10 cm, 높이가 12 cm, 모선의 길이가 13 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"60 cm²","correct":true},{"t":"120 cm²","mis":"M6-2-u6-X20"},{"t":"30 cm²","mis":"M6-2-u6-X20"},{"t":"65 cm²","mis":"M6-2-u6-X15"}],"explanation":["앞에서 본 삼각형의 밑변은 밑면의 지름 10 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선 13 cm는 쓰지 않아요.","10 × 12 ÷ 2 = 60 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_basic#6','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',2,'mc','auto','밑면의 지름이 12 cm, 높이가 9 cm인 원기둥을 앞에서 보았어요. 앞에서 본 직사각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X08']::text[],true,'{"seq":6,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"밑면의 지름이 12 cm, 높이가 9 cm인 원기둥을 앞에서 보았어요. 앞에서 본 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"108 cm²","correct":true},{"t":"54 cm²","mis":"M6-2-u6-X20"},{"t":"339.12 cm²","mis":"M6-2-u6-X08"},{"t":"42 cm²","mis":"M6-2-u6-X20"}],"explanation":["원기둥을 앞에서 보면 직사각형이에요.","가로는 밑면의 지름 12 cm, 세로는 높이 9 cm예요.","12 × 9 = 108 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 8 cm, 높이가 6 cm인 원기둥을 앞에서 보았어요. 앞에서 본 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"48 cm²","correct":true},{"t":"24 cm²","mis":"M6-2-u6-X20"},{"t":"150.72 cm²","mis":"M6-2-u6-X08"},{"t":"28 cm²","mis":"M6-2-u6-X20"}],"explanation":["원기둥을 앞에서 보면 직사각형이에요.","가로는 밑면의 지름 8 cm, 세로는 높이 6 cm예요.","8 × 6 = 48 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_basic#7','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',2,'mc','auto','원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 앞에서 본 삼각형의 넓이를 구할 때 쓰지 않는 길이는 어느 것인가요?',ARRAY['M6-2-u6-X15','M6-2-u6-X20']::text[],true,'{"seq":7,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 앞에서 본 삼각형의 넓이를 구할 때 쓰지 않는 길이는 어느 것인가요?","options":[{"t":"모선의 길이 15 cm","correct":true},{"t":"높이 12 cm","mis":"M6-2-u6-X15"},{"t":"밑면의 반지름 9 cm","mis":"M6-2-u6-X20"},{"t":"세 길이 모두 써요","mis":"M6-2-u6-X15"}],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","밑변은 반지름 9 cm의 2배인 18 cm, 높이는 12 cm예요.","모선 15 cm는 넓이를 구할 때 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"원뿔 모양 모자는 밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm예요. 앞에서 본 삼각형의 넓이를 구할 때 쓰지 않는 길이는 어느 것인가요?","options":[{"t":"모선의 길이 10 cm","correct":true},{"t":"높이 8 cm","mis":"M6-2-u6-X15"},{"t":"밑면의 반지름 6 cm","mis":"M6-2-u6-X20"},{"t":"세 길이 모두 써요","mis":"M6-2-u6-X15"}],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","밑변은 반지름 6 cm의 2배인 12 cm, 높이는 8 cm예요.","모선 10 cm는 넓이를 구할 때 쓰지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_basic#8','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',2,'ox','auto','원뿔을 앞에서 본 삼각형의 높이는 모선과 같아요.',ARRAY['M6-2-u6-X15']::text[],true,'{"seq":8,"concept":"M6-2-u6-C8","difficulty":2,"kind":"ox","stem":"원뿔을 앞에서 본 삼각형의 높이는 모선과 같아요.","answer":"X","reason_options":[{"t":"삼각형의 높이는 원뿔의 높이이고 모선은 옆 변이기 때문에","correct":true},{"t":"모선이 꼭짓점에서 내려오기 때문에","mis":"M6-2-u6-X15"}],"mis":"M6-2-u6-X15","explanation":["원뿔을 앞에서 보면 삼각형 — 밑변은 밑면의 지름, 높이는 원뿔의 높이예요.","원기둥을 앞에서 보면 직사각형 — 가로는 지름, 세로는 높이예요.","모선은 삼각형의 옆 변이에요."],"variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 직사각형의 가로는 밑면의 지름이에요.","answer":"O","reason_options":[{"t":"밑면인 원이 지름만큼의 선분으로 보이기 때문에","correct":true},{"t":"가로는 밑면의 둘레이기 때문에","mis":"M6-2-u6-X08"}],"explanation":["원뿔을 앞에서 보면 삼각형 — 밑변은 밑면의 지름, 높이는 원뿔의 높이예요.","원기둥을 앞에서 보면 직사각형 — 가로는 지름, 세로는 높이예요.","모선은 삼각형의 옆 변이에요."]},{"stem":"원뿔을 앞에서 본 삼각형의 밑변은 밑면의 반지름이에요.","answer":"X","reason_options":[{"t":"밑면인 원이 지름만큼 보이기 때문에","correct":true},{"t":"원뿔의 밑면은 반지름으로만 나타내기 때문에","mis":"M6-2-u6-X20"}],"explanation":["원뿔을 앞에서 보면 삼각형 — 밑변은 밑면의 지름, 높이는 원뿔의 높이예요.","원기둥을 앞에서 보면 직사각형 — 가로는 지름, 세로는 높이예요.","모선은 삼각형의 옆 변이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_basic#9','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',2,'mc','auto','원뿔 모양 모자의 밑면의 반지름이 9 cm일 때, 앞에서 본 삼각형의 밑변의 길이는 몇 cm인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],false,'{"seq":9,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"원뿔 모양 모자의 밑면의 반지름이 9 cm일 때, 앞에서 본 삼각형의 밑변의 길이는 몇 cm인가요?","options":[{"t":"18 cm","correct":true},{"t":"9 cm","mis":"M6-2-u6-X20"},{"t":"15 cm","mis":"M6-2-u6-X15"},{"t":"12 cm","mis":"M6-2-u6-X15"}],"explanation":["앞에서 보면 밑면인 원이 지름만큼의 선분으로 보여요.","지름은 반지름의 2배예요.","9 × 2 = 18 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_basic#10','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',3,'sa','auto','세계 전통 의상 체험관의 원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 원기둥 모양 모자의 높이는 9 cm예요. 두 모자를 앞에서 본 모양의 넓이가 같을 때 원기둥 모양 모자의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"세계 전통 의상 체험관의 원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 원기둥 모양 모자의 높이는 9 cm예요. 두 모자를 앞에서 본 모양의 넓이가 같을 때 원기둥 모양 모자의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["원뿔을 앞에서 본 삼각형의 밑변은 9 × 2 = 18 cm, 높이는 12 cm — 넓이는 18 × 12 ÷ 2 = 108 cm²예요.","원기둥을 앞에서 본 직사각형도 108 cm² — 세로는 높이 9 cm예요.","가로(지름)는 108 ÷ 9 = 12 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원뿔 모양 모자는 밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm예요. 원기둥 모양 모자는 밑면의 반지름이 4 cm예요. 두 모자를 앞에서 본 모양의 넓이가 같을 때 원기둥 모양 모자의 높이는 몇 cm인가요?","answer":["6"],"explanation":["원뿔을 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥을 앞에서 본 직사각형의 가로는 밑면의 지름 4 × 2 = 8 cm예요.","세로(높이)는 48 ÷ 8 = 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_challenge#1','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',3,'match','auto','앞에서 본 모양에 대해 알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C8","difficulty":3,"kind":"match","stem":"앞에서 본 모양에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"삼각형의 밑변","r":"밑면의 지름"},{"l":"삼각형의 높이","r":"원뿔의 높이"},{"l":"삼각형의 옆 변","r":"모선"}],"mis":"M6-2-u6-X15","explanation":["원뿔은 삼각형, 원기둥은 직사각형, 구는 원으로 보여요.","삼각형의 밑변은 지름, 높이는 원뿔의 높이, 옆 변은 모선이에요.","직사각형의 가로는 지름, 세로는 높이예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 앞에서 본 모양에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"직사각형의 가로","r":"밑면의 지름"},{"l":"직사각형의 세로","r":"원기둥의 높이"},{"l":"위에서 본 모양","r":"원"}],"explanation":["원뿔은 삼각형, 원기둥은 직사각형, 구는 원으로 보여요.","삼각형의 밑변은 지름, 높이는 원뿔의 높이, 옆 변은 모선이에요.","직사각형의 가로는 지름, 세로는 높이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_challenge#2','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',2,'sa','auto','원기둥을 앞에서 본 직사각형의 넓이가 108 cm², 세로가 9 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u6-C8","difficulty":2,"kind":"sa","stem":"원기둥을 앞에서 본 직사각형의 넓이가 108 cm², 세로가 9 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["앞에서 본 직사각형의 세로는 높이, 가로는 밑면의 지름이에요.","(가로) = (넓이) ÷ (세로)예요.","108 ÷ 9 = 12 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 직사각형의 넓이가 48 cm², 가로가 8 cm예요. 이 원기둥의 높이는 몇 cm인가요?","answer":["6"],"explanation":["앞에서 본 직사각형의 가로는 밑면의 지름, 세로는 높이예요.","(세로) = (넓이) ÷ (가로)예요.","48 ÷ 8 = 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_challenge#3','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',3,'error','auto','밑면의 지름이 18 cm, 높이가 12 cm, 모선이 15 cm인 원뿔을 앞에서 본 삼각형의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u6-X15','M6-2-u6-X19']::text[],false,'{"seq":3,"concept":"M6-2-u6-C8","difficulty":3,"kind":"error","stem":"밑면의 지름이 18 cm, 높이가 12 cm, 모선이 15 cm인 원뿔을 앞에서 본 삼각형의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"지석 — 「18 × 15 ÷ 2 = 135야.」","correct":true,"mis_target":"M6-2-u6-X15"},{"t":"서우 — 「18 × 12 ÷ 2 = 108이야.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「밑변은 지름, 높이는 원뿔의 높이야.」","mis":"M6-2-u6-X19"},{"t":"민지 — 「넓이는 108 cm²야.」","mis":"M6-2-u6-X19"}],"explanation":["삼각형의 높이는 원뿔의 높이 12 cm예요.","모선 15 cm는 삼각형의 옆 변이라 높이가 아니에요.","바른 넓이는 108 cm² — 지석은 모선을 높이로 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_challenge#4','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',3,'sa','auto','세계 전통 의상 체험관의 원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 원기둥 모양 모자의 밑면의 지름이 12 cm이고 두 모자를 앞에서 본 모양의 넓이가 같을 때, 원기둥 모양 모자의 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":4,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"세계 전통 의상 체험관의 원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 원기둥 모양 모자의 밑면의 지름이 12 cm이고 두 모자를 앞에서 본 모양의 넓이가 같을 때, 원기둥 모양 모자의 높이는 몇 cm인가요?","answer":["9"],"explanation":["원뿔을 앞에서 본 삼각형의 넓이는 18 × 12 ÷ 2 = 108 cm²예요.","원기둥을 앞에서 본 직사각형도 108 cm² — 가로는 지름 12 cm예요.","세로(높이)는 108 ÷ 12 = 9 cm예요."],"mis":"M6-2-u6-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_challenge#5','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',3,'sa','auto','원뿔 모양 모자는 밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm예요. 원기둥 모양 모자의 높이가 6 cm이고 두 모자를 앞에서 본 모양의 넓이가 같을 때, 원기둥 모양 모자의 밑면의 지름은 몇 cm인가요?','{}'::text[],false,'{"seq":5,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"원뿔 모양 모자는 밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm예요. 원기둥 모양 모자의 높이가 6 cm이고 두 모자를 앞에서 본 모양의 넓이가 같을 때, 원기둥 모양 모자의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["원뿔을 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥을 앞에서 본 직사각형도 48 cm² — 세로는 높이 6 cm예요.","가로(지름)는 48 ÷ 6 = 8 cm예요."],"mis":"M6-2-u6-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_challenge#6','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',4,'sa','auto','원뿔을 앞에서 본 삼각형의 넓이가 108 cm²이고, 원뿔의 밑면의 지름이 18 cm예요. 이 원뿔의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C8","difficulty":4,"kind":"sa","stem":"원뿔을 앞에서 본 삼각형의 넓이가 108 cm²이고, 원뿔의 밑면의 지름이 18 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["12"],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","18 × (높이) ÷ 2 = 108 — (높이) = 108 × 2 ÷ 18이에요.","108 × 2 ÷ 18 = 12 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원뿔을 앞에서 본 삼각형의 넓이가 48 cm²이고, 원뿔의 밑면의 지름이 12 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["8"],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","12 × (높이) ÷ 2 = 48 — (높이) = 48 × 2 ÷ 12예요.","48 × 2 ÷ 12 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_challenge#7','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',3,'ox','auto','원뿔과 원기둥을 앞에서 본 모양의 넓이를 구할 때 원뿔의 모선의 길이가 꼭 필요해요.',ARRAY['M6-2-u6-X15']::text[],false,'{"seq":7,"concept":"M6-2-u6-C8","difficulty":3,"kind":"ox","stem":"원뿔과 원기둥을 앞에서 본 모양의 넓이를 구할 때 원뿔의 모선의 길이가 꼭 필요해요.","answer":"X","reason_options":[{"t":"앞에서 본 삼각형의 넓이는 밑변(밑면의 지름)과 높이(원뿔의 높이)로 구하기 때문에","correct":true},{"t":"모선이 삼각형의 높이이기 때문에","mis":"M6-2-u6-X15"}],"mis":"M6-2-u6-X15","explanation":["원뿔을 앞에서 본 삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","밑변은 밑면의 지름, 높이는 원뿔의 높이예요.","모선은 삼각형의 옆 변이라 넓이를 구할 때 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_challenge#8','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',2,'mc','auto','『수학』 139쪽 2번 — 원뿔(밑면의 반지름 6 cm, 높이 8 cm, 모선 10 cm)과 원기둥(밑면의 반지름 4 cm)을 앞에서 본 모양의 넓이가 같아요. 원기둥의 높이를 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],false,'{"seq":8,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"『수학』 139쪽 2번 — 원뿔(밑면의 반지름 6 cm, 높이 8 cm, 모선 10 cm)과 원기둥(밑면의 반지름 4 cm)을 앞에서 본 모양의 넓이가 같아요. 원기둥의 높이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"12 × 8 ÷ 2 = 8 × □","correct":true},{"t":"6 × 8 ÷ 2 = 4 × □","mis":"M6-2-u6-X20"},{"t":"12 × 10 ÷ 2 = 8 × □","mis":"M6-2-u6-X15"},{"t":"12 × 8 = 8 × □","mis":"M6-2-u6-X20"}],"explanation":["원뿔의 앞모양은 밑변 12 cm, 높이 8 cm인 삼각형 — 넓이 12 × 8 ÷ 2예요.","원기둥의 앞모양은 가로가 지름 8 cm인 직사각형 — 넓이 8 × □예요.","두 넓이가 같으니 12 × 8 ÷ 2 = 8 × □ — □ = 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_challenge#9','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',4,'essay','teacher','『수학』 138쪽 1번 문제(원뿔: 밑면의 반지름 9 cm, 높이 12 cm, 모선 15 cm · 원기둥: 높이 9 cm, 두 앞모양의 넓이가 같음)를 어떻게 해결했는지 필요한 정보를 찾는 과정과 함께 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u6-C8","difficulty":4,"kind":"essay","stem":"『수학』 138쪽 1번 문제(원뿔: 밑면의 반지름 9 cm, 높이 12 cm, 모선 15 cm · 원기둥: 높이 9 cm, 두 앞모양의 넓이가 같음)를 어떻게 해결했는지 필요한 정보를 찾는 과정과 함께 설명해 보세요.","answer_guide":{"answer":"예: 원뿔을 앞에서 본 모양은 밑변이 9 × 2 = 18 cm, 높이가 12 cm인 삼각형이라 넓이는 18 × 12 ÷ 2 = 108 cm²이다. 모선 15 cm는 쓰지 않는다. 원기둥을 앞에서 본 직사각형도 넓이가 108 cm²이고 세로가 9 cm이므로 가로(밑면의 지름)는 108 ÷ 9 = 12 cm이다.","scoring_points":["필요한 정보(밑변·높이)를 골라 모선을 쓰지 않았는가","삼각형 넓이 108 cm²를 구했는가","108 ÷ 9 = 12로 지름을 구했는가"]},"explanation":["밑변 18 cm, 높이 12 cm를 골라요.","18 × 12 ÷ 2 = 108이에요.","108 ÷ 9 = 12 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_L09_challenge#10','math',6,2,'u6','L09','tb_g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',4,'essay','teacher','『수학』 139쪽 2번 문제의 조건을 바꾸어 새 문제를 만들고 풀어 보세요. (원뿔: 밑면의 반지름 6 cm, 높이 8 cm, 모선 10 cm · 원기둥을 앞에서 본 모양의 넓이가 원뿔과 같음 — 이번에는 원기둥의 높이 6 cm를 주고 지름을 묻기)','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C8","difficulty":4,"kind":"essay","stem":"『수학』 139쪽 2번 문제의 조건을 바꾸어 새 문제를 만들고 풀어 보세요. (원뿔: 밑면의 반지름 6 cm, 높이 8 cm, 모선 10 cm · 원기둥을 앞에서 본 모양의 넓이가 원뿔과 같음 — 이번에는 원기둥의 높이 6 cm를 주고 지름을 묻기)","answer_guide":{"answer":"예: 원뿔을 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²이다. 원기둥을 앞에서 본 직사각형도 48 cm²이고 세로(높이)가 6 cm이므로 가로(밑면의 지름)는 48 ÷ 6 = 8 cm이다.","scoring_points":["바꾼 조건(높이 6 cm, 지름 묻기)으로 문제를 만들었는가","삼각형 넓이 48 cm²를 구했는가","48 ÷ 6 = 8로 지름을 구했는가"]},"explanation":["삼각형 넓이는 48 cm²예요.","직사각형도 48 cm²예요.","48 ÷ 6 = 8 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#1','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C1',1,'mc','auto','가 둥근 기둥 모양 · 나 육각기둥 · 다 각뿔 · 라 공 모양 · 마 눕혀 놓은 둥근 기둥 모양 · 바 뿔 모양이고 밑면이 원인 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X01','M6-2-u6-X14']::text[],true,'{"seq":1,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"가 둥근 기둥 모양 · 나 육각기둥 · 다 각뿔 · 라 공 모양 · 마 눕혀 놓은 둥근 기둥 모양 · 바 뿔 모양이고 밑면이 원인 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 마","correct":true},{"t":"가","mis":"M6-2-u6-X05"},{"t":"가, 나, 마","mis":"M6-2-u6-X01"},{"t":"가, 마, 바","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 마 모두 원기둥이에요."],"variant_rule":{"alt":[{"stem":"가 위아래 두 원의 크기가 다른 통 · 나 둥근 기둥 모양의 통 · 다 서로 평행하고 합동인 두 면이 삼각형인 상자 · 라 길쭉한 둥근 기둥 모양의 통 · 마 뾰족한 뿔 모양의 상자 · 바 납작한 둥근 기둥 모양의 통 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"나, 라, 바","correct":true},{"t":"나, 라","mis":"M6-2-u6-X02"},{"t":"가, 나, 라, 바","mis":"M6-2-u6-X02"},{"t":"나, 다, 라, 바","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","나, 라, 바 모두 원기둥이에요."]},{"stem":"가 서로 평행하고 합동인 두 면이 삼각형인 입체도형 · 나 둥근 기둥 모양의 입체도형 · 다 마주 보는 두 면이 원이지만 크기가 다른 입체도형 · 라 눕혀 놓은 둥근 기둥 모양의 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나","mis":"M6-2-u6-X05"},{"t":"나, 다, 라","mis":"M6-2-u6-X02"},{"t":"가, 나, 라","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","나, 라 모두 원기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#2','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C5',1,'mc','auto','가 둥근 기둥 모양 · 나 육각기둥 · 다 각뿔 · 라 공 모양 · 마 눕혀 놓은 둥근 기둥 모양 · 바 뿔 모양이고 밑면이 원인 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X01','M6-2-u6-X14']::text[],true,'{"seq":2,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"가 둥근 기둥 모양 · 나 육각기둥 · 다 각뿔 · 라 공 모양 · 마 눕혀 놓은 둥근 기둥 모양 · 바 뿔 모양이고 밑면이 원인 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"바","correct":true},{"t":"다, 바","mis":"M6-2-u6-X01"},{"t":"가, 바","mis":"M6-2-u6-X14"},{"t":"다","mis":"M6-2-u6-X01"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","바 하나만 원뿔이에요."],"variant_rule":{"alt":[{"stem":"가 밑면이 원이고 뾰족한 뿔 모양인 입체도형 · 나 상자 모양의 각기둥 · 다 둥근 기둥 모양의 입체도형 · 라 납작한 둥근 기둥 모양의 입체도형 · 마 작은 뿔 모양이고 밑면이 원인 입체도형 · 바 밑면이 다각형인 뿔 모양의 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 마","correct":true},{"t":"가","mis":"M6-2-u6-X14"},{"t":"가, 마, 바","mis":"M6-2-u6-X01"},{"t":"가, 라, 마","mis":"M6-2-u6-X14"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 마 모두 원뿔이에요."]},{"stem":"가 밑면이 다각형인 뿔 모양의 입체도형 · 나 서로 평행하고 합동인 두 원이 있는 기둥 모양 · 다 거꾸로 세운 뿔 모양이고 한 원을 면으로 하는 입체도형 · 라 눕혀 놓은 뿔 모양이고 한 원을 면으로 하는 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"다, 라","correct":true},{"t":"다","mis":"M6-2-u6-X14"},{"t":"가, 다, 라","mis":"M6-2-u6-X01"},{"t":"나, 다, 라","mis":"M6-2-u6-X14"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","다, 라 모두 원뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#3','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C7',1,'mc','auto','가 둥근 기둥 모양 · 나 육각기둥 · 다 각뿔 · 라 공 모양 · 마 눕혀 놓은 둥근 기둥 모양 · 바 뿔 모양이고 밑면이 원인 입체도형 — 구를 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X22']::text[],true,'{"seq":3,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"가 둥근 기둥 모양 · 나 육각기둥 · 다 각뿔 · 라 공 모양 · 마 눕혀 놓은 둥근 기둥 모양 · 바 뿔 모양이고 밑면이 원인 입체도형 — 구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"라","correct":true},{"t":"가, 라","mis":"M6-2-u6-X22"},{"t":"라, 마","mis":"M6-2-u6-X22"},{"t":"가, 라, 마","mis":"M6-2-u6-X22"}],"explanation":["구는 어느 방향에서 보아도 원인 공 모양의 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","라 하나만 구예요."],"variant_rule":{"alt":[{"stem":"가 공 모양의 입체도형 · 나 납작하게 눌린 둥근 모양 · 다 길쭉한 달걀 모양 · 라 작은 공 모양의 입체도형 — 구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가","mis":"M6-2-u6-X22"},{"t":"가, 나, 라","mis":"M6-2-u6-X22"},{"t":"가, 다, 라","mis":"M6-2-u6-X22"}],"explanation":["구는 어느 방향에서 보아도 원인 공 모양의 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 라 모두 구예요."]},{"stem":"가 뿔 모양이고 밑면이 원인 입체도형 · 나 공 모양의 입체도형 · 다 눕혀 놓은 둥근 기둥 모양 · 라 작은 공 모양의 입체도형 · 마 눕혀 놓은 뿔 모양이고 밑면이 원인 입체도형 · 바 납작한 둥근 기둥 모양 — 구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나","mis":"M6-2-u6-X22"},{"t":"나, 다, 라","mis":"M6-2-u6-X22"},{"t":"가, 나, 라","mis":"M6-2-u6-X03"}],"explanation":["구는 어느 방향에서 보아도 원인 공 모양의 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","나, 라 모두 구예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#4','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C1',1,'match','auto','『수학』 140쪽 마무리 2 — 평면도형을 한 직선을 기준으로 한 바퀴 돌려서 만들 수 있는 입체도형을 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C1","difficulty":1,"kind":"match","stem":"『수학』 140쪽 마무리 2 — 평면도형을 한 직선을 기준으로 한 바퀴 돌려서 만들 수 있는 입체도형을 이으세요.","pairs":[{"l":"직각삼각형","r":"원뿔"},{"l":"직사각형","r":"원기둥"},{"l":"지름을 따라 반으로 나눈 원","r":"구"}],"mis":"M6-2-u6-X03","explanation":["직각삼각형을 돌리면 원뿔이 돼요.","직사각형을 돌리면 원기둥이 돼요.","반원을 지름을 기준으로 돌리면 구가 돼요."],"variant_rule":{"alt":[{"stem":"한 바퀴 돌릴 때 기준으로 삼는 변과 만들어지는 입체도형을 이으세요.","pairs":[{"l":"직사각형의 한 변","r":"원기둥"},{"l":"직각삼각형의 직각을 낀 한 변","r":"원뿔"},{"l":"반원의 지름","r":"구"}],"explanation":["직사각형은 한 변을 기준으로 돌려요.","직각삼각형은 직각이 있는 변을 기준으로 돌려요.","반원은 지름을 기준으로 돌려요."]},{"stem":"돌리기 전 평면도형의 부분과 만들어진 입체도형의 부분을 이으세요.","pairs":[{"l":"반원의 중심","r":"구의 중심"},{"l":"반원의 반지름","r":"구의 반지름"},{"l":"직각삼각형에서 막대에 붙인 변","r":"원뿔의 높이"}],"explanation":["원의 중심은 구의 중심이 돼요.","원의 반지름은 구의 반지름이 돼요.","막대에 붙인 변은 높이가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#5','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C2',1,'mc','auto','원기둥에서 두 밑면 사이의 거리를 무엇이라고 하나요?',ARRAY['M6-2-u6-X05','M6-2-u6-X15']::text[],true,'{"seq":5,"concept":"M6-2-u6-C2","difficulty":1,"kind":"mc","stem":"원기둥에서 두 밑면 사이의 거리를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면 사이의 거리를 높이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."],"variant_rule":{"alt":[{"stem":"원뿔에서 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"모선","correct":true},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 모선이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]},{"stem":"원뿔에서 뾰족한 부분의 점을 무엇이라고 하나요?","options":[{"t":"원뿔의 꼭짓점","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","뾰족한 부분의 점을 원뿔의 꼭짓점이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#6','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C4',1,'mc','auto','『수학』 141쪽 마무리 4 — 가 직사각형의 위쪽에 크기가 같은 두 원이 나란히 · 나 사다리꼴 옆면의 위와 아래에 원 · 다 세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 같은 원이 하나씩 — 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u6-X12','M6-2-u6-X11']::text[],true,'{"seq":6,"concept":"M6-2-u6-C4","difficulty":1,"kind":"mc","stem":"『수학』 141쪽 마무리 4 — 가 직사각형의 위쪽에 크기가 같은 두 원이 나란히 · 나 사다리꼴 옆면의 위와 아래에 원 · 다 세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 같은 원이 하나씩 — 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M6-2-u6-X12"},{"t":"나","mis":"M6-2-u6-X11"},{"t":"가와 다","mis":"M6-2-u6-X12"}],"explanation":["가는 두 원이 겹쳐서 안 돼요.","나는 옆면이 직사각형이 아니어서 안 돼요.","다는 옆면이 직사각형이고 합동인 두 원이 마주 보아 전개도가 돼요."],"variant_rule":{"alt":[{"stem":"종이 상자는 이물질을 없앤 다음 납작하게 부피를 줄여 분리배출해요. 상자를 잘라 펼친 가 · 나 · 다 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요? (가 직사각형의 위와 아래에 크기가 같은 원이 하나씩 · 나 직사각형의 왼쪽에 크기가 같은 두 원이 나란히 · 다 직사각형의 위에 큰 원, 아래에 작은 원)","options":[{"t":"가","correct":true},{"t":"나","mis":"M6-2-u6-X12"},{"t":"다","mis":"M6-2-u6-X02"},{"t":"셋 다 될 수 있어요","mis":"M6-2-u6-X02"}],"explanation":["나는 두 원이 같은 쪽에 있어 접으면 겹쳐요.","다는 두 원이 서로 합동이 아니에요.","그래서 원기둥의 전개도는 가예요."]},{"stem":"『수학』 129쪽 가~라 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요? (가 직사각형의 위와 아래에 크기가 같은 원 · 나 사다리꼴 옆면 · 다 두 원이 위쪽에 나란히 · 라 크기가 다른 두 원)","options":[{"t":"가","correct":true},{"t":"나","mis":"M6-2-u6-X11"},{"t":"다","mis":"M6-2-u6-X12"},{"t":"라","mis":"M6-2-u6-X02"}],"explanation":["나는 옆면이 직사각형이 아니에요.","다는 두 원이 겹치고, 라는 두 원이 합동이 아니에요.","그래서 가예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#7','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C6',1,'mc','auto','『수학』 142쪽 마무리 6 — ㉠ 원기둥의 밑면은 1개예요. ㉡ 원기둥의 전개도에서 옆면은 원이에요. ㉢ 원뿔의 높이는 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요. ㉣ 구의 중심은 1개이고, 구의 반지름은 무수히 많아요. 바르게 설명한 것은 어느 것인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X13','M6-2-u6-X15']::text[],true,'{"seq":7,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"『수학』 142쪽 마무리 6 — ㉠ 원기둥의 밑면은 1개예요. ㉡ 원기둥의 전개도에서 옆면은 원이에요. ㉢ 원뿔의 높이는 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요. ㉣ 구의 중심은 1개이고, 구의 반지름은 무수히 많아요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"M6-2-u6-X05"},{"t":"㉡","mis":"M6-2-u6-X13"},{"t":"㉢","mis":"M6-2-u6-X15"}],"explanation":["원기둥의 밑면은 2개, 전개도의 옆면은 직사각형이에요.","㉢은 높이가 아니라 모선의 뜻이에요.","바르게 설명한 것은 ㉣이에요."],"variant_rule":{"alt":[{"stem":"『수학익힘』 93쪽 — ㉠ 구는 꼭짓점이 없어요. ㉡ 구는 밑면이 2개 있어요. ㉢ 구의 중심은 1개예요. ㉣ 구의 반지름은 무수히 많고 그 길이가 모두 달라요. 바르게 설명한 것을 모두 찾은 것은 어느 것인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠, ㉡","mis":"M6-2-u6-X05"},{"t":"㉢, ㉣","mis":"M6-2-u6-X17"},{"t":"㉠, ㉢, ㉣","mis":"M6-2-u6-X17"}],"explanation":["구에는 밑면이 없어요 — ㉡은 틀려요.","구의 반지름은 길이가 모두 같아요 — ㉣은 틀려요.","바른 것은 ㉠, ㉢이에요."]},{"stem":"단원 평가 — 원뿔에 대한 설명 ㉠ 어느 방향에서 보아도 원 모양이에요. ㉡ 원뿔의 꼭짓점은 2개예요. ㉢ 직사각형을 한 변을 기준으로 한 바퀴 돌려서 만들 수 있어요. ㉣ 원뿔의 높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요. 옳은 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"M6-2-u6-X18"},{"t":"㉡","mis":"M6-2-u6-X07"},{"t":"㉢","mis":"M6-2-u6-X03"}],"explanation":["원뿔을 앞에서 보면 삼각형이고, 꼭짓점은 1개예요.","직사각형을 돌리면 원기둥이 돼요.","옳은 것은 ㉣이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#8','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C2',1,'sa','auto','원기둥의 밑면은 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C2","difficulty":1,"kind":"sa","stem":"원기둥의 밑면은 몇 개인가요?","answer":["2"],"explanation":["원기둥·원뿔·구의 정의와 구성 요소를 떠올려요.","서로 평행하고 합동인 두 원 — 2개예요.","원기둥 밑면 2 · 원뿔 밑면 1 · 구의 중심 1이에요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"원뿔의 밑면은 몇 개인가요?","answer":["1"],"explanation":["원기둥·원뿔·구의 정의와 구성 요소를 떠올려요.","한 원을 면으로 해요 — 1개예요.","원기둥 밑면 2 · 원뿔 밑면 1 · 구의 중심 1이에요."]},{"stem":"구의 중심은 몇 개인가요?","answer":["1"],"explanation":["원기둥·원뿔·구의 정의와 구성 요소를 떠올려요.","돌리기 전 원의 중심 하나가 구의 중심 — 1개예요.","원기둥 밑면 2 · 원뿔 밑면 1 · 구의 중심 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#9','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C3',2,'mc','auto','『수학』 141쪽 마무리 5 — 밑면의 지름이 2 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?',ARRAY['M6-2-u6-X08','M6-2-u6-X09']::text[],true,'{"seq":9,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"『수학』 141쪽 마무리 5 — 밑면의 지름이 2 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"6.28 cm","correct":true},{"t":"2 cm","mis":"M6-2-u6-X08"},{"t":"3.14 cm","mis":"M6-2-u6-X08"},{"t":"3 cm","mis":"M6-2-u6-X09"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 2 cm예요.","2 × 3.14 = 6.28 cm예요."],"variant_rule":{"alt":[{"stem":"『수학』 130쪽 활동 6 — 밑면의 반지름이 1 cm, 높이가 2 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"6.28 cm","correct":true},{"t":"2 cm","mis":"M6-2-u6-X08"},{"t":"3.14 cm","mis":"M6-2-u6-X08"},{"t":"12.56 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 2 cm예요.","2 × 3.14 = 6.28 cm예요."]},{"stem":"『수학익힘』 89쪽 — 밑면의 반지름이 1.5 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"9.42 cm","correct":true},{"t":"3 cm","mis":"M6-2-u6-X08"},{"t":"4.71 cm","mis":"M6-2-u6-X08"},{"t":"18.84 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 3 cm예요.","3 × 3.14 = 9.42 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#10','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C3',2,'sa','auto','원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 4 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 4 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 4 cm는 높이예요.","25.12 ÷ 3.14 = 8 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 5 cm는 높이예요.","18.84 ÷ 3.14 = 6 cm예요."]},{"stem":"원기둥의 전개도에서 옆면의 가로가 31.4 cm, 세로가 11 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["10"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 11 cm는 높이예요.","31.4 ÷ 3.14 = 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#11','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C1',2,'sa','auto','가로 9 cm, 세로 4 cm인 직사각형을 길이가 9 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":11,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 9 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["기준으로 한 9 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 4 cm 변은 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 4 × 2 = 8 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 9 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 높이는 몇 cm인가요?","answer":["9"],"explanation":["기준으로 한 9 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 4 cm 변은 밑면의 반지름이 돼요.","그래서 높이는 9 cm예요."]},{"stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 4 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["18"],"explanation":["기준으로 한 4 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 9 cm 변은 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 9 × 2 = 18 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#12','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C5',2,'sa','auto','『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 지름은 몇 cm인가요?","answer":["14"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","지름은 7 × 2 = 14 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 높이는 몇 cm인가요?","answer":["5"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","그래서 높이는 5 cm예요."]},{"stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","그래서 밑면의 반지름은 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#13','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C6',2,'sa','auto','원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 13 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":13,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 13 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["12"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 높이는 12 cm예요 — 13 cm는 모선이에요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 4 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 5 cm, 밑면의 반지름은 3 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["5"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 모선의 길이는 5 cm예요."]},{"stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 15 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 17 cm, 밑면의 반지름은 8 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["15"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 높이는 15 cm예요 — 17 cm는 모선이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#14','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C7',2,'sa','auto','반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u6-C7","difficulty":2,"kind":"sa","stem":"반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["돌리기 전 원의 반지름은 구의 반지름이 돼요.","반원의 반지름이 8 cm예요.","그래서 구의 반지름은 8 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 6 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["12"],"explanation":["돌리기 전 원의 반지름이 구의 반지름 — 6 cm예요.","구의 지름은 반지름의 2배예요.","6 × 2 = 12 cm예요."]},{"stem":"반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["8"],"explanation":["돌리기 전 원의 반지름이 구의 반지름 — 4 cm예요.","구의 지름은 반지름의 2배예요.","4 × 2 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#15','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C2',2,'sa','auto','『수학익힘』 87쪽의 통조림은 원기둥 모양이에요. 밑면의 지름이 8 cm이고 두 밑면 사이의 거리가 3 cm예요. 이 통조림의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u6-C2","difficulty":2,"kind":"sa","stem":"『수학익힘』 87쪽의 통조림은 원기둥 모양이에요. 밑면의 지름이 8 cm이고 두 밑면 사이의 거리가 3 cm예요. 이 통조림의 높이는 몇 cm인가요?","answer":["3"],"explanation":["원기둥의 높이는 두 밑면 사이의 거리예요.","밑면의 지름 8 cm는 높이가 아니에요.","그래서 높이는 3 cm예요."],"mis":"M6-2-u6-X06","variant_rule":{"alt":[{"stem":"『수학익힘』 87쪽의 원기둥 모양 물건이 눕혀 놓여 있어요. 밑면의 지름은 6 cm이고, 두 밑면 사이의 거리는 12 cm예요. 이 물건의 높이는 몇 cm인가요?","answer":["12"],"explanation":["눕혀 놓아도 서로 평행하고 합동인 두 원이 밑면이에요.","높이는 두 밑면 사이의 거리예요 — 바닥에서 위까지의 길이가 아니에요.","그래서 높이는 12 cm예요."]},{"stem":"단원 평가 — 밑면의 지름이 6 cm이고 두 밑면 사이의 거리가 4 cm인 원기둥이 있어요. 이 원기둥의 높이는 몇 cm인가요?","answer":["4"],"explanation":["높이는 두 밑면 사이의 거리예요.","밑면의 지름 6 cm는 높이와 상관없어요.","그래서 높이는 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#16','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C8',2,'mc','auto','원뿔을 옆에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":16,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"원뿔을 옆에서 본 모양은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 옆에서 본 모양은 삼각형이에요."],"variant_rule":{"alt":[{"stem":"원기둥을 옆에서 본 모양은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 옆에서 본 모양은 직사각형이에요."]},{"stem":"구를 옆에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 구를 옆에서 본 모양은 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#17','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C8',3,'ox','auto','『수학』 142쪽 마무리 7 — 원기둥, 원뿔, 구를 옆에서 본 모양은 서로 같아요.',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":17,"concept":"M6-2-u6-C8","difficulty":3,"kind":"ox","stem":"『수학』 142쪽 마무리 7 — 원기둥, 원뿔, 구를 옆에서 본 모양은 서로 같아요.","answer":"X","reason_options":[{"t":"옆에서 본 모양이 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이라 서로 다르기 때문에","correct":true},{"t":"셋 다 위에서 본 모양이 원이기 때문에","mis":"M6-2-u6-X18"}],"mis":"M6-2-u6-X18","explanation":["원기둥을 옆에서 보면 직사각형이에요.","원뿔은 삼각형, 구는 원이에요.","그래서 옆에서 본 모양은 서로 달라요."],"variant_rule":{"alt":[{"stem":"원기둥·원뿔·구를 위에서 본 모양은 모두 원이에요.","answer":"O","reason_options":[{"t":"세 입체도형 모두 위에서 보면 둥근 테두리만 보이기 때문에","correct":true},{"t":"셋 다 앞에서 본 모양과 위에서 본 모양이 같기 때문에","mis":"M6-2-u6-X18"}],"explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."]},{"stem":"원기둥을 앞에서 본 직사각형의 가로는 밑면의 지름이에요.","answer":"O","reason_options":[{"t":"밑면인 원이 지름만큼의 선분으로 보이기 때문에","correct":true},{"t":"가로는 밑면의 둘레이기 때문에","mis":"M6-2-u6-X08"}],"explanation":["원뿔을 앞에서 보면 삼각형 — 밑변은 밑면의 지름, 높이는 원뿔의 높이예요.","원기둥을 앞에서 보면 직사각형 — 가로는 지름, 세로는 높이예요.","모선은 삼각형의 옆 변이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#18','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C8',3,'mc','auto','밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":18,"concept":"M6-2-u6-C8","difficulty":3,"kind":"mc","stem":"밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"108 cm²","correct":true},{"t":"216 cm²","mis":"M6-2-u6-X20"},{"t":"54 cm²","mis":"M6-2-u6-X20"},{"t":"135 cm²","mis":"M6-2-u6-X15"}],"explanation":["앞에서 본 삼각형의 밑변은 밑면의 지름 18 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선 15 cm는 쓰지 않아요.","18 × 12 ÷ 2 = 108 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"48 cm²","correct":true},{"t":"96 cm²","mis":"M6-2-u6-X20"},{"t":"24 cm²","mis":"M6-2-u6-X20"},{"t":"60 cm²","mis":"M6-2-u6-X15"}],"explanation":["앞에서 본 삼각형의 밑변은 밑면의 지름 12 cm, 높이는 원뿔의 높이 8 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선 10 cm는 쓰지 않아요.","12 × 8 ÷ 2 = 48 cm²예요."]},{"stem":"밑면의 지름이 10 cm, 높이가 12 cm, 모선의 길이가 13 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"60 cm²","correct":true},{"t":"120 cm²","mis":"M6-2-u6-X20"},{"t":"30 cm²","mis":"M6-2-u6-X20"},{"t":"65 cm²","mis":"M6-2-u6-X15"}],"explanation":["앞에서 본 삼각형의 밑변은 밑면의 지름 10 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선 13 cm는 쓰지 않아요.","10 × 12 ÷ 2 = 60 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#19','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C8',3,'sa','auto','세계 전통 의상 체험관의 원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 원기둥 모양 모자의 높이는 9 cm예요. 두 모자를 앞에서 본 모양의 넓이가 같을 때 원기둥 모양 모자의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":19,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"세계 전통 의상 체험관의 원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 원기둥 모양 모자의 높이는 9 cm예요. 두 모자를 앞에서 본 모양의 넓이가 같을 때 원기둥 모양 모자의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["원뿔을 앞에서 본 삼각형의 밑변은 9 × 2 = 18 cm, 높이는 12 cm — 넓이는 18 × 12 ÷ 2 = 108 cm²예요.","원기둥을 앞에서 본 직사각형도 108 cm² — 세로는 높이 9 cm예요.","가로(지름)는 108 ÷ 9 = 12 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원뿔 모양 모자는 밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm예요. 원기둥 모양 모자는 밑면의 반지름이 4 cm예요. 두 모자를 앞에서 본 모양의 넓이가 같을 때 원기둥 모양 모자의 높이는 몇 cm인가요?","answer":["6"],"explanation":["원뿔을 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥을 앞에서 본 직사각형의 가로는 밑면의 지름 4 × 2 = 8 cm예요.","세로(높이)는 48 ÷ 8 = 6 cm예요."]},{"stem":"세계 전통 의상 체험관의 원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 원기둥 모양 모자의 밑면의 지름이 12 cm이고 두 모자를 앞에서 본 모양의 넓이가 같을 때, 원기둥 모양 모자의 높이는 몇 cm인가요?","answer":["9"],"explanation":["원뿔을 앞에서 본 삼각형의 넓이는 18 × 12 ÷ 2 = 108 cm²예요.","원기둥을 앞에서 본 직사각형도 108 cm² — 가로는 지름 12 cm예요.","세로(높이)는 108 ÷ 12 = 9 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#20','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C4',3,'mc','auto','『수학』 129쪽의 나 — 「옆면이 사다리꼴 모양이고, 두 원이 위와 아래에 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?',ARRAY['M6-2-u6-X11']::text[],true,'{"seq":20,"concept":"M6-2-u6-C4","difficulty":3,"kind":"mc","stem":"『수학』 129쪽의 나 — 「옆면이 사다리꼴 모양이고, 두 원이 위와 아래에 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"옆면이 직사각형이 아니어서","correct":true},{"t":"두 원이 겹쳐서","mis":"M6-2-u6-X11"},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X11"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X11"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 옆면이 직사각형이 아니어서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"『수학』 129쪽의 라 — 「세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 다른 두 원이 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 원이 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 두 원이 서로 합동이 아니어서 전개도가 될 수 없어요."]},{"stem":"『수학』 141쪽 마무리 4의 가 — 「직사각형 옆면의 위쪽에 크기가 같은 두 원이 나란히 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"두 원이 겹쳐서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X12"},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X12"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X12"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 두 원이 겹쳐서 전개도가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#21','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C3',3,'sa','auto','가로 37.68 cm, 세로 6 cm인 직사각형 모양의 종이를 옆면으로 하는 원기둥을 만들려고 해요. 밑면의 반지름은 몇 cm로 해야 하나요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u6-C3","difficulty":3,"kind":"sa","stem":"가로 37.68 cm, 세로 6 cm인 직사각형 모양의 종이를 옆면으로 하는 원기둥을 만들려고 해요. 밑면의 반지름은 몇 cm로 해야 하나요?","answer":["6"],"explanation":["옆면의 가로 37.68 cm가 밑면의 둘레가 돼요.","지름은 37.68 ÷ 3.14 = 12 cm예요.","반지름은 12 ÷ 2 = 6 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 가로가 18.84 cm예. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 18.84 ÷ 3.14 = 6 cm예요.","반지름은 6 ÷ 2 = 3 cm예요."]},{"stem":"원기둥의 전개도에서 옆면의 가로가 25.12 cm예. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["4"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 25.12 ÷ 3.14 = 8 cm예요.","반지름은 8 ÷ 2 = 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#22','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C5',3,'mc','auto','단원 평가 — 원뿔과 각뿔에 대한 설명 ㉠ 원뿔과 각뿔은 모두 밑면이 1개예요. ㉡ 원뿔의 밑면의 모양은 원이고, 각뿔의 밑면의 모양은 다각형이에요. ㉢ 원뿔과 각뿔은 모두 굽은 면이 있어요. 잘못 설명한 것은 어느 것인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X01','M6-2-u6-X19']::text[],true,'{"seq":22,"concept":"M6-2-u6-C5","difficulty":3,"kind":"mc","stem":"단원 평가 — 원뿔과 각뿔에 대한 설명 ㉠ 원뿔과 각뿔은 모두 밑면이 1개예요. ㉡ 원뿔의 밑면의 모양은 원이고, 각뿔의 밑면의 모양은 다각형이에요. ㉢ 원뿔과 각뿔은 모두 굽은 면이 있어요. 잘못 설명한 것은 어느 것인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M6-2-u6-X05"},{"t":"㉡","mis":"M6-2-u6-X01"},{"t":"잘못 설명한 것이 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔과 각뿔은 모두 밑면이 1개예요.","밑면 모양은 원뿔이 원, 각뿔이 다각형이에요.","각뿔의 면은 모두 평평해요 — ㉢이 잘못이에요."],"variant_rule":{"alt":[{"stem":"단원 평가 — 가는 원뿔, 나는 오각뿔이에요. ㉠ 가는 원뿔이고 나는 오각뿔이에요. ㉡ 가와 나는 모두 꼭짓점이 1개뿐이에요. ㉢ 가와 나는 모두 뿔 모양이에요. 잘못 설명한 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u6-X19"},{"t":"㉢","mis":"M6-2-u6-X14"},{"t":"잘못 설명한 것이 없어요","mis":"M6-2-u6-X07"}],"explanation":["원뿔의 꼭짓점은 1개예요.","오각뿔은 밑면의 꼭짓점 5개와 각뿔의 꼭짓점 1개 — 6개예요.","그래서 ㉡이 잘못이에요."]},{"stem":"원기둥과 원뿔의 다른 점은 어느 것인가요?","options":[{"t":"원기둥은 밑면이 2개, 원뿔은 1개예요","correct":true},{"t":"원기둥은 밑면이 원, 원뿔은 다각형이에요","mis":"M6-2-u6-X01"},{"t":"원뿔에는 옆면이 없어요","mis":"M6-2-u6-X14"},{"t":"원기둥은 높이가 없어요","mis":"M6-2-u6-X06"}],"explanation":["원기둥과 원뿔 모두 밑면이 원이고 옆면이 굽은 면이에요.","원기둥은 밑면이 2개, 원뿔은 1개예요.","원뿔에는 뾰족한 꼭짓점이 있고 원기둥에는 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#23','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C8',4,'essay','teacher','『수학』 142쪽 마무리 7 — 원기둥, 원뿔, 구를 옆에서 본 모양은 서로 같은지 다른지 쓰고, 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M6-2-u6-C8","difficulty":4,"kind":"essay","stem":"『수학』 142쪽 마무리 7 — 원기둥, 원뿔, 구를 옆에서 본 모양은 서로 같은지 다른지 쓰고, 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 서로 다릅니다. 원기둥을 옆에서 본 모양은 직사각형, 원뿔을 옆에서 본 모양은 삼각형, 구를 옆에서 본 모양은 원이기 때문입니다.","scoring_points":["「다릅니다」라고 답했는가","원기둥 직사각형·원뿔 삼각형을 썼는가","구는 원이라고 썼는가"]},"explanation":["원기둥 → 직사각형이에요.","원뿔 → 삼각형이에요.","구 → 원이라 서로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#24','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C3',4,'essay','teacher','『수학』 141쪽 마무리 5 — 밑면의 지름이 2 cm, 높이가 3 cm인 원기둥의 전개도를 완성하는 방법을 쓰고, 밑면의 반지름·옆면의 가로·옆면의 세로를 구해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u6-C3","difficulty":4,"kind":"essay","stem":"『수학』 141쪽 마무리 5 — 밑면의 지름이 2 cm, 높이가 3 cm인 원기둥의 전개도를 완성하는 방법을 쓰고, 밑면의 반지름·옆면의 가로·옆면의 세로를 구해 보세요.","answer_guide":{"answer":"예: 원기둥의 높이 3 cm가 되도록 옆면(직사각형)을 완성하고, 옆면을 기준으로 그려져 있는 밑면과 마주 보는 위치에 합동인 밑면을 하나 더 그린다. 밑면의 반지름은 1 cm, 옆면의 가로는 2 × 3.14 = 6.28 cm, 옆면의 세로는 3 cm이다.","scoring_points":["옆면을 직사각형으로·밑면을 마주 보게 그린다고 썼는가","반지름 1 cm·가로 6.28 cm를 구했는가","세로 3 cm를 썼는가"]},"explanation":["옆면 직사각형 · 밑면은 마주 보게예요.","반지름 1 cm, 가로 2 × 3.14 = 6.28 cm예요.","세로 = 높이 3 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_a#25','math',6,2,'u6','','tb_g6_2_math_u6_review_a','unit_review','M6-2-u6-C8',4,'essay','teacher','『수학』 138쪽 1번 — 원뿔(밑면의 반지름 9 cm, 높이 12 cm, 모선 15 cm)과 원기둥(높이 9 cm)을 앞에서 본 모양의 넓이가 같을 때 원기둥 밑면의 지름을 구하고, 문제를 어떻게 해결했는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u6-C8","difficulty":4,"kind":"essay","stem":"『수학』 138쪽 1번 — 원뿔(밑면의 반지름 9 cm, 높이 12 cm, 모선 15 cm)과 원기둥(높이 9 cm)을 앞에서 본 모양의 넓이가 같을 때 원기둥 밑면의 지름을 구하고, 문제를 어떻게 해결했는지 설명해 보세요.","answer_guide":{"answer":"예: 원뿔을 앞에서 본 삼각형의 넓이는 18 × 12 ÷ 2 = 108 cm²이다. 원기둥을 앞에서 본 직사각형의 넓이도 108 cm²이고 세로가 9 cm이므로 지름은 108 ÷ 9 = 12 cm이다. 넓이를 구하는 데 필요한 정보를 찾고 두 넓이가 같다는 것을 이용했다.","scoring_points":["삼각형 넓이 108 cm²(모선은 쓰지 않음)를 구했는가","108 ÷ 9 = 12 cm를 구했는가","해결 방법(필요한 정보·같은 넓이)을 설명했는가"]},"explanation":["18 × 12 ÷ 2 = 108이에요.","108 ÷ 9 = 12 cm예요.","필요한 정보만 골라 같은 넓이를 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#1','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C1',1,'mc','auto','가 위아래 두 원의 크기가 다른 통 · 나 둥근 기둥 모양의 통 · 다 서로 평행하고 합동인 두 면이 삼각형인 상자 · 라 길쭉한 둥근 기둥 모양의 통 · 마 뾰족한 뿔 모양의 상자 · 바 납작한 둥근 기둥 모양의 통 — 원기둥을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X02','M6-2-u6-X01']::text[],true,'{"seq":1,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"가 위아래 두 원의 크기가 다른 통 · 나 둥근 기둥 모양의 통 · 다 서로 평행하고 합동인 두 면이 삼각형인 상자 · 라 길쭉한 둥근 기둥 모양의 통 · 마 뾰족한 뿔 모양의 상자 · 바 납작한 둥근 기둥 모양의 통 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"나, 라, 바","correct":true},{"t":"나, 라","mis":"M6-2-u6-X02"},{"t":"가, 나, 라, 바","mis":"M6-2-u6-X02"},{"t":"나, 다, 라, 바","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","나, 라, 바 모두 원기둥이에요."],"variant_rule":{"alt":[{"stem":"가 서로 평행하고 합동인 두 면이 삼각형인 입체도형 · 나 둥근 기둥 모양의 입체도형 · 다 마주 보는 두 면이 원이지만 크기가 다른 입체도형 · 라 눕혀 놓은 둥근 기둥 모양의 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나","mis":"M6-2-u6-X05"},{"t":"나, 다, 라","mis":"M6-2-u6-X02"},{"t":"가, 나, 라","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","나, 라 모두 원기둥이에요."]},{"stem":"가 밑면이 원이고 뾰족한 뿔 모양인 입체도형 · 나 상자 모양의 각기둥 · 다 둥근 기둥 모양의 입체도형 · 라 납작한 둥근 기둥 모양의 입체도형 · 마 작은 뿔 모양이고 밑면이 원인 입체도형 · 바 밑면이 다각형인 뿔 모양의 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"다, 라","correct":true},{"t":"다","mis":"M6-2-u6-X05"},{"t":"나, 다, 라","mis":"M6-2-u6-X01"},{"t":"가, 다, 라, 마","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","다, 라 모두 원기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#2','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C5',1,'mc','auto','가 밑면이 원이고 뾰족한 뿔 모양인 입체도형 · 나 상자 모양의 각기둥 · 다 둥근 기둥 모양의 입체도형 · 라 납작한 둥근 기둥 모양의 입체도형 · 마 작은 뿔 모양이고 밑면이 원인 입체도형 · 바 밑면이 다각형인 뿔 모양의 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X14','M6-2-u6-X01']::text[],true,'{"seq":2,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"가 밑면이 원이고 뾰족한 뿔 모양인 입체도형 · 나 상자 모양의 각기둥 · 다 둥근 기둥 모양의 입체도형 · 라 납작한 둥근 기둥 모양의 입체도형 · 마 작은 뿔 모양이고 밑면이 원인 입체도형 · 바 밑면이 다각형인 뿔 모양의 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 마","correct":true},{"t":"가","mis":"M6-2-u6-X14"},{"t":"가, 마, 바","mis":"M6-2-u6-X01"},{"t":"가, 라, 마","mis":"M6-2-u6-X14"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 마 모두 원뿔이에요."],"variant_rule":{"alt":[{"stem":"가 밑면이 다각형인 뿔 모양의 입체도형 · 나 서로 평행하고 합동인 두 원이 있는 기둥 모양 · 다 거꾸로 세운 뿔 모양이고 한 원을 면으로 하는 입체도형 · 라 눕혀 놓은 뿔 모양이고 한 원을 면으로 하는 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"다, 라","correct":true},{"t":"다","mis":"M6-2-u6-X14"},{"t":"가, 다, 라","mis":"M6-2-u6-X01"},{"t":"나, 다, 라","mis":"M6-2-u6-X14"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","다, 라 모두 원뿔이에요."]},{"stem":"가 뿔 모양이고 밑면이 원인 입체도형 · 나 공 모양의 입체도형 · 다 눕혀 놓은 둥근 기둥 모양 · 라 작은 공 모양의 입체도형 · 마 눕혀 놓은 뿔 모양이고 밑면이 원인 입체도형 · 바 납작한 둥근 기둥 모양 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 마","correct":true},{"t":"가","mis":"M6-2-u6-X14"},{"t":"가, 다, 마","mis":"M6-2-u6-X14"},{"t":"가, 나, 마","mis":"M6-2-u6-X03"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 마 모두 원뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#3','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C7',1,'mc','auto','가 공 모양의 입체도형 · 나 납작하게 눌린 둥근 모양 · 다 길쭉한 달걀 모양 · 라 작은 공 모양의 입체도형 — 구를 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X22']::text[],true,'{"seq":3,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"가 공 모양의 입체도형 · 나 납작하게 눌린 둥근 모양 · 다 길쭉한 달걀 모양 · 라 작은 공 모양의 입체도형 — 구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가","mis":"M6-2-u6-X22"},{"t":"가, 나, 라","mis":"M6-2-u6-X22"},{"t":"가, 다, 라","mis":"M6-2-u6-X22"}],"explanation":["구는 어느 방향에서 보아도 원인 공 모양의 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 라 모두 구예요."],"variant_rule":{"alt":[{"stem":"가 뿔 모양이고 밑면이 원인 입체도형 · 나 공 모양의 입체도형 · 다 눕혀 놓은 둥근 기둥 모양 · 라 작은 공 모양의 입체도형 · 마 눕혀 놓은 뿔 모양이고 밑면이 원인 입체도형 · 바 납작한 둥근 기둥 모양 — 구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나","mis":"M6-2-u6-X22"},{"t":"나, 다, 라","mis":"M6-2-u6-X22"},{"t":"가, 나, 라","mis":"M6-2-u6-X03"}],"explanation":["구는 어느 방향에서 보아도 원인 공 모양의 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","나, 라 모두 구예요."]},{"stem":"단원 평가 — 가 공 모양 · 나 뿔 모양 · 다 둥근 기둥 모양. 어느 방향에서 보아도 모양이 같은 입체도형을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M6-2-u6-X18"},{"t":"다","mis":"M6-2-u6-X18"},{"t":"가, 다","mis":"M6-2-u6-X18"}],"explanation":["원뿔은 앞에서 보면 삼각형, 위에서 보면 원이에요.","원기둥은 앞에서 보면 직사각형, 위에서 보면 원이에요.","어느 방향에서 보아도 원인 것은 구 — 가예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#4','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C1',1,'match','auto','한 바퀴 돌릴 때 기준으로 삼는 변과 만들어지는 입체도형을 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C1","difficulty":1,"kind":"match","stem":"한 바퀴 돌릴 때 기준으로 삼는 변과 만들어지는 입체도형을 이으세요.","pairs":[{"l":"직사각형의 한 변","r":"원기둥"},{"l":"직각삼각형의 직각을 낀 한 변","r":"원뿔"},{"l":"반원의 지름","r":"구"}],"mis":"M6-2-u6-X03","explanation":["직사각형은 한 변을 기준으로 돌려요.","직각삼각형은 직각이 있는 변을 기준으로 돌려요.","반원은 지름을 기준으로 돌려요."],"variant_rule":{"alt":[{"stem":"돌리기 전 평면도형의 부분과 만들어진 입체도형의 부분을 이으세요.","pairs":[{"l":"반원의 중심","r":"구의 중심"},{"l":"반원의 반지름","r":"구의 반지름"},{"l":"직각삼각형에서 막대에 붙인 변","r":"원뿔의 높이"}],"explanation":["원의 중심은 구의 중심이 돼요.","원의 반지름은 구의 반지름이 돼요.","막대에 붙인 변은 높이가 돼요."]},{"stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"막대에 붙인 변","r":"높이"},{"l":"뻗어 나간 변","r":"밑면의 반지름"},{"l":"뻗어 나간 변의 2배","r":"밑면의 지름"}],"explanation":["직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","막대에 붙인 변은 높이, 뻗은 변은 밑면의 반지름이에요.","밑면이 다각형이면 각기둥, 원이면 원기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#5','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C6',1,'mc','auto','원뿔에서 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 무엇이라고 하나요?',ARRAY['M6-2-u6-X15','M6-2-u6-X05']::text[],true,'{"seq":5,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"원뿔에서 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"모선","correct":true},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 모선이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."],"variant_rule":{"alt":[{"stem":"원뿔에서 뾰족한 부분의 점을 무엇이라고 하나요?","options":[{"t":"원뿔의 꼭짓점","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","뾰족한 부분의 점을 원뿔의 꼭짓점이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]},{"stem":"원기둥에서 두 밑면과 만나는 굽은 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면과 만나는 굽은 면을 옆면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#6','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C4',1,'mc','auto','종이 상자는 이물질을 없앤 다음 납작하게 부피를 줄여 분리배출해요. 상자를 잘라 펼친 가 · 나 · 다 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요? (가 직사각형의 위와 아래에 크기가 같은 원이 하나씩 · 나 직사각형의 왼쪽에 크기가 같은 두 원이 나란히 · 다 직사각형의 위에 큰 원, 아래에 작은 원)',ARRAY['M6-2-u6-X12','M6-2-u6-X02']::text[],true,'{"seq":6,"concept":"M6-2-u6-C4","difficulty":1,"kind":"mc","stem":"종이 상자는 이물질을 없앤 다음 납작하게 부피를 줄여 분리배출해요. 상자를 잘라 펼친 가 · 나 · 다 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요? (가 직사각형의 위와 아래에 크기가 같은 원이 하나씩 · 나 직사각형의 왼쪽에 크기가 같은 두 원이 나란히 · 다 직사각형의 위에 큰 원, 아래에 작은 원)","options":[{"t":"가","correct":true},{"t":"나","mis":"M6-2-u6-X12"},{"t":"다","mis":"M6-2-u6-X02"},{"t":"셋 다 될 수 있어요","mis":"M6-2-u6-X02"}],"explanation":["나는 두 원이 같은 쪽에 있어 접으면 겹쳐요.","다는 두 원이 서로 합동이 아니에요.","그래서 원기둥의 전개도는 가예요."],"variant_rule":{"alt":[{"stem":"『수학』 129쪽 가~라 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요? (가 직사각형의 위와 아래에 크기가 같은 원 · 나 사다리꼴 옆면 · 다 두 원이 위쪽에 나란히 · 라 크기가 다른 두 원)","options":[{"t":"가","correct":true},{"t":"나","mis":"M6-2-u6-X11"},{"t":"다","mis":"M6-2-u6-X12"},{"t":"라","mis":"M6-2-u6-X02"}],"explanation":["나는 옆면이 직사각형이 아니에요.","다는 두 원이 겹치고, 라는 두 원이 합동이 아니에요.","그래서 가예요."]},{"stem":"형성 평가 — 가 직사각형의 위쪽에 크기가 같은 두 원이 나란히 · 나 직사각형의 위에 작은 원, 아래에 큰 원 · 다 세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 같은 원이 하나씩. 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M6-2-u6-X12"},{"t":"나","mis":"M6-2-u6-X02"},{"t":"가와 다","mis":"M6-2-u6-X12"}],"explanation":["가는 두 원이 겹쳐요.","나는 두 원이 합동이 아니에요.","다는 옆면이 직사각형이고 합동인 두 원이 마주 보아 전개도가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#7','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C7',1,'mc','auto','『수학익힘』 93쪽 — ㉠ 구는 꼭짓점이 없어요. ㉡ 구는 밑면이 2개 있어요. ㉢ 구의 중심은 1개예요. ㉣ 구의 반지름은 무수히 많고 그 길이가 모두 달라요. 바르게 설명한 것을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X17']::text[],true,'{"seq":7,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"『수학익힘』 93쪽 — ㉠ 구는 꼭짓점이 없어요. ㉡ 구는 밑면이 2개 있어요. ㉢ 구의 중심은 1개예요. ㉣ 구의 반지름은 무수히 많고 그 길이가 모두 달라요. 바르게 설명한 것을 모두 찾은 것은 어느 것인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠, ㉡","mis":"M6-2-u6-X05"},{"t":"㉢, ㉣","mis":"M6-2-u6-X17"},{"t":"㉠, ㉢, ㉣","mis":"M6-2-u6-X17"}],"explanation":["구에는 밑면이 없어요 — ㉡은 틀려요.","구의 반지름은 길이가 모두 같아요 — ㉣은 틀려요.","바른 것은 ㉠, ㉢이에요."],"variant_rule":{"alt":[{"stem":"단원 평가 — 원뿔에 대한 설명 ㉠ 어느 방향에서 보아도 원 모양이에요. ㉡ 원뿔의 꼭짓점은 2개예요. ㉢ 직사각형을 한 변을 기준으로 한 바퀴 돌려서 만들 수 있어요. ㉣ 원뿔의 높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요. 옳은 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"M6-2-u6-X18"},{"t":"㉡","mis":"M6-2-u6-X07"},{"t":"㉢","mis":"M6-2-u6-X03"}],"explanation":["원뿔을 앞에서 보면 삼각형이고, 꼭짓점은 1개예요.","직사각형을 돌리면 원기둥이 돼요.","옳은 것은 ㉣이에요."]},{"stem":"단원 평가 — 원기둥과 원뿔에 대한 설명 ㉠ 원기둥과 원뿔의 밑면은 모두 원이에요. ㉡ 원기둥과 원뿔의 밑면은 각각 2개예요. 잘못 설명한 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u6-X19"},{"t":"둘 다 맞아요","mis":"M6-2-u6-X05"},{"t":"둘 다 틀려요","mis":"M6-2-u6-X19"}],"explanation":["원기둥과 원뿔의 밑면은 모두 원이에요 — ㉠은 맞아요.","원기둥의 밑면은 2개, 원뿔은 1개예요.","그래서 잘못 설명한 것은 ㉡이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#8','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C6',1,'sa','auto','원뿔의 밑면은 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C6","difficulty":1,"kind":"sa","stem":"원뿔의 밑면은 몇 개인가요?","answer":["1"],"explanation":["원기둥·원뿔·구의 정의와 구성 요소를 떠올려요.","한 원을 면으로 해요 — 1개예요.","원기둥 밑면 2 · 원뿔 밑면 1 · 구의 중심 1이에요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"구의 중심은 몇 개인가요?","answer":["1"],"explanation":["원기둥·원뿔·구의 정의와 구성 요소를 떠올려요.","돌리기 전 원의 중심 하나가 구의 중심 — 1개예요.","원기둥 밑면 2 · 원뿔 밑면 1 · 구의 중심 1이에요."]},{"stem":"원기둥의 옆면은 몇 개인가요?","answer":["1"],"explanation":["원기둥·원뿔·구의 정의와 구성 요소를 떠올려요.","두 밑면과 만나는 굽은 면 하나 — 1개예요.","원기둥 밑면 2 · 원뿔 밑면 1 · 구의 중심 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#9','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C3',2,'mc','auto','『수학』 130쪽 활동 6 — 밑면의 반지름이 1 cm, 높이가 2 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":9,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"『수학』 130쪽 활동 6 — 밑면의 반지름이 1 cm, 높이가 2 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"6.28 cm","correct":true},{"t":"2 cm","mis":"M6-2-u6-X08"},{"t":"3.14 cm","mis":"M6-2-u6-X08"},{"t":"12.56 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 2 cm예요.","2 × 3.14 = 6.28 cm예요."],"variant_rule":{"alt":[{"stem":"『수학익힘』 89쪽 — 밑면의 반지름이 1.5 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"9.42 cm","correct":true},{"t":"3 cm","mis":"M6-2-u6-X08"},{"t":"4.71 cm","mis":"M6-2-u6-X08"},{"t":"18.84 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 3 cm예요.","3 × 3.14 = 9.42 cm예요."]},{"stem":"단원 평가 — 밑면의 반지름이 0.5 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"3.14 cm","correct":true},{"t":"1 cm","mis":"M6-2-u6-X08"},{"t":"1.57 cm","mis":"M6-2-u6-X08"},{"t":"3 cm","mis":"M6-2-u6-X09"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 1 cm예요.","1 × 3.14 = 3.14 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#10','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C3',2,'sa','auto','원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 5 cm는 높이예요.","18.84 ÷ 3.14 = 6 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 가로가 31.4 cm, 세로가 11 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["10"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 11 cm는 높이예요.","31.4 ÷ 3.14 = 10 cm예요."]},{"stem":"원기둥의 전개도에서 옆면의 가로가 6.28 cm, 세로가 2 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["2"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 2 cm는 높이예요.","6.28 ÷ 3.14 = 2 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#11','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C1',2,'sa','auto','가로 9 cm, 세로 4 cm인 직사각형을 길이가 9 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":11,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 9 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 높이는 몇 cm인가요?","answer":["9"],"explanation":["기준으로 한 9 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 4 cm 변은 밑면의 반지름이 돼요.","그래서 높이는 9 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 4 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["18"],"explanation":["기준으로 한 4 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 9 cm 변은 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 9 × 2 = 18 cm예요."]},{"stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 4 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 높이는 몇 cm인가요?","answer":["4"],"explanation":["기준으로 한 4 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 9 cm 변은 밑면의 반지름이 돼요.","그래서 높이는 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#12','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C5',2,'sa','auto','『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 높이는 몇 cm인가요?","answer":["5"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","그래서 높이는 5 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","그래서 밑면의 반지름은 7 cm예요."]},{"stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["19"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","지름 14 cm와 높이 5 cm — 14 + 5 = 19 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#13','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C6',2,'sa','auto','원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 4 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 5 cm, 밑면의 반지름은 3 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":13,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 4 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 5 cm, 밑면의 반지름은 3 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["5"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 모선의 길이는 5 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 15 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 17 cm, 밑면의 반지름은 8 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["15"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 높이는 15 cm예요 — 17 cm는 모선이에요."]},{"stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 8 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 10 cm, 밑면의 반지름은 6 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["10"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 모선의 길이는 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#14','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C7',2,'sa','auto','반지름이 6 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u6-C7","difficulty":2,"kind":"sa","stem":"반지름이 6 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["12"],"explanation":["돌리기 전 원의 반지름이 구의 반지름 — 6 cm예요.","구의 지름은 반지름의 2배예요.","6 × 2 = 12 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["8"],"explanation":["돌리기 전 원의 반지름이 구의 반지름 — 4 cm예요.","구의 지름은 반지름의 2배예요.","4 × 2 = 8 cm예요."]},{"stem":"반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["16"],"explanation":["돌리기 전 원의 반지름이 구의 반지름 — 8 cm예요.","구의 지름은 반지름의 2배예요.","8 × 2 = 16 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#15','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C2',2,'sa','auto','『수학익힘』 87쪽의 원기둥 모양 물건이 눕혀 놓여 있어요. 밑면의 지름은 6 cm이고, 두 밑면 사이의 거리는 12 cm예요. 이 물건의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u6-C2","difficulty":2,"kind":"sa","stem":"『수학익힘』 87쪽의 원기둥 모양 물건이 눕혀 놓여 있어요. 밑면의 지름은 6 cm이고, 두 밑면 사이의 거리는 12 cm예요. 이 물건의 높이는 몇 cm인가요?","answer":["12"],"explanation":["눕혀 놓아도 서로 평행하고 합동인 두 원이 밑면이에요.","높이는 두 밑면 사이의 거리예요 — 바닥에서 위까지의 길이가 아니에요.","그래서 높이는 12 cm예요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"단원 평가 — 밑면의 지름이 6 cm이고 두 밑면 사이의 거리가 4 cm인 원기둥이 있어요. 이 원기둥의 높이는 몇 cm인가요?","answer":["4"],"explanation":["높이는 두 밑면 사이의 거리예요.","밑면의 지름 6 cm는 높이와 상관없어요.","그래서 높이는 4 cm예요."]},{"stem":"밑면의 반지름이 4 cm, 높이가 8 cm인 원기둥의 전개도에서 옆면의 세로는 몇 cm인가요?","answer":["8"],"explanation":["옆면의 세로는 두 밑면 사이를 이어요.","두 밑면 사이의 거리가 원기둥의 높이예요.","그래서 옆면의 세로는 높이와 같은 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#16','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C8',2,'mc','auto','원기둥을 옆에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":16,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"원기둥을 옆에서 본 모양은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 옆에서 본 모양은 직사각형이에요."],"variant_rule":{"alt":[{"stem":"구를 옆에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 구를 옆에서 본 모양은 원이에요."]},{"stem":"원뿔을 위에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 위에서 본 모양은 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#17','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C7',3,'ox','auto','원기둥·원뿔·구를 위에서 본 모양은 모두 원이에요.',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":17,"concept":"M6-2-u6-C7","difficulty":3,"kind":"ox","stem":"원기둥·원뿔·구를 위에서 본 모양은 모두 원이에요.","answer":"O","reason_options":[{"t":"세 입체도형 모두 위에서 보면 둥근 테두리만 보이기 때문에","correct":true},{"t":"셋 다 앞에서 본 모양과 위에서 본 모양이 같기 때문에","mis":"M6-2-u6-X18"}],"mis":"M6-2-u6-X18","explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."],"variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 직사각형의 가로는 밑면의 지름이에요.","answer":"O","reason_options":[{"t":"밑면인 원이 지름만큼의 선분으로 보이기 때문에","correct":true},{"t":"가로는 밑면의 둘레이기 때문에","mis":"M6-2-u6-X08"}],"explanation":["원뿔을 앞에서 보면 삼각형 — 밑변은 밑면의 지름, 높이는 원뿔의 높이예요.","원기둥을 앞에서 보면 직사각형 — 가로는 지름, 세로는 높이예요.","모선은 삼각형의 옆 변이에요."]},{"stem":"구를 앞에서 본 모양은 반원이에요.","answer":"X","reason_options":[{"t":"구는 어느 방향에서 보아도 원이기 때문에","correct":true},{"t":"반원을 돌려 만들었기 때문에","mis":"M6-2-u6-X18"}],"explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#18','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C8',3,'mc','auto','밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":18,"concept":"M6-2-u6-C8","difficulty":3,"kind":"mc","stem":"밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"48 cm²","correct":true},{"t":"96 cm²","mis":"M6-2-u6-X20"},{"t":"24 cm²","mis":"M6-2-u6-X20"},{"t":"60 cm²","mis":"M6-2-u6-X15"}],"explanation":["앞에서 본 삼각형의 밑변은 밑면의 지름 12 cm, 높이는 원뿔의 높이 8 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선 10 cm는 쓰지 않아요.","12 × 8 ÷ 2 = 48 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 10 cm, 높이가 12 cm, 모선의 길이가 13 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"60 cm²","correct":true},{"t":"120 cm²","mis":"M6-2-u6-X20"},{"t":"30 cm²","mis":"M6-2-u6-X20"},{"t":"65 cm²","mis":"M6-2-u6-X15"}],"explanation":["앞에서 본 삼각형의 밑변은 밑면의 지름 10 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선 13 cm는 쓰지 않아요.","10 × 12 ÷ 2 = 60 cm²예요."]},{"stem":"밑면의 지름이 10 cm, 높이가 11 cm인 원기둥을 앞에서 보았어요. 앞에서 본 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"110 cm²","correct":true},{"t":"55 cm²","mis":"M6-2-u6-X20"},{"t":"345.4 cm²","mis":"M6-2-u6-X08"},{"t":"42 cm²","mis":"M6-2-u6-X20"}],"explanation":["원기둥을 앞에서 보면 직사각형이에요.","가로는 밑면의 지름 10 cm, 세로는 높이 11 cm예요.","10 × 11 = 110 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#19','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C8',3,'sa','auto','원뿔 모양 모자는 밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm예요. 원기둥 모양 모자는 밑면의 반지름이 4 cm예요. 두 모자를 앞에서 본 모양의 넓이가 같을 때 원기둥 모양 모자의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":19,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"원뿔 모양 모자는 밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm예요. 원기둥 모양 모자는 밑면의 반지름이 4 cm예요. 두 모자를 앞에서 본 모양의 넓이가 같을 때 원기둥 모양 모자의 높이는 몇 cm인가요?","answer":["6"],"explanation":["원뿔을 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥을 앞에서 본 직사각형의 가로는 밑면의 지름 4 × 2 = 8 cm예요.","세로(높이)는 48 ÷ 8 = 6 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"세계 전통 의상 체험관의 원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 원기둥 모양 모자의 밑면의 지름이 12 cm이고 두 모자를 앞에서 본 모양의 넓이가 같을 때, 원기둥 모양 모자의 높이는 몇 cm인가요?","answer":["9"],"explanation":["원뿔을 앞에서 본 삼각형의 넓이는 18 × 12 ÷ 2 = 108 cm²예요.","원기둥을 앞에서 본 직사각형도 108 cm² — 가로는 지름 12 cm예요.","세로(높이)는 108 ÷ 12 = 9 cm예요."]},{"stem":"원뿔 모양 모자는 밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm예요. 원기둥 모양 모자의 높이가 6 cm이고 두 모자를 앞에서 본 모양의 넓이가 같을 때, 원기둥 모양 모자의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["원뿔을 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥을 앞에서 본 직사각형도 48 cm² — 세로는 높이 6 cm예요.","가로(지름)는 48 ÷ 6 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#20','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C4',3,'mc','auto','『수학』 129쪽의 라 — 「세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 다른 두 원이 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":20,"concept":"M6-2-u6-C4","difficulty":3,"kind":"mc","stem":"『수학』 129쪽의 라 — 「세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 다른 두 원이 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 원이 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 두 원이 서로 합동이 아니어서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"『수학』 141쪽 마무리 4의 가 — 「직사각형 옆면의 위쪽에 크기가 같은 두 원이 나란히 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"두 원이 겹쳐서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X12"},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X12"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X12"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 두 원이 겹쳐서 전개도가 될 수 없어요."]},{"stem":"형성 평가의 나 — 「직사각형의 위에 작은 원, 아래에 큰 원이 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 원이 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 두 원이 서로 합동이 아니어서 전개도가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#21','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C3',3,'sa','auto','원기둥의 전개도에서 옆면의 가로가 18.84 cm예. 이 원기둥의 밑면의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u6-C3","difficulty":3,"kind":"sa","stem":"원기둥의 전개도에서 옆면의 가로가 18.84 cm예. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 18.84 ÷ 3.14 = 6 cm예요.","반지름은 6 ÷ 2 = 3 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 가로가 25.12 cm예. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["4"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 25.12 ÷ 3.14 = 8 cm예요.","반지름은 8 ÷ 2 = 4 cm예요."]},{"stem":"원기둥의 전개도에서 옆면의 가로가 31.4 cm예. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 31.4 ÷ 3.14 = 10 cm예요.","반지름은 10 ÷ 2 = 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#22','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C5',3,'mc','auto','단원 평가 — 가는 원뿔, 나는 오각뿔이에요. ㉠ 가는 원뿔이고 나는 오각뿔이에요. ㉡ 가와 나는 모두 꼭짓점이 1개뿐이에요. ㉢ 가와 나는 모두 뿔 모양이에요. 잘못 설명한 것은 어느 것인가요?',ARRAY['M6-2-u6-X19','M6-2-u6-X14','M6-2-u6-X07']::text[],true,'{"seq":22,"concept":"M6-2-u6-C5","difficulty":3,"kind":"mc","stem":"단원 평가 — 가는 원뿔, 나는 오각뿔이에요. ㉠ 가는 원뿔이고 나는 오각뿔이에요. ㉡ 가와 나는 모두 꼭짓점이 1개뿐이에요. ㉢ 가와 나는 모두 뿔 모양이에요. 잘못 설명한 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u6-X19"},{"t":"㉢","mis":"M6-2-u6-X14"},{"t":"잘못 설명한 것이 없어요","mis":"M6-2-u6-X07"}],"explanation":["원뿔의 꼭짓점은 1개예요.","오각뿔은 밑면의 꼭짓점 5개와 각뿔의 꼭짓점 1개 — 6개예요.","그래서 ㉡이 잘못이에요."],"variant_rule":{"alt":[{"stem":"원기둥과 원뿔의 다른 점은 어느 것인가요?","options":[{"t":"원기둥은 밑면이 2개, 원뿔은 1개예요","correct":true},{"t":"원기둥은 밑면이 원, 원뿔은 다각형이에요","mis":"M6-2-u6-X01"},{"t":"원뿔에는 옆면이 없어요","mis":"M6-2-u6-X14"},{"t":"원기둥은 높이가 없어요","mis":"M6-2-u6-X06"}],"explanation":["원기둥과 원뿔 모두 밑면이 원이고 옆면이 굽은 면이에요.","원기둥은 밑면이 2개, 원뿔은 1개예요.","원뿔에는 뾰족한 꼭짓점이 있고 원기둥에는 없어요."]},{"stem":"원기둥과 각기둥의 같은 점은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 밑면이 있어요","correct":true},{"t":"밑면의 모양이 같아요","mis":"M6-2-u6-X01"},{"t":"옆면이 모두 직사각형이에요","mis":"M6-2-u6-X01"},{"t":"꼭짓점이 있어요","mis":"M6-2-u6-X07"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#23','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C7',4,'essay','teacher','단원 평가 — 원뿔과 구의 같은 점과 다른 점을 각각 한 가지씩 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M6-2-u6-C7","difficulty":4,"kind":"essay","stem":"단원 평가 — 원뿔과 구의 같은 점과 다른 점을 각각 한 가지씩 써 보세요.","answer_guide":{"answer":"예: 같은 점 — 위에서 본 모양이 원이다(굽은 면이 있다). 다른 점 — 원뿔은 꼭짓점이 있고, 구는 꼭짓점이 없다(원뿔은 평평한 면이 1개, 구는 없다).","scoring_points":["같은 점(위에서 본 모양이 원 등)을 썼는가","다른 점(꼭짓점·평평한 면 등)을 썼는가","원뿔과 구의 성질을 바르게 썼는가"]},"explanation":["둘 다 위에서 보면 원이에요.","원뿔은 꼭짓점이 있어요.","구는 꼭짓점이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#24','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C3',4,'essay','teacher','단원 평가 — 밑면의 반지름이 0.5 cm, 높이가 3 cm인 원기둥의 전개도를 완성하고 각 부분의 길이를 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u6-C3","difficulty":4,"kind":"essay","stem":"단원 평가 — 밑면의 반지름이 0.5 cm, 높이가 3 cm인 원기둥의 전개도를 완성하고 각 부분의 길이를 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 밑면의 지름은 0.5 × 2 = 1 cm이므로 옆면의 가로는 1 × 3.14 = 3.14 cm이다. 옆면의 세로는 높이 3 cm이다. 합동인 두 밑면(반지름 0.5 cm)을 옆면을 기준으로 마주 보게 그린다.","scoring_points":["지름 1 cm를 구했는가","옆면의 가로 3.14 cm·세로 3 cm를 구했는가","합동인 두 밑면을 마주 보게 그린다고 썼는가"]},"explanation":["지름은 1 cm예요.","가로 3.14 cm, 세로 3 cm예요.","두 밑면은 마주 보게 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_b#25','math',6,2,'u6','','tb_g6_2_math_u6_review_b','unit_review','M6-2-u6-C8',4,'essay','teacher','『수학』 139쪽 2번 — 원뿔(밑면의 반지름 6 cm, 높이 8 cm, 모선 10 cm)과 원기둥(밑면의 반지름 4 cm)을 앞에서 본 모양의 넓이가 같을 때 원기둥의 높이를 구하고, 풀이 과정을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u6-C8","difficulty":4,"kind":"essay","stem":"『수학』 139쪽 2번 — 원뿔(밑면의 반지름 6 cm, 높이 8 cm, 모선 10 cm)과 원기둥(밑면의 반지름 4 cm)을 앞에서 본 모양의 넓이가 같을 때 원기둥의 높이를 구하고, 풀이 과정을 써 보세요.","answer_guide":{"answer":"예: 원뿔을 앞에서 본 모양은 삼각형이고 넓이는 12 × 8 ÷ 2 = 48 cm²이다. 원기둥을 앞에서 본 모양은 가로가 4 × 2 = 8 cm인 직사각형이고 넓이가 48 cm²이므로 8 × □ = 48, 높이는 6 cm이다.","scoring_points":["삼각형 넓이 48 cm²를 구했는가","원기둥 앞모양의 가로를 지름 8 cm로 잡았는가","높이 6 cm를 구했는가"]},"explanation":["12 × 8 ÷ 2 = 48이에요.","가로는 지름 8 cm예요.","48 ÷ 8 = 6 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#1','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C1',1,'mc','auto','가 서로 평행하고 합동인 두 면이 삼각형인 입체도형 · 나 둥근 기둥 모양의 입체도형 · 다 마주 보는 두 면이 원이지만 크기가 다른 입체도형 · 라 눕혀 놓은 둥근 기둥 모양의 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X02','M6-2-u6-X01']::text[],true,'{"seq":1,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"가 서로 평행하고 합동인 두 면이 삼각형인 입체도형 · 나 둥근 기둥 모양의 입체도형 · 다 마주 보는 두 면이 원이지만 크기가 다른 입체도형 · 라 눕혀 놓은 둥근 기둥 모양의 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나","mis":"M6-2-u6-X05"},{"t":"나, 다, 라","mis":"M6-2-u6-X02"},{"t":"가, 나, 라","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","나, 라 모두 원기둥이에요."],"variant_rule":{"alt":[{"stem":"가 밑면이 원이고 뾰족한 뿔 모양인 입체도형 · 나 상자 모양의 각기둥 · 다 둥근 기둥 모양의 입체도형 · 라 납작한 둥근 기둥 모양의 입체도형 · 마 작은 뿔 모양이고 밑면이 원인 입체도형 · 바 밑면이 다각형인 뿔 모양의 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"다, 라","correct":true},{"t":"다","mis":"M6-2-u6-X05"},{"t":"나, 다, 라","mis":"M6-2-u6-X01"},{"t":"가, 다, 라, 마","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","다, 라 모두 원기둥이에요."]},{"stem":"가 둥근 기둥 모양 · 나 육각기둥 · 다 각뿔 · 라 공 모양 · 마 눕혀 놓은 둥근 기둥 모양 · 바 뿔 모양이고 밑면이 원인 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 마","correct":true},{"t":"가","mis":"M6-2-u6-X05"},{"t":"가, 나, 마","mis":"M6-2-u6-X01"},{"t":"가, 마, 바","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 마 모두 원기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#2','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C5',1,'mc','auto','가 밑면이 다각형인 뿔 모양의 입체도형 · 나 서로 평행하고 합동인 두 원이 있는 기둥 모양 · 다 거꾸로 세운 뿔 모양이고 한 원을 면으로 하는 입체도형 · 라 눕혀 놓은 뿔 모양이고 한 원을 면으로 하는 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X14','M6-2-u6-X01']::text[],true,'{"seq":2,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"가 밑면이 다각형인 뿔 모양의 입체도형 · 나 서로 평행하고 합동인 두 원이 있는 기둥 모양 · 다 거꾸로 세운 뿔 모양이고 한 원을 면으로 하는 입체도형 · 라 눕혀 놓은 뿔 모양이고 한 원을 면으로 하는 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"다, 라","correct":true},{"t":"다","mis":"M6-2-u6-X14"},{"t":"가, 다, 라","mis":"M6-2-u6-X01"},{"t":"나, 다, 라","mis":"M6-2-u6-X14"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","다, 라 모두 원뿔이에요."],"variant_rule":{"alt":[{"stem":"가 뿔 모양이고 밑면이 원인 입체도형 · 나 공 모양의 입체도형 · 다 눕혀 놓은 둥근 기둥 모양 · 라 작은 공 모양의 입체도형 · 마 눕혀 놓은 뿔 모양이고 밑면이 원인 입체도형 · 바 납작한 둥근 기둥 모양 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 마","correct":true},{"t":"가","mis":"M6-2-u6-X14"},{"t":"가, 다, 마","mis":"M6-2-u6-X14"},{"t":"가, 나, 마","mis":"M6-2-u6-X03"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 마 모두 원뿔이에요."]},{"stem":"가 둥근 기둥 모양 · 나 육각기둥 · 다 각뿔 · 라 공 모양 · 마 눕혀 놓은 둥근 기둥 모양 · 바 뿔 모양이고 밑면이 원인 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"바","correct":true},{"t":"다, 바","mis":"M6-2-u6-X01"},{"t":"가, 바","mis":"M6-2-u6-X14"},{"t":"다","mis":"M6-2-u6-X01"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","바 하나만 원뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#3','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C7',1,'mc','auto','가 뿔 모양이고 밑면이 원인 입체도형 · 나 공 모양의 입체도형 · 다 눕혀 놓은 둥근 기둥 모양 · 라 작은 공 모양의 입체도형 · 마 눕혀 놓은 뿔 모양이고 밑면이 원인 입체도형 · 바 납작한 둥근 기둥 모양 — 구를 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X22','M6-2-u6-X03']::text[],true,'{"seq":3,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"가 뿔 모양이고 밑면이 원인 입체도형 · 나 공 모양의 입체도형 · 다 눕혀 놓은 둥근 기둥 모양 · 라 작은 공 모양의 입체도형 · 마 눕혀 놓은 뿔 모양이고 밑면이 원인 입체도형 · 바 납작한 둥근 기둥 모양 — 구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나","mis":"M6-2-u6-X22"},{"t":"나, 다, 라","mis":"M6-2-u6-X22"},{"t":"가, 나, 라","mis":"M6-2-u6-X03"}],"explanation":["구는 어느 방향에서 보아도 원인 공 모양의 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","나, 라 모두 구예요."],"variant_rule":{"alt":[{"stem":"단원 평가 — 가 공 모양 · 나 뿔 모양 · 다 둥근 기둥 모양. 어느 방향에서 보아도 모양이 같은 입체도형을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M6-2-u6-X18"},{"t":"다","mis":"M6-2-u6-X18"},{"t":"가, 다","mis":"M6-2-u6-X18"}],"explanation":["원뿔은 앞에서 보면 삼각형, 위에서 보면 원이에요.","원기둥은 앞에서 보면 직사각형, 위에서 보면 원이에요.","어느 방향에서 보아도 원인 것은 구 — 가예요."]},{"stem":"가 둥근 기둥 모양 · 나 육각기둥 · 다 각뿔 · 라 공 모양 · 마 눕혀 놓은 둥근 기둥 모양 · 바 뿔 모양이고 밑면이 원인 입체도형 — 구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"라","correct":true},{"t":"가, 라","mis":"M6-2-u6-X22"},{"t":"라, 마","mis":"M6-2-u6-X22"},{"t":"가, 라, 마","mis":"M6-2-u6-X22"}],"explanation":["구는 어느 방향에서 보아도 원인 공 모양의 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","라 하나만 구예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#4','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C7',1,'match','auto','돌리기 전 평면도형의 부분과 만들어진 입체도형의 부분을 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C7","difficulty":1,"kind":"match","stem":"돌리기 전 평면도형의 부분과 만들어진 입체도형의 부분을 이으세요.","pairs":[{"l":"반원의 중심","r":"구의 중심"},{"l":"반원의 반지름","r":"구의 반지름"},{"l":"직각삼각형에서 막대에 붙인 변","r":"원뿔의 높이"}],"mis":"M6-2-u6-X04","explanation":["원의 중심은 구의 중심이 돼요.","원의 반지름은 구의 반지름이 돼요.","막대에 붙인 변은 높이가 돼요."],"variant_rule":{"alt":[{"stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"막대에 붙인 변","r":"높이"},{"l":"뻗어 나간 변","r":"밑면의 반지름"},{"l":"뻗어 나간 변의 2배","r":"밑면의 지름"}],"explanation":["직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","막대에 붙인 변은 높이, 뻗은 변은 밑면의 반지름이에요.","밑면이 다각형이면 각기둥, 원이면 원기둥이에요."]},{"stem":"『수학』 140쪽 마무리 2 — 평면도형을 한 직선을 기준으로 한 바퀴 돌려서 만들 수 있는 입체도형을 이으세요.","pairs":[{"l":"직각삼각형","r":"원뿔"},{"l":"직사각형","r":"원기둥"},{"l":"지름을 따라 반으로 나눈 원","r":"구"}],"explanation":["직각삼각형을 돌리면 원뿔이 돼요.","직사각형을 돌리면 원기둥이 돼요.","반원을 지름을 기준으로 돌리면 구가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#5','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C6',1,'mc','auto','원뿔에서 뾰족한 부분의 점을 무엇이라고 하나요?',ARRAY['M6-2-u6-X15','M6-2-u6-X05']::text[],true,'{"seq":5,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"원뿔에서 뾰족한 부분의 점을 무엇이라고 하나요?","options":[{"t":"원뿔의 꼭짓점","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","뾰족한 부분의 점을 원뿔의 꼭짓점이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."],"variant_rule":{"alt":[{"stem":"원기둥에서 두 밑면과 만나는 굽은 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면과 만나는 굽은 면을 옆면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]},{"stem":"원기둥에서 두 밑면 사이의 거리를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면 사이의 거리를 높이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#6','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C4',1,'mc','auto','『수학』 129쪽 가~라 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요? (가 직사각형의 위와 아래에 크기가 같은 원 · 나 사다리꼴 옆면 · 다 두 원이 위쪽에 나란히 · 라 크기가 다른 두 원)',ARRAY['M6-2-u6-X11','M6-2-u6-X12','M6-2-u6-X02']::text[],true,'{"seq":6,"concept":"M6-2-u6-C4","difficulty":1,"kind":"mc","stem":"『수학』 129쪽 가~라 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요? (가 직사각형의 위와 아래에 크기가 같은 원 · 나 사다리꼴 옆면 · 다 두 원이 위쪽에 나란히 · 라 크기가 다른 두 원)","options":[{"t":"가","correct":true},{"t":"나","mis":"M6-2-u6-X11"},{"t":"다","mis":"M6-2-u6-X12"},{"t":"라","mis":"M6-2-u6-X02"}],"explanation":["나는 옆면이 직사각형이 아니에요.","다는 두 원이 겹치고, 라는 두 원이 합동이 아니에요.","그래서 가예요."],"variant_rule":{"alt":[{"stem":"형성 평가 — 가 직사각형의 위쪽에 크기가 같은 두 원이 나란히 · 나 직사각형의 위에 작은 원, 아래에 큰 원 · 다 세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 같은 원이 하나씩. 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M6-2-u6-X12"},{"t":"나","mis":"M6-2-u6-X02"},{"t":"가와 다","mis":"M6-2-u6-X12"}],"explanation":["가는 두 원이 겹쳐요.","나는 두 원이 합동이 아니에요.","다는 옆면이 직사각형이고 합동인 두 원이 마주 보아 전개도가 돼요."]},{"stem":"『수학』 141쪽 마무리 4 — 가 직사각형의 위쪽에 크기가 같은 두 원이 나란히 · 나 사다리꼴 옆면의 위와 아래에 원 · 다 세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 같은 원이 하나씩 — 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M6-2-u6-X12"},{"t":"나","mis":"M6-2-u6-X11"},{"t":"가와 다","mis":"M6-2-u6-X12"}],"explanation":["가는 두 원이 겹쳐서 안 돼요.","나는 옆면이 직사각형이 아니어서 안 돼요.","다는 옆면이 직사각형이고 합동인 두 원이 마주 보아 전개도가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#7','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C6',1,'mc','auto','단원 평가 — 원뿔에 대한 설명 ㉠ 어느 방향에서 보아도 원 모양이에요. ㉡ 원뿔의 꼭짓점은 2개예요. ㉢ 직사각형을 한 변을 기준으로 한 바퀴 돌려서 만들 수 있어요. ㉣ 원뿔의 높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요. 옳은 것은 어느 것인가요?',ARRAY['M6-2-u6-X18','M6-2-u6-X07','M6-2-u6-X03']::text[],true,'{"seq":7,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"단원 평가 — 원뿔에 대한 설명 ㉠ 어느 방향에서 보아도 원 모양이에요. ㉡ 원뿔의 꼭짓점은 2개예요. ㉢ 직사각형을 한 변을 기준으로 한 바퀴 돌려서 만들 수 있어요. ㉣ 원뿔의 높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요. 옳은 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"M6-2-u6-X18"},{"t":"㉡","mis":"M6-2-u6-X07"},{"t":"㉢","mis":"M6-2-u6-X03"}],"explanation":["원뿔을 앞에서 보면 삼각형이고, 꼭짓점은 1개예요.","직사각형을 돌리면 원기둥이 돼요.","옳은 것은 ㉣이에요."],"variant_rule":{"alt":[{"stem":"단원 평가 — 원기둥과 원뿔에 대한 설명 ㉠ 원기둥과 원뿔의 밑면은 모두 원이에요. ㉡ 원기둥과 원뿔의 밑면은 각각 2개예요. 잘못 설명한 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u6-X19"},{"t":"둘 다 맞아요","mis":"M6-2-u6-X05"},{"t":"둘 다 틀려요","mis":"M6-2-u6-X19"}],"explanation":["원기둥과 원뿔의 밑면은 모두 원이에요 — ㉠은 맞아요.","원기둥의 밑면은 2개, 원뿔은 1개예요.","그래서 잘못 설명한 것은 ㉡이에요."]},{"stem":"『수학』 142쪽 마무리 6 — ㉠ 원기둥의 밑면은 1개예요. ㉡ 원기둥의 전개도에서 옆면은 원이에요. ㉢ 원뿔의 높이는 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요. ㉣ 구의 중심은 1개이고, 구의 반지름은 무수히 많아요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"M6-2-u6-X05"},{"t":"㉡","mis":"M6-2-u6-X13"},{"t":"㉢","mis":"M6-2-u6-X15"}],"explanation":["원기둥의 밑면은 2개, 전개도의 옆면은 직사각형이에요.","㉢은 높이가 아니라 모선의 뜻이에요.","바르게 설명한 것은 ㉣이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#8','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C7',1,'sa','auto','구의 중심은 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C7","difficulty":1,"kind":"sa","stem":"구의 중심은 몇 개인가요?","answer":["1"],"explanation":["원기둥·원뿔·구의 정의와 구성 요소를 떠올려요.","돌리기 전 원의 중심 하나가 구의 중심 — 1개예요.","원기둥 밑면 2 · 원뿔 밑면 1 · 구의 중심 1이에요."],"mis":"M6-2-u6-X17","variant_rule":{"alt":[{"stem":"원기둥의 옆면은 몇 개인가요?","answer":["1"],"explanation":["원기둥·원뿔·구의 정의와 구성 요소를 떠올려요.","두 밑면과 만나는 굽은 면 하나 — 1개예요.","원기둥 밑면 2 · 원뿔 밑면 1 · 구의 중심 1이에요."]},{"stem":"원기둥의 밑면은 몇 개인가요?","answer":["2"],"explanation":["원기둥·원뿔·구의 정의와 구성 요소를 떠올려요.","서로 평행하고 합동인 두 원 — 2개예요.","원기둥 밑면 2 · 원뿔 밑면 1 · 구의 중심 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#9','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C3',2,'mc','auto','『수학익힘』 89쪽 — 밑면의 반지름이 1.5 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":9,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"『수학익힘』 89쪽 — 밑면의 반지름이 1.5 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"9.42 cm","correct":true},{"t":"3 cm","mis":"M6-2-u6-X08"},{"t":"4.71 cm","mis":"M6-2-u6-X08"},{"t":"18.84 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 3 cm예요.","3 × 3.14 = 9.42 cm예요."],"variant_rule":{"alt":[{"stem":"단원 평가 — 밑면의 반지름이 0.5 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"3.14 cm","correct":true},{"t":"1 cm","mis":"M6-2-u6-X08"},{"t":"1.57 cm","mis":"M6-2-u6-X08"},{"t":"3 cm","mis":"M6-2-u6-X09"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 1 cm예요.","1 × 3.14 = 3.14 cm예요."]},{"stem":"『수학』 141쪽 마무리 5 — 밑면의 지름이 2 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"6.28 cm","correct":true},{"t":"2 cm","mis":"M6-2-u6-X08"},{"t":"3.14 cm","mis":"M6-2-u6-X08"},{"t":"3 cm","mis":"M6-2-u6-X09"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 2 cm예요.","2 × 3.14 = 6.28 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#10','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C3',2,'sa','auto','원기둥의 전개도에서 옆면의 가로가 31.4 cm, 세로가 11 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"원기둥의 전개도에서 옆면의 가로가 31.4 cm, 세로가 11 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["10"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 11 cm는 높이예요.","31.4 ÷ 3.14 = 10 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 가로가 6.28 cm, 세로가 2 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["2"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 2 cm는 높이예요.","6.28 ÷ 3.14 = 2 cm예요."]},{"stem":"원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 4 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 4 cm는 높이예요.","25.12 ÷ 3.14 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#11','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C1',2,'sa','auto','가로 9 cm, 세로 4 cm인 직사각형을 길이가 4 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":11,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 4 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["18"],"explanation":["기준으로 한 4 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 9 cm 변은 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 9 × 2 = 18 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 4 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 높이는 몇 cm인가요?","answer":["4"],"explanation":["기준으로 한 4 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 9 cm 변은 밑면의 반지름이 돼요.","그래서 높이는 4 cm예요."]},{"stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 9 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["기준으로 한 9 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 4 cm 변은 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 4 × 2 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#12','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C5',2,'sa','auto','『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","그래서 밑면의 반지름은 7 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["19"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","지름 14 cm와 높이 5 cm — 14 + 5 = 19 cm예요."]},{"stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 지름은 몇 cm인가요?","answer":["14"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","지름은 7 × 2 = 14 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#13','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C6',2,'sa','auto','원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 15 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 17 cm, 밑면의 반지름은 8 cm예요. 이 원뿔의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":13,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 15 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 17 cm, 밑면의 반지름은 8 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["15"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 높이는 15 cm예요 — 17 cm는 모선이에요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 8 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 10 cm, 밑면의 반지름은 6 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["10"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 모선의 길이는 10 cm예요."]},{"stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 13 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["12"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 높이는 12 cm예요 — 13 cm는 모선이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#14','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C7',2,'sa','auto','반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u6-C7","difficulty":2,"kind":"sa","stem":"반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["8"],"explanation":["돌리기 전 원의 반지름이 구의 반지름 — 4 cm예요.","구의 지름은 반지름의 2배예요.","4 × 2 = 8 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["16"],"explanation":["돌리기 전 원의 반지름이 구의 반지름 — 8 cm예요.","구의 지름은 반지름의 2배예요.","8 × 2 = 16 cm예요."]},{"stem":"반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["돌리기 전 원의 반지름은 구의 반지름이 돼요.","반원의 반지름이 8 cm예요.","그래서 구의 반지름은 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#15','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C2',2,'sa','auto','단원 평가 — 밑면의 지름이 6 cm이고 두 밑면 사이의 거리가 4 cm인 원기둥이 있어요. 이 원기둥의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u6-C2","difficulty":2,"kind":"sa","stem":"단원 평가 — 밑면의 지름이 6 cm이고 두 밑면 사이의 거리가 4 cm인 원기둥이 있어요. 이 원기둥의 높이는 몇 cm인가요?","answer":["4"],"explanation":["높이는 두 밑면 사이의 거리예요.","밑면의 지름 6 cm는 높이와 상관없어요.","그래서 높이는 4 cm예요."],"mis":"M6-2-u6-X06","variant_rule":{"alt":[{"stem":"밑면의 반지름이 4 cm, 높이가 8 cm인 원기둥의 전개도에서 옆면의 세로는 몇 cm인가요?","answer":["8"],"explanation":["옆면의 세로는 두 밑면 사이를 이어요.","두 밑면 사이의 거리가 원기둥의 높이예요.","그래서 옆면의 세로는 높이와 같은 8 cm예요."]},{"stem":"『수학익힘』 87쪽의 통조림은 원기둥 모양이에요. 밑면의 지름이 8 cm이고 두 밑면 사이의 거리가 3 cm예요. 이 통조림의 높이는 몇 cm인가요?","answer":["3"],"explanation":["원기둥의 높이는 두 밑면 사이의 거리예요.","밑면의 지름 8 cm는 높이가 아니에요.","그래서 높이는 3 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#16','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C8',2,'mc','auto','구를 옆에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":16,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"구를 옆에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 구를 옆에서 본 모양은 원이에요."],"variant_rule":{"alt":[{"stem":"원뿔을 위에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 위에서 본 모양은 원이에요."]},{"stem":"원뿔을 옆에서 본 모양은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 옆에서 본 모양은 삼각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#17','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C8',3,'ox','auto','원기둥을 앞에서 본 직사각형의 가로는 밑면의 지름이에요.',ARRAY['M6-2-u6-X08']::text[],true,'{"seq":17,"concept":"M6-2-u6-C8","difficulty":3,"kind":"ox","stem":"원기둥을 앞에서 본 직사각형의 가로는 밑면의 지름이에요.","answer":"O","reason_options":[{"t":"밑면인 원이 지름만큼의 선분으로 보이기 때문에","correct":true},{"t":"가로는 밑면의 둘레이기 때문에","mis":"M6-2-u6-X08"}],"mis":"M6-2-u6-X08","explanation":["원뿔을 앞에서 보면 삼각형 — 밑변은 밑면의 지름, 높이는 원뿔의 높이예요.","원기둥을 앞에서 보면 직사각형 — 가로는 지름, 세로는 높이예요.","모선은 삼각형의 옆 변이에요."],"variant_rule":{"alt":[{"stem":"구를 앞에서 본 모양은 반원이에요.","answer":"X","reason_options":[{"t":"구는 어느 방향에서 보아도 원이기 때문에","correct":true},{"t":"반원을 돌려 만들었기 때문에","mis":"M6-2-u6-X18"}],"explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."]},{"stem":"『수학』 142쪽 마무리 7 — 원기둥, 원뿔, 구를 옆에서 본 모양은 서로 같아요.","answer":"X","reason_options":[{"t":"옆에서 본 모양이 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이라 서로 다르기 때문에","correct":true},{"t":"셋 다 위에서 본 모양이 원이기 때문에","mis":"M6-2-u6-X18"}],"explanation":["원기둥을 옆에서 보면 직사각형이에요.","원뿔은 삼각형, 구는 원이에요.","그래서 옆에서 본 모양은 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#18','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C8',3,'mc','auto','밑면의 지름이 10 cm, 높이가 12 cm, 모선의 길이가 13 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":18,"concept":"M6-2-u6-C8","difficulty":3,"kind":"mc","stem":"밑면의 지름이 10 cm, 높이가 12 cm, 모선의 길이가 13 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"60 cm²","correct":true},{"t":"120 cm²","mis":"M6-2-u6-X20"},{"t":"30 cm²","mis":"M6-2-u6-X20"},{"t":"65 cm²","mis":"M6-2-u6-X15"}],"explanation":["앞에서 본 삼각형의 밑변은 밑면의 지름 10 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선 13 cm는 쓰지 않아요.","10 × 12 ÷ 2 = 60 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 10 cm, 높이가 11 cm인 원기둥을 앞에서 보았어요. 앞에서 본 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"110 cm²","correct":true},{"t":"55 cm²","mis":"M6-2-u6-X20"},{"t":"345.4 cm²","mis":"M6-2-u6-X08"},{"t":"42 cm²","mis":"M6-2-u6-X20"}],"explanation":["원기둥을 앞에서 보면 직사각형이에요.","가로는 밑면의 지름 10 cm, 세로는 높이 11 cm예요.","10 × 11 = 110 cm²예요."]},{"stem":"밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"108 cm²","correct":true},{"t":"216 cm²","mis":"M6-2-u6-X20"},{"t":"54 cm²","mis":"M6-2-u6-X20"},{"t":"135 cm²","mis":"M6-2-u6-X15"}],"explanation":["앞에서 본 삼각형의 밑변은 밑면의 지름 18 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선 15 cm는 쓰지 않아요.","18 × 12 ÷ 2 = 108 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#19','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C8',3,'sa','auto','세계 전통 의상 체험관의 원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 원기둥 모양 모자의 밑면의 지름이 12 cm이고 두 모자를 앞에서 본 모양의 넓이가 같을 때, 원기둥 모양 모자의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":19,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"세계 전통 의상 체험관의 원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 원기둥 모양 모자의 밑면의 지름이 12 cm이고 두 모자를 앞에서 본 모양의 넓이가 같을 때, 원기둥 모양 모자의 높이는 몇 cm인가요?","answer":["9"],"explanation":["원뿔을 앞에서 본 삼각형의 넓이는 18 × 12 ÷ 2 = 108 cm²예요.","원기둥을 앞에서 본 직사각형도 108 cm² — 가로는 지름 12 cm예요.","세로(높이)는 108 ÷ 12 = 9 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원뿔 모양 모자는 밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm예요. 원기둥 모양 모자의 높이가 6 cm이고 두 모자를 앞에서 본 모양의 넓이가 같을 때, 원기둥 모양 모자의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["원뿔을 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥을 앞에서 본 직사각형도 48 cm² — 세로는 높이 6 cm예요.","가로(지름)는 48 ÷ 6 = 8 cm예요."]},{"stem":"세계 전통 의상 체험관의 원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 원기둥 모양 모자의 높이는 9 cm예요. 두 모자를 앞에서 본 모양의 넓이가 같을 때 원기둥 모양 모자의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["원뿔을 앞에서 본 삼각형의 밑변은 9 × 2 = 18 cm, 높이는 12 cm — 넓이는 18 × 12 ÷ 2 = 108 cm²예요.","원기둥을 앞에서 본 직사각형도 108 cm² — 세로는 높이 9 cm예요.","가로(지름)는 108 ÷ 9 = 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#20','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C4',3,'mc','auto','『수학』 141쪽 마무리 4의 가 — 「직사각형 옆면의 위쪽에 크기가 같은 두 원이 나란히 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?',ARRAY['M6-2-u6-X12']::text[],true,'{"seq":20,"concept":"M6-2-u6-C4","difficulty":3,"kind":"mc","stem":"『수학』 141쪽 마무리 4의 가 — 「직사각형 옆면의 위쪽에 크기가 같은 두 원이 나란히 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"두 원이 겹쳐서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X12"},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X12"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X12"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 두 원이 겹쳐서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"형성 평가의 나 — 「직사각형의 위에 작은 원, 아래에 큰 원이 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 원이 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 두 원이 서로 합동이 아니어서 전개도가 될 수 없어요."]},{"stem":"『수학』 129쪽의 나 — 「옆면이 사다리꼴 모양이고, 두 원이 위와 아래에 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"옆면이 직사각형이 아니어서","correct":true},{"t":"두 원이 겹쳐서","mis":"M6-2-u6-X11"},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X11"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X11"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 옆면이 직사각형이 아니어서 전개도가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#21','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C3',3,'sa','auto','원기둥의 전개도에서 옆면의 가로가 25.12 cm예. 이 원기둥의 밑면의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u6-C3","difficulty":3,"kind":"sa","stem":"원기둥의 전개도에서 옆면의 가로가 25.12 cm예. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["4"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 25.12 ÷ 3.14 = 8 cm예요.","반지름은 8 ÷ 2 = 4 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 가로가 31.4 cm예. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 31.4 ÷ 3.14 = 10 cm예요.","반지름은 10 ÷ 2 = 5 cm예요."]},{"stem":"가로 37.68 cm, 세로 6 cm인 직사각형 모양의 종이를 옆면으로 하는 원기둥을 만들려고 해요. 밑면의 반지름은 몇 cm로 해야 하나요?","answer":["6"],"explanation":["옆면의 가로 37.68 cm가 밑면의 둘레가 돼요.","지름은 37.68 ÷ 3.14 = 12 cm예요.","반지름은 12 ÷ 2 = 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#22','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C5',3,'mc','auto','원기둥과 원뿔의 다른 점은 어느 것인가요?',ARRAY['M6-2-u6-X01','M6-2-u6-X14','M6-2-u6-X06']::text[],true,'{"seq":22,"concept":"M6-2-u6-C5","difficulty":3,"kind":"mc","stem":"원기둥과 원뿔의 다른 점은 어느 것인가요?","options":[{"t":"원기둥은 밑면이 2개, 원뿔은 1개예요","correct":true},{"t":"원기둥은 밑면이 원, 원뿔은 다각형이에요","mis":"M6-2-u6-X01"},{"t":"원뿔에는 옆면이 없어요","mis":"M6-2-u6-X14"},{"t":"원기둥은 높이가 없어요","mis":"M6-2-u6-X06"}],"explanation":["원기둥과 원뿔 모두 밑면이 원이고 옆면이 굽은 면이에요.","원기둥은 밑면이 2개, 원뿔은 1개예요.","원뿔에는 뾰족한 꼭짓점이 있고 원기둥에는 없어요."],"variant_rule":{"alt":[{"stem":"원기둥과 각기둥의 같은 점은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 밑면이 있어요","correct":true},{"t":"밑면의 모양이 같아요","mis":"M6-2-u6-X01"},{"t":"옆면이 모두 직사각형이에요","mis":"M6-2-u6-X01"},{"t":"꼭짓점이 있어요","mis":"M6-2-u6-X07"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."]},{"stem":"단원 평가 — 원뿔과 각뿔에 대한 설명 ㉠ 원뿔과 각뿔은 모두 밑면이 1개예요. ㉡ 원뿔의 밑면의 모양은 원이고, 각뿔의 밑면의 모양은 다각형이에요. ㉢ 원뿔과 각뿔은 모두 굽은 면이 있어요. 잘못 설명한 것은 어느 것인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M6-2-u6-X05"},{"t":"㉡","mis":"M6-2-u6-X01"},{"t":"잘못 설명한 것이 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔과 각뿔은 모두 밑면이 1개예요.","밑면 모양은 원뿔이 원, 각뿔이 다각형이에요.","각뿔의 면은 모두 평평해요 — ㉢이 잘못이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#23','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C7',4,'essay','teacher','단원 평가 — 원기둥과 구의 같은 점과 다른 점을 각각 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M6-2-u6-C7","difficulty":4,"kind":"essay","stem":"단원 평가 — 원기둥과 구의 같은 점과 다른 점을 각각 써 보세요.","answer_guide":{"answer":"예: 같은 점 — 원기둥과 구는 꼭짓점이 없다. 다른 점 — 평평한 면이 원기둥은 2개, 구는 없다(앞에서 본 모양이 원기둥은 직사각형, 구는 원이다).","scoring_points":["같은 점(꼭짓점이 없음 등)을 썼는가","다른 점(평평한 면 2개·0개 등)을 썼는가","두 입체도형의 성질을 바르게 썼는가"]},"explanation":["둘 다 꼭짓점이 없어요.","평평한 면은 원기둥 2개, 구 0개예요.","앞모양도 직사각형과 원으로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#24','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C3',4,'essay','teacher','『수학』 130쪽 활동 7 — 밑면의 지름이 3 cm, 높이가 2 cm인 원기둥의 전개도를 그리고 밑면의 반지름·옆면의 가로·옆면의 세로를 구하는 과정을 써 보세요. 친구와 확인할 때 무엇을 보아야 하는지도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u6-C3","difficulty":4,"kind":"essay","stem":"『수학』 130쪽 활동 7 — 밑면의 지름이 3 cm, 높이가 2 cm인 원기둥의 전개도를 그리고 밑면의 반지름·옆면의 가로·옆면의 세로를 구하는 과정을 써 보세요. 친구와 확인할 때 무엇을 보아야 하는지도 쓰세요.","answer_guide":{"answer":"예: 밑면의 반지름은 3 ÷ 2 = 1.5 cm, 옆면의 가로는 3 × 3.14 = 9.42 cm, 옆면의 세로는 2 cm이다. 친구와 확인할 때는 정확한 길이보다 옆면이 직사각형인지, 밑면이 옆면을 기준으로 마주 보는 위치에 합동인 모양으로 그려졌는지를 본다.","scoring_points":["반지름 1.5 cm·가로 9.42 cm를 구했는가","세로 2 cm를 썼는가","확인할 점(직사각형·마주 보는 합동인 밑면)을 썼는가"]},"explanation":["반지름 1.5 cm, 가로 9.42 cm예요.","세로 2 cm예요.","직사각형 옆면·마주 보는 합동인 밑면을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_c#25','math',6,2,'u6','','tb_g6_2_math_u6_review_c','unit_review','M6-2-u6-C3',4,'essay','teacher','단원 평가 — 밑면의 지름이 10 cm, 높이가 8 cm인 원기둥의 전개도에서 옆면의 둘레를 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u6-C3","difficulty":4,"kind":"essay","stem":"단원 평가 — 밑면의 지름이 10 cm, 높이가 8 cm인 원기둥의 전개도에서 옆면의 둘레를 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 옆면의 가로는 밑면의 둘레이므로 10 × 3.14 = 31.4 cm이고, 옆면의 세로는 높이 8 cm이다. 옆면의 둘레는 (31.4 + 8) × 2 = 78.8 cm이다.","scoring_points":["옆면의 가로 31.4 cm를 구했는가","세로 8 cm를 썼는가","둘레 78.8 cm를 구했는가"]},"explanation":["가로 10 × 3.14 = 31.4 cm예요.","세로 8 cm예요.","(31.4 + 8) × 2 = 78.8 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#1','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C1',1,'mc','auto','가 밑면이 원이고 뾰족한 뿔 모양인 입체도형 · 나 상자 모양의 각기둥 · 다 둥근 기둥 모양의 입체도형 · 라 납작한 둥근 기둥 모양의 입체도형 · 마 작은 뿔 모양이고 밑면이 원인 입체도형 · 바 밑면이 다각형인 뿔 모양의 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X01','M6-2-u6-X14']::text[],true,'{"seq":1,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"가 밑면이 원이고 뾰족한 뿔 모양인 입체도형 · 나 상자 모양의 각기둥 · 다 둥근 기둥 모양의 입체도형 · 라 납작한 둥근 기둥 모양의 입체도형 · 마 작은 뿔 모양이고 밑면이 원인 입체도형 · 바 밑면이 다각형인 뿔 모양의 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"다, 라","correct":true},{"t":"다","mis":"M6-2-u6-X05"},{"t":"나, 다, 라","mis":"M6-2-u6-X01"},{"t":"가, 다, 라, 마","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","다, 라 모두 원기둥이에요."],"variant_rule":{"alt":[{"stem":"가 둥근 기둥 모양 · 나 육각기둥 · 다 각뿔 · 라 공 모양 · 마 눕혀 놓은 둥근 기둥 모양 · 바 뿔 모양이고 밑면이 원인 입체도형 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 마","correct":true},{"t":"가","mis":"M6-2-u6-X05"},{"t":"가, 나, 마","mis":"M6-2-u6-X01"},{"t":"가, 마, 바","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 마 모두 원기둥이에요."]},{"stem":"가 위아래 두 원의 크기가 다른 통 · 나 둥근 기둥 모양의 통 · 다 서로 평행하고 합동인 두 면이 삼각형인 상자 · 라 길쭉한 둥근 기둥 모양의 통 · 마 뾰족한 뿔 모양의 상자 · 바 납작한 둥근 기둥 모양의 통 — 원기둥을 모두 찾은 것은 어느 것인가요?","options":[{"t":"나, 라, 바","correct":true},{"t":"나, 라","mis":"M6-2-u6-X02"},{"t":"가, 나, 라, 바","mis":"M6-2-u6-X02"},{"t":"나, 다, 라, 바","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","나, 라, 바 모두 원기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#2','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C5',1,'mc','auto','가 뿔 모양이고 밑면이 원인 입체도형 · 나 공 모양의 입체도형 · 다 눕혀 놓은 둥근 기둥 모양 · 라 작은 공 모양의 입체도형 · 마 눕혀 놓은 뿔 모양이고 밑면이 원인 입체도형 · 바 납작한 둥근 기둥 모양 — 원뿔을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X14','M6-2-u6-X03']::text[],true,'{"seq":2,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"가 뿔 모양이고 밑면이 원인 입체도형 · 나 공 모양의 입체도형 · 다 눕혀 놓은 둥근 기둥 모양 · 라 작은 공 모양의 입체도형 · 마 눕혀 놓은 뿔 모양이고 밑면이 원인 입체도형 · 바 납작한 둥근 기둥 모양 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 마","correct":true},{"t":"가","mis":"M6-2-u6-X14"},{"t":"가, 다, 마","mis":"M6-2-u6-X14"},{"t":"가, 나, 마","mis":"M6-2-u6-X03"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 마 모두 원뿔이에요."],"variant_rule":{"alt":[{"stem":"가 둥근 기둥 모양 · 나 육각기둥 · 다 각뿔 · 라 공 모양 · 마 눕혀 놓은 둥근 기둥 모양 · 바 뿔 모양이고 밑면이 원인 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"바","correct":true},{"t":"다, 바","mis":"M6-2-u6-X01"},{"t":"가, 바","mis":"M6-2-u6-X14"},{"t":"다","mis":"M6-2-u6-X01"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","바 하나만 원뿔이에요."]},{"stem":"가 밑면이 원이고 뾰족한 뿔 모양인 입체도형 · 나 상자 모양의 각기둥 · 다 둥근 기둥 모양의 입체도형 · 라 납작한 둥근 기둥 모양의 입체도형 · 마 작은 뿔 모양이고 밑면이 원인 입체도형 · 바 밑면이 다각형인 뿔 모양의 입체도형 — 원뿔을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 마","correct":true},{"t":"가","mis":"M6-2-u6-X14"},{"t":"가, 마, 바","mis":"M6-2-u6-X01"},{"t":"가, 라, 마","mis":"M6-2-u6-X14"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 마 모두 원뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#3','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C7',1,'mc','auto','단원 평가 — 가 공 모양 · 나 뿔 모양 · 다 둥근 기둥 모양. 어느 방향에서 보아도 모양이 같은 입체도형을 모두 찾은 것은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":3,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"단원 평가 — 가 공 모양 · 나 뿔 모양 · 다 둥근 기둥 모양. 어느 방향에서 보아도 모양이 같은 입체도형을 모두 찾은 것은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M6-2-u6-X18"},{"t":"다","mis":"M6-2-u6-X18"},{"t":"가, 다","mis":"M6-2-u6-X18"}],"explanation":["원뿔은 앞에서 보면 삼각형, 위에서 보면 원이에요.","원기둥은 앞에서 보면 직사각형, 위에서 보면 원이에요.","어느 방향에서 보아도 원인 것은 구 — 가예요."],"variant_rule":{"alt":[{"stem":"가 둥근 기둥 모양 · 나 육각기둥 · 다 각뿔 · 라 공 모양 · 마 눕혀 놓은 둥근 기둥 모양 · 바 뿔 모양이고 밑면이 원인 입체도형 — 구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"라","correct":true},{"t":"가, 라","mis":"M6-2-u6-X22"},{"t":"라, 마","mis":"M6-2-u6-X22"},{"t":"가, 라, 마","mis":"M6-2-u6-X22"}],"explanation":["구는 어느 방향에서 보아도 원인 공 모양의 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","라 하나만 구예요."]},{"stem":"가 공 모양의 입체도형 · 나 납작하게 눌린 둥근 모양 · 다 길쭉한 달걀 모양 · 라 작은 공 모양의 입체도형 — 구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가","mis":"M6-2-u6-X22"},{"t":"가, 나, 라","mis":"M6-2-u6-X22"},{"t":"가, 다, 라","mis":"M6-2-u6-X22"}],"explanation":["구는 어느 방향에서 보아도 원인 공 모양의 입체도형이에요.","보기를 하나씩 뜻에 대어 봐요.","가, 라 모두 구예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#4','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C1',1,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C1","difficulty":1,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"막대에 붙인 변","r":"높이"},{"l":"뻗어 나간 변","r":"밑면의 반지름"},{"l":"뻗어 나간 변의 2배","r":"밑면의 지름"}],"mis":"M6-2-u6-X04","explanation":["직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","막대에 붙인 변은 높이, 뻗은 변은 밑면의 반지름이에요.","밑면이 다각형이면 각기둥, 원이면 원기둥이에요."],"variant_rule":{"alt":[{"stem":"『수학』 140쪽 마무리 2 — 평면도형을 한 직선을 기준으로 한 바퀴 돌려서 만들 수 있는 입체도형을 이으세요.","pairs":[{"l":"직각삼각형","r":"원뿔"},{"l":"직사각형","r":"원기둥"},{"l":"지름을 따라 반으로 나눈 원","r":"구"}],"explanation":["직각삼각형을 돌리면 원뿔이 돼요.","직사각형을 돌리면 원기둥이 돼요.","반원을 지름을 기준으로 돌리면 구가 돼요."]},{"stem":"한 바퀴 돌릴 때 기준으로 삼는 변과 만들어지는 입체도형을 이으세요.","pairs":[{"l":"직사각형의 한 변","r":"원기둥"},{"l":"직각삼각형의 직각을 낀 한 변","r":"원뿔"},{"l":"반원의 지름","r":"구"}],"explanation":["직사각형은 한 변을 기준으로 돌려요.","직각삼각형은 직각이 있는 변을 기준으로 돌려요.","반원은 지름을 기준으로 돌려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#5','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C2',1,'mc','auto','원기둥에서 두 밑면과 만나는 굽은 면을 무엇이라고 하나요?',ARRAY['M6-2-u6-X05','M6-2-u6-X06','M6-2-u6-X15']::text[],true,'{"seq":5,"concept":"M6-2-u6-C2","difficulty":1,"kind":"mc","stem":"원기둥에서 두 밑면과 만나는 굽은 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면과 만나는 굽은 면을 옆면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."],"variant_rule":{"alt":[{"stem":"원기둥에서 두 밑면 사이의 거리를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면 사이의 거리를 높이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]},{"stem":"원뿔에서 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"모선","correct":true},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 모선이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#6','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C4',1,'mc','auto','형성 평가 — 가 직사각형의 위쪽에 크기가 같은 두 원이 나란히 · 나 직사각형의 위에 작은 원, 아래에 큰 원 · 다 세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 같은 원이 하나씩. 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u6-X12','M6-2-u6-X02']::text[],true,'{"seq":6,"concept":"M6-2-u6-C4","difficulty":1,"kind":"mc","stem":"형성 평가 — 가 직사각형의 위쪽에 크기가 같은 두 원이 나란히 · 나 직사각형의 위에 작은 원, 아래에 큰 원 · 다 세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 같은 원이 하나씩. 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M6-2-u6-X12"},{"t":"나","mis":"M6-2-u6-X02"},{"t":"가와 다","mis":"M6-2-u6-X12"}],"explanation":["가는 두 원이 겹쳐요.","나는 두 원이 합동이 아니에요.","다는 옆면이 직사각형이고 합동인 두 원이 마주 보아 전개도가 돼요."],"variant_rule":{"alt":[{"stem":"『수학』 141쪽 마무리 4 — 가 직사각형의 위쪽에 크기가 같은 두 원이 나란히 · 나 사다리꼴 옆면의 위와 아래에 원 · 다 세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 같은 원이 하나씩 — 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M6-2-u6-X12"},{"t":"나","mis":"M6-2-u6-X11"},{"t":"가와 다","mis":"M6-2-u6-X12"}],"explanation":["가는 두 원이 겹쳐서 안 돼요.","나는 옆면이 직사각형이 아니어서 안 돼요.","다는 옆면이 직사각형이고 합동인 두 원이 마주 보아 전개도가 돼요."]},{"stem":"종이 상자는 이물질을 없앤 다음 납작하게 부피를 줄여 분리배출해요. 상자를 잘라 펼친 가 · 나 · 다 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요? (가 직사각형의 위와 아래에 크기가 같은 원이 하나씩 · 나 직사각형의 왼쪽에 크기가 같은 두 원이 나란히 · 다 직사각형의 위에 큰 원, 아래에 작은 원)","options":[{"t":"가","correct":true},{"t":"나","mis":"M6-2-u6-X12"},{"t":"다","mis":"M6-2-u6-X02"},{"t":"셋 다 될 수 있어요","mis":"M6-2-u6-X02"}],"explanation":["나는 두 원이 같은 쪽에 있어 접으면 겹쳐요.","다는 두 원이 서로 합동이 아니에요.","그래서 원기둥의 전개도는 가예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#7','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C5',1,'mc','auto','단원 평가 — 원기둥과 원뿔에 대한 설명 ㉠ 원기둥과 원뿔의 밑면은 모두 원이에요. ㉡ 원기둥과 원뿔의 밑면은 각각 2개예요. 잘못 설명한 것은 어느 것인가요?',ARRAY['M6-2-u6-X19','M6-2-u6-X05']::text[],true,'{"seq":7,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"단원 평가 — 원기둥과 원뿔에 대한 설명 ㉠ 원기둥과 원뿔의 밑면은 모두 원이에요. ㉡ 원기둥과 원뿔의 밑면은 각각 2개예요. 잘못 설명한 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u6-X19"},{"t":"둘 다 맞아요","mis":"M6-2-u6-X05"},{"t":"둘 다 틀려요","mis":"M6-2-u6-X19"}],"explanation":["원기둥과 원뿔의 밑면은 모두 원이에요 — ㉠은 맞아요.","원기둥의 밑면은 2개, 원뿔은 1개예요.","그래서 잘못 설명한 것은 ㉡이에요."],"variant_rule":{"alt":[{"stem":"『수학』 142쪽 마무리 6 — ㉠ 원기둥의 밑면은 1개예요. ㉡ 원기둥의 전개도에서 옆면은 원이에요. ㉢ 원뿔의 높이는 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요. ㉣ 구의 중심은 1개이고, 구의 반지름은 무수히 많아요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"M6-2-u6-X05"},{"t":"㉡","mis":"M6-2-u6-X13"},{"t":"㉢","mis":"M6-2-u6-X15"}],"explanation":["원기둥의 밑면은 2개, 전개도의 옆면은 직사각형이에요.","㉢은 높이가 아니라 모선의 뜻이에요.","바르게 설명한 것은 ㉣이에요."]},{"stem":"『수학익힘』 93쪽 — ㉠ 구는 꼭짓점이 없어요. ㉡ 구는 밑면이 2개 있어요. ㉢ 구의 중심은 1개예요. ㉣ 구의 반지름은 무수히 많고 그 길이가 모두 달라요. 바르게 설명한 것을 모두 찾은 것은 어느 것인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠, ㉡","mis":"M6-2-u6-X05"},{"t":"㉢, ㉣","mis":"M6-2-u6-X17"},{"t":"㉠, ㉢, ㉣","mis":"M6-2-u6-X17"}],"explanation":["구에는 밑면이 없어요 — ㉡은 틀려요.","구의 반지름은 길이가 모두 같아요 — ㉣은 틀려요.","바른 것은 ㉠, ㉢이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#8','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C2',1,'sa','auto','원기둥의 옆면은 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C2","difficulty":1,"kind":"sa","stem":"원기둥의 옆면은 몇 개인가요?","answer":["1"],"explanation":["원기둥·원뿔·구의 정의와 구성 요소를 떠올려요.","두 밑면과 만나는 굽은 면 하나 — 1개예요.","원기둥 밑면 2 · 원뿔 밑면 1 · 구의 중심 1이에요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"원기둥의 밑면은 몇 개인가요?","answer":["2"],"explanation":["원기둥·원뿔·구의 정의와 구성 요소를 떠올려요.","서로 평행하고 합동인 두 원 — 2개예요.","원기둥 밑면 2 · 원뿔 밑면 1 · 구의 중심 1이에요."]},{"stem":"원뿔의 밑면은 몇 개인가요?","answer":["1"],"explanation":["원기둥·원뿔·구의 정의와 구성 요소를 떠올려요.","한 원을 면으로 해요 — 1개예요.","원기둥 밑면 2 · 원뿔 밑면 1 · 구의 중심 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#9','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C3',2,'mc','auto','단원 평가 — 밑면의 반지름이 0.5 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?',ARRAY['M6-2-u6-X08','M6-2-u6-X09']::text[],true,'{"seq":9,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"단원 평가 — 밑면의 반지름이 0.5 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"3.14 cm","correct":true},{"t":"1 cm","mis":"M6-2-u6-X08"},{"t":"1.57 cm","mis":"M6-2-u6-X08"},{"t":"3 cm","mis":"M6-2-u6-X09"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 1 cm예요.","1 × 3.14 = 3.14 cm예요."],"variant_rule":{"alt":[{"stem":"『수학』 141쪽 마무리 5 — 밑면의 지름이 2 cm, 높이가 3 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"6.28 cm","correct":true},{"t":"2 cm","mis":"M6-2-u6-X08"},{"t":"3.14 cm","mis":"M6-2-u6-X08"},{"t":"3 cm","mis":"M6-2-u6-X09"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 2 cm예요.","2 × 3.14 = 6.28 cm예요."]},{"stem":"『수학』 130쪽 활동 6 — 밑면의 반지름이 1 cm, 높이가 2 cm인 원기둥의 전개도를 그리고 각 부분의 길이를 나타내요. 옆면의 가로는 몇 cm로 나타내야 하나요?","options":[{"t":"6.28 cm","correct":true},{"t":"2 cm","mis":"M6-2-u6-X08"},{"t":"3.14 cm","mis":"M6-2-u6-X08"},{"t":"12.56 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 2 cm예요.","2 × 3.14 = 6.28 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#10','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C3',2,'sa','auto','원기둥의 전개도에서 옆면의 가로가 6.28 cm, 세로가 2 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"원기둥의 전개도에서 옆면의 가로가 6.28 cm, 세로가 2 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["2"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 2 cm는 높이예요.","6.28 ÷ 3.14 = 2 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 4 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 4 cm는 높이예요.","25.12 ÷ 3.14 = 8 cm예요."]},{"stem":"원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (밑면의 둘레) ÷ 3.14예요. 세로 5 cm는 높이예요.","18.84 ÷ 3.14 = 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#11','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C1',2,'sa','auto','가로 9 cm, 세로 4 cm인 직사각형을 길이가 4 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":11,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 4 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 높이는 몇 cm인가요?","answer":["4"],"explanation":["기준으로 한 4 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 9 cm 변은 밑면의 반지름이 돼요.","그래서 높이는 4 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 9 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["기준으로 한 9 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 4 cm 변은 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 4 × 2 = 8 cm예요."]},{"stem":"가로 9 cm, 세로 4 cm인 직사각형을 길이가 9 cm인 변을 기준으로 한 바퀴 돌려서 원기둥을 만들었어요. 이 원기둥의 높이는 몇 cm인가요?","answer":["9"],"explanation":["기준으로 한 9 cm 변은 원기둥의 높이가 돼요.","뻗어 나간 4 cm 변은 밑면의 반지름이 돼요.","그래서 높이는 9 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#12','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C5',2,'sa','auto','『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 지름과 높이의 합은 몇 cm인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["19"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","지름 14 cm와 높이 5 cm — 14 + 5 = 19 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 밑면의 지름은 몇 cm인가요?","answer":["14"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","지름은 7 × 2 = 14 cm예요."]},{"stem":"『수학익힘』 91쪽 — 직각을 낀 두 변이 5 cm, 7 cm인 직각삼각형을 5 cm인 변을 기준으로 한 바퀴 돌려서 만든 입체도형의 높이는 몇 cm인가요?","answer":["5"],"explanation":["기준으로 한 5 cm 변은 원뿔의 높이가 돼요.","뻗어 나간 7 cm 변(직각삼각형의 밑변)은 밑면의 반지름이 돼요.","그래서 높이는 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#13','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C6',2,'sa','auto','원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 8 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 10 cm, 밑면의 반지름은 6 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":13,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 8 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 10 cm, 밑면의 반지름은 6 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["10"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 모선의 길이는 10 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 13 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["12"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 높이는 12 cm예요 — 13 cm는 모선이에요."]},{"stem":"원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분은 4 cm, 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 5 cm, 밑면의 반지름은 3 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["5"],"explanation":["높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분은 모선이에요.","그래서 모선의 길이는 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#14','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C7',2,'sa','auto','반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u6-C7","difficulty":2,"kind":"sa","stem":"반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["16"],"explanation":["돌리기 전 원의 반지름이 구의 반지름 — 8 cm예요.","구의 지름은 반지름의 2배예요.","8 × 2 = 16 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["돌리기 전 원의 반지름은 구의 반지름이 돼요.","반원의 반지름이 8 cm예요.","그래서 구의 반지름은 8 cm예요."]},{"stem":"반지름이 6 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["12"],"explanation":["돌리기 전 원의 반지름이 구의 반지름 — 6 cm예요.","구의 지름은 반지름의 2배예요.","6 × 2 = 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#15','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C3',2,'sa','auto','밑면의 반지름이 4 cm, 높이가 8 cm인 원기둥의 전개도에서 옆면의 세로는 몇 cm인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"밑면의 반지름이 4 cm, 높이가 8 cm인 원기둥의 전개도에서 옆면의 세로는 몇 cm인가요?","answer":["8"],"explanation":["옆면의 세로는 두 밑면 사이를 이어요.","두 밑면 사이의 거리가 원기둥의 높이예요.","그래서 옆면의 세로는 높이와 같은 8 cm예요."],"mis":"M6-2-u6-X09","variant_rule":{"alt":[{"stem":"『수학익힘』 87쪽의 통조림은 원기둥 모양이에요. 밑면의 지름이 8 cm이고 두 밑면 사이의 거리가 3 cm예요. 이 통조림의 높이는 몇 cm인가요?","answer":["3"],"explanation":["원기둥의 높이는 두 밑면 사이의 거리예요.","밑면의 지름 8 cm는 높이가 아니에요.","그래서 높이는 3 cm예요."]},{"stem":"『수학익힘』 87쪽의 원기둥 모양 물건이 눕혀 놓여 있어요. 밑면의 지름은 6 cm이고, 두 밑면 사이의 거리는 12 cm예요. 이 물건의 높이는 몇 cm인가요?","answer":["12"],"explanation":["눕혀 놓아도 서로 평행하고 합동인 두 원이 밑면이에요.","높이는 두 밑면 사이의 거리예요 — 바닥에서 위까지의 길이가 아니에요.","그래서 높이는 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#16','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C8',2,'mc','auto','원뿔을 위에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":16,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"원뿔을 위에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 위에서 본 모양은 원이에요."],"variant_rule":{"alt":[{"stem":"원뿔을 옆에서 본 모양은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 옆에서 본 모양은 삼각형이에요."]},{"stem":"원기둥을 옆에서 본 모양은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 옆에서 본 모양은 직사각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#17','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C7',3,'ox','auto','구를 앞에서 본 모양은 반원이에요.',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":17,"concept":"M6-2-u6-C7","difficulty":3,"kind":"ox","stem":"구를 앞에서 본 모양은 반원이에요.","answer":"X","reason_options":[{"t":"구는 어느 방향에서 보아도 원이기 때문에","correct":true},{"t":"반원을 돌려 만들었기 때문에","mis":"M6-2-u6-X18"}],"mis":"M6-2-u6-X18","explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."],"variant_rule":{"alt":[{"stem":"『수학』 142쪽 마무리 7 — 원기둥, 원뿔, 구를 옆에서 본 모양은 서로 같아요.","answer":"X","reason_options":[{"t":"옆에서 본 모양이 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이라 서로 다르기 때문에","correct":true},{"t":"셋 다 위에서 본 모양이 원이기 때문에","mis":"M6-2-u6-X18"}],"explanation":["원기둥을 옆에서 보면 직사각형이에요.","원뿔은 삼각형, 구는 원이에요.","그래서 옆에서 본 모양은 서로 달라요."]},{"stem":"원기둥·원뿔·구를 위에서 본 모양은 모두 원이에요.","answer":"O","reason_options":[{"t":"세 입체도형 모두 위에서 보면 둥근 테두리만 보이기 때문에","correct":true},{"t":"셋 다 앞에서 본 모양과 위에서 본 모양이 같기 때문에","mis":"M6-2-u6-X18"}],"explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#18','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C8',3,'mc','auto','밑면의 지름이 10 cm, 높이가 11 cm인 원기둥을 앞에서 보았어요. 앞에서 본 직사각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X08']::text[],true,'{"seq":18,"concept":"M6-2-u6-C8","difficulty":3,"kind":"mc","stem":"밑면의 지름이 10 cm, 높이가 11 cm인 원기둥을 앞에서 보았어요. 앞에서 본 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"110 cm²","correct":true},{"t":"55 cm²","mis":"M6-2-u6-X20"},{"t":"345.4 cm²","mis":"M6-2-u6-X08"},{"t":"42 cm²","mis":"M6-2-u6-X20"}],"explanation":["원기둥을 앞에서 보면 직사각형이에요.","가로는 밑면의 지름 10 cm, 세로는 높이 11 cm예요.","10 × 11 = 110 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"108 cm²","correct":true},{"t":"216 cm²","mis":"M6-2-u6-X20"},{"t":"54 cm²","mis":"M6-2-u6-X20"},{"t":"135 cm²","mis":"M6-2-u6-X15"}],"explanation":["앞에서 본 삼각형의 밑변은 밑면의 지름 18 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선 15 cm는 쓰지 않아요.","18 × 12 ÷ 2 = 108 cm²예요."]},{"stem":"밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"48 cm²","correct":true},{"t":"96 cm²","mis":"M6-2-u6-X20"},{"t":"24 cm²","mis":"M6-2-u6-X20"},{"t":"60 cm²","mis":"M6-2-u6-X15"}],"explanation":["앞에서 본 삼각형의 밑변은 밑면의 지름 12 cm, 높이는 원뿔의 높이 8 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선 10 cm는 쓰지 않아요.","12 × 8 ÷ 2 = 48 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#19','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C8',3,'sa','auto','원뿔 모양 모자는 밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm예요. 원기둥 모양 모자의 높이가 6 cm이고 두 모자를 앞에서 본 모양의 넓이가 같을 때, 원기둥 모양 모자의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":19,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"원뿔 모양 모자는 밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm예요. 원기둥 모양 모자의 높이가 6 cm이고 두 모자를 앞에서 본 모양의 넓이가 같을 때, 원기둥 모양 모자의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["원뿔을 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥을 앞에서 본 직사각형도 48 cm² — 세로는 높이 6 cm예요.","가로(지름)는 48 ÷ 6 = 8 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"세계 전통 의상 체험관의 원뿔 모양 모자는 밑면의 반지름이 9 cm, 높이가 12 cm, 모선의 길이가 15 cm예요. 원기둥 모양 모자의 높이는 9 cm예요. 두 모자를 앞에서 본 모양의 넓이가 같을 때 원기둥 모양 모자의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["원뿔을 앞에서 본 삼각형의 밑변은 9 × 2 = 18 cm, 높이는 12 cm — 넓이는 18 × 12 ÷ 2 = 108 cm²예요.","원기둥을 앞에서 본 직사각형도 108 cm² — 세로는 높이 9 cm예요.","가로(지름)는 108 ÷ 9 = 12 cm예요."]},{"stem":"원뿔 모양 모자는 밑면의 반지름이 6 cm, 높이가 8 cm, 모선의 길이가 10 cm예요. 원기둥 모양 모자는 밑면의 반지름이 4 cm예요. 두 모자를 앞에서 본 모양의 넓이가 같을 때 원기둥 모양 모자의 높이는 몇 cm인가요?","answer":["6"],"explanation":["원뿔을 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥을 앞에서 본 직사각형의 가로는 밑면의 지름 4 × 2 = 8 cm예요.","세로(높이)는 48 ÷ 8 = 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#20','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C4',3,'mc','auto','형성 평가의 나 — 「직사각형의 위에 작은 원, 아래에 큰 원이 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":20,"concept":"M6-2-u6-C4","difficulty":3,"kind":"mc","stem":"형성 평가의 나 — 「직사각형의 위에 작은 원, 아래에 큰 원이 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 원이 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 두 원이 서로 합동이 아니어서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"『수학』 129쪽의 나 — 「옆면이 사다리꼴 모양이고, 두 원이 위와 아래에 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"옆면이 직사각형이 아니어서","correct":true},{"t":"두 원이 겹쳐서","mis":"M6-2-u6-X11"},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X11"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X11"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 옆면이 직사각형이 아니어서 전개도가 될 수 없어요."]},{"stem":"『수학』 129쪽의 라 — 「세로로 긴 직사각형의 왼쪽과 오른쪽에 크기가 다른 두 원이 붙은 그림」은 원기둥의 전개도가 될 수 없어요. 까닭은 무엇인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 원이 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도는 옆면이 직사각형, 두 밑면이 합동인 원이어야 해요.","두 밑면은 옆면을 기준으로 마주 보는 위치에 있어야 해요.","이 그림은 두 원이 서로 합동이 아니어서 전개도가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#21','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C3',3,'sa','auto','원기둥의 전개도에서 옆면의 가로가 31.4 cm예. 이 원기둥의 밑면의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u6-C3","difficulty":3,"kind":"sa","stem":"원기둥의 전개도에서 옆면의 가로가 31.4 cm예. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 31.4 ÷ 3.14 = 10 cm예요.","반지름은 10 ÷ 2 = 5 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"가로 37.68 cm, 세로 6 cm인 직사각형 모양의 종이를 옆면으로 하는 원기둥을 만들려고 해요. 밑면의 반지름은 몇 cm로 해야 하나요?","answer":["6"],"explanation":["옆면의 가로 37.68 cm가 밑면의 둘레가 돼요.","지름은 37.68 ÷ 3.14 = 12 cm예요.","반지름은 12 ÷ 2 = 6 cm예요."]},{"stem":"원기둥의 전개도에서 옆면의 가로가 18.84 cm예. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 18.84 ÷ 3.14 = 6 cm예요.","반지름은 6 ÷ 2 = 3 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#22','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C2',3,'mc','auto','원기둥과 각기둥의 같은 점은 어느 것인가요?',ARRAY['M6-2-u6-X01','M6-2-u6-X07']::text[],true,'{"seq":22,"concept":"M6-2-u6-C2","difficulty":3,"kind":"mc","stem":"원기둥과 각기둥의 같은 점은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 밑면이 있어요","correct":true},{"t":"밑면의 모양이 같아요","mis":"M6-2-u6-X01"},{"t":"옆면이 모두 직사각형이에요","mis":"M6-2-u6-X01"},{"t":"꼭짓점이 있어요","mis":"M6-2-u6-X07"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."],"variant_rule":{"alt":[{"stem":"단원 평가 — 원뿔과 각뿔에 대한 설명 ㉠ 원뿔과 각뿔은 모두 밑면이 1개예요. ㉡ 원뿔의 밑면의 모양은 원이고, 각뿔의 밑면의 모양은 다각형이에요. ㉢ 원뿔과 각뿔은 모두 굽은 면이 있어요. 잘못 설명한 것은 어느 것인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M6-2-u6-X05"},{"t":"㉡","mis":"M6-2-u6-X01"},{"t":"잘못 설명한 것이 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔과 각뿔은 모두 밑면이 1개예요.","밑면 모양은 원뿔이 원, 각뿔이 다각형이에요.","각뿔의 면은 모두 평평해요 — ㉢이 잘못이에요."]},{"stem":"단원 평가 — 가는 원뿔, 나는 오각뿔이에요. ㉠ 가는 원뿔이고 나는 오각뿔이에요. ㉡ 가와 나는 모두 꼭짓점이 1개뿐이에요. ㉢ 가와 나는 모두 뿔 모양이에요. 잘못 설명한 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u6-X19"},{"t":"㉢","mis":"M6-2-u6-X14"},{"t":"잘못 설명한 것이 없어요","mis":"M6-2-u6-X07"}],"explanation":["원뿔의 꼭짓점은 1개예요.","오각뿔은 밑면의 꼭짓점 5개와 각뿔의 꼭짓점 1개 — 6개예요.","그래서 ㉡이 잘못이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#23','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C6',4,'essay','teacher','『수학』 141쪽 마무리 3과 142쪽 마무리 6에서 원뿔의 높이와 모선을 바꾸어 쓰는 실수가 많아요. 원뿔의 높이와 모선의 뜻을 각각 쓰고, 어느 것이 더 긴지 까닭과 함께 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M6-2-u6-C6","difficulty":4,"kind":"essay","stem":"『수학』 141쪽 마무리 3과 142쪽 마무리 6에서 원뿔의 높이와 모선을 바꾸어 쓰는 실수가 많아요. 원뿔의 높이와 모선의 뜻을 각각 쓰고, 어느 것이 더 긴지 까닭과 함께 설명해 보세요.","answer_guide":{"answer":"예: 모선은 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이고, 높이는 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이이다. 모선은 둘레까지 비스듬히 가고 높이는 곧게 내려가므로 모선이 높이보다 길다.","scoring_points":["모선의 뜻을 썼는가","높이의 뜻(수직으로 내린 선분의 길이)을 썼는가","모선이 더 긴 까닭을 썼는가"]},"explanation":["모선 = 꼭짓점과 밑면 둘레의 한 점을 이은 선분이에요.","높이 = 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","비스듬한 모선이 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#24','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C3',4,'essay','teacher','『수학익힘』 89쪽 — 밑면의 반지름이 1.5 cm, 높이가 3 cm인 원기둥의 전개도를 완성하는 방법을 쓰고, 각 부분의 길이를 구해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u6-C3","difficulty":4,"kind":"essay","stem":"『수학익힘』 89쪽 — 밑면의 반지름이 1.5 cm, 높이가 3 cm인 원기둥의 전개도를 완성하는 방법을 쓰고, 각 부분의 길이를 구해 보세요.","answer_guide":{"answer":"예: 높이 3 cm가 되도록 옆면을 완성하고, 그려져 있는 밑면과 마주 보는 위치에 밑면을 하나 더 그린다. 밑면의 반지름은 1.5 cm, 옆면의 가로는 3 × 3.14 = 9.42 cm, 옆면의 세로는 3 cm이다.","scoring_points":["옆면 완성·밑면을 마주 보게 그린다고 썼는가","가로 9.42 cm를 구했는가","반지름 1.5 cm·세로 3 cm를 썼는가"]},"explanation":["옆면을 완성하고 밑면을 마주 보게 그려요.","가로 3 × 3.14 = 9.42 cm예요.","반지름 1.5 cm, 세로 3 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u6_review_d#25','math',6,2,'u6','','tb_g6_2_math_u6_review_d','unit_review','M6-2-u6-C1',4,'essay','teacher','『수학』 140쪽 마무리 1 — 원기둥(가·마), 원뿔(바), 구(라)를 찾았어요. 나(육각기둥)와 다(각뿔)가 원기둥이나 원뿔이 아닌 까닭을 밑면의 모양으로 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u6-C1","difficulty":4,"kind":"essay","stem":"『수학』 140쪽 마무리 1 — 원기둥(가·마), 원뿔(바), 구(라)를 찾았어요. 나(육각기둥)와 다(각뿔)가 원기둥이나 원뿔이 아닌 까닭을 밑면의 모양으로 설명해 보세요.","answer_guide":{"answer":"예: 나는 서로 평행하고 합동인 두 면이 원이 아니라 육각형이어서 원기둥이 아니다. 다는 뿔 모양이지만 밑면이 원이 아니라 다각형이어서 원뿔이 아니다.","scoring_points":["나 — 두 밑면이 다각형(육각형)임을 썼는가","다 — 밑면이 원이 아님을 썼는가","원기둥·원뿔의 뜻에 대어 설명했는가"]},"explanation":["나는 밑면이 육각형이에요.","다는 밑면이 다각형이에요.","원기둥·원뿔은 밑면이 원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
